'use client';

import { useDocumentTitle } from '@/hooks/useDocumentTitle';

import { useState, useEffect, Fragment } from 'react';
import { apiFetch, apiMutate, reportError } from '@/lib/api';
import { useTranslations } from 'next-intl';

interface SyncSummary {
  pending: number;
  processed: number;
  failed: number;
  total: number;
}

interface TypeBreakdown {
  eventType: string;
  total: number;
  pending: number;
  processed: number;
  failed: number;
}

interface OutboxEvent {
  outboxId: string;
  aggregateType: string;
  aggregateId: string;
  eventType: string;
  payload: any;
  createdOn: string;
  processedAt: string | null;
  lastError: string | null;
}

interface SyncData {
  summary: SyncSummary;
  byType: TypeBreakdown[];
  recentEvents: OutboxEvent[];
}

export default function EventQueueDashboard() {
  const t = useTranslations('admin.eventQueue');
  useDocumentTitle(t('title'));
  
  const [data, setData] = useState<SyncData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [autoRefresh, setAutoRefresh] = useState(false);

  // Detail drawer state
  const [drawerType, setDrawerType] = useState<string | null>(null);
  const [drawerEvents, setDrawerEvents] = useState<OutboxEvent[]>([]);
  const [drawerLoading, setDrawerLoading] = useState(false);
  const [drawerExpandedId, setDrawerExpandedId] = useState<string | null>(null);

  // Clearing state
  const [clearing, setClearing] = useState<string | null>(null);

  const loadData = async () => {
    try {
      const res = await apiFetch<SyncData>('/api/settings/external-sync?limit=100');
      setData(res);
      setError('');
    } catch (err: any) {
      setError(err instanceof Error ? err.message : t('errors.loadFailed'));
      reportError(err, 'EventQueueDashboard_loadData');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  useEffect(() => {
    if (!autoRefresh) return;
    const interval = setInterval(loadData, 5000);
    return () => clearInterval(interval);
  }, [autoRefresh]);

  const handleViewEvents = async (eventType: string) => {
    if (drawerType === eventType) {
      setDrawerType(null);
      return;
    }
    setDrawerType(eventType);
    setDrawerLoading(true);
    setDrawerExpandedId(null);
    try {
      const res = await apiFetch<{ events: OutboxEvent[] }>(
        `/api/settings/external-sync/events?type=${encodeURIComponent(eventType)}&status=failed&limit=50`,
      );
      setDrawerEvents(res.events);
    } catch (err) {
      setDrawerEvents([]);
      reportError(err, 'EventQueueDashboard_handleViewEvents');
    } finally {
      setDrawerLoading(false);
    }
  };

  const handleClearEvents = async (eventType: string) => {
    if (!confirm(t('confirmClear', { type: eventType }))) return;
    setClearing(eventType);
    try {
      await apiMutate(
        `/api/settings/external-sync/events?type=${encodeURIComponent(eventType)}`,
        'DELETE',
      );
      // Close drawer if viewing that type
      if (drawerType === eventType) {
        setDrawerType(null);
        setDrawerEvents([]);
      }
      await loadData();
    } catch (err: any) {
      setError(err instanceof Error ? err.message : t('errors.clearFailed'));
      reportError(err, 'EventQueueDashboard_handleClearEvents');
    } finally {
      setClearing(null);
    }
  };

  if (loading) {
    return (
      <>
        <div className="flex items-center justify-center flex-1">
          <p style={{ color: 'var(--text-muted)' }}>{t('loading')}</p>
        </div>
      </>
    );
  }

  return (
    <>
      <div style={{ maxWidth: 1100, margin: '0 auto' }}>
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <div>
            <h1 className="text-2xl font-bold">{t('title')}</h1>
            <p className="text-sm mt-1" style={{ color: 'var(--text-muted)' }}>
              {t('subtitle')}
            </p>
          </div>
          <div className="flex gap-2 items-center">
            <label className="flex items-center gap-2 text-xs" style={{ color: 'var(--text-muted)' }}>
              <input
                type="checkbox"
                checked={autoRefresh}
                onChange={() => setAutoRefresh(!autoRefresh)}
              />
              {t('autoRefresh')}
            </label>
            <button className="btn btn-secondary btn-sm" onClick={loadData}>
              {/* eslint-disable-next-line i18next/no-literal-string */}
              Γå╗ {t('refresh')}
            </button>
          </div>
        </div>

        {error && (
          <div
            className="mb-4 px-4 py-3 rounded-lg text-sm"
            style={{
              background: 'rgba(239, 68, 68, 0.1)',
              border: '1px solid rgba(239, 68, 68, 0.3)',
              color: '#f87171',
            }}
          >
            {error}
          </div>
        )}

        {data && (
          <>
            {/* Summary Cards */}
            <div className="grid grid-cols-4 gap-4 mb-6">
              <div
                className="card"
                style={{
                  textAlign: 'center',
                  background: data.summary.pending > 0 ? 'rgba(245, 158, 11, 0.08)' : undefined,
                  border: data.summary.pending > 0 ? '1px solid rgba(245, 158, 11, 0.3)' : undefined,
                }}
              >
                <div className="text-xs font-semibold mb-2" style={{ color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                  {t('summary.pending')}
                </div>
                <div
                  className="text-3xl font-bold"
                  style={{ color: data.summary.pending > 0 ? '#f59e0b' : 'var(--text-primary)', fontVariantNumeric: 'tabular-nums' }}
                >
                  {data.summary.pending}
                </div>
              </div>
              <div className="card" style={{ textAlign: 'center' }}>
                <div className="text-xs font-semibold mb-2" style={{ color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                  {t('summary.processed')}
                </div>
                <div className="text-3xl font-bold" style={{ color: '#4ade80', fontVariantNumeric: 'tabular-nums' }}>
                  {data.summary.processed}
                </div>
              </div>
              <div
                className="card"
                style={{
                  textAlign: 'center',
                  background: data.summary.failed > 0 ? 'rgba(239, 68, 68, 0.08)' : undefined,
                  border: data.summary.failed > 0 ? '1px solid rgba(239, 68, 68, 0.3)' : undefined,
                }}
              >
                <div className="text-xs font-semibold mb-2" style={{ color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                  {t('summary.failed')}
                </div>
                <div
                  className="text-3xl font-bold"
                  style={{ color: data.summary.failed > 0 ? '#ef4444' : 'var(--text-primary)', fontVariantNumeric: 'tabular-nums' }}
                >
                  {data.summary.failed}
                </div>
              </div>
              <div className="card" style={{ textAlign: 'center' }}>
                <div className="text-xs font-semibold mb-2" style={{ color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                  {t('summary.total')}
                </div>
                <div className="text-3xl font-bold" style={{ fontVariantNumeric: 'tabular-nums' }}>
                  {data.summary.total}
                </div>
              </div>
            </div>

            {/* By-type breakdown */}
            {data.byType.length > 0 && (
              <div className="card mb-6">
                <h3
                  className="text-sm font-semibold mb-4"
                  style={{ color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em' }}
                >
                  {t('eventTypes')}
                </h3>
                <table className="table-lines">
                  <thead>
                    <tr>
                      <th>{t('columns.eventType')}</th>
                      <th style={{ width: 80, textAlign: 'right' }}>{t('columns.total')}</th>
                      <th style={{ width: 80, textAlign: 'right' }}>{t('columns.pending')}</th>
                      <th style={{ width: 80, textAlign: 'right' }}>{t('columns.failed')}</th>
                      <th style={{ width: 80, textAlign: 'right' }}>{t('columns.processed')}</th>
                      <th style={{ width: 110 }}>{t('columns.status')}</th>
                      <th style={{ width: 160, textAlign: 'right' }}>{t('columns.actions')}</th>
                    </tr>
                  </thead>
                  <tbody>
                    {data.byType.map((row) => (
                      <Fragment key={row.eventType}>
                        <tr>
                          <td>
                            <span
                              style={{
                                padding: '2px 8px',
                                borderRadius: 4,
                                fontSize: 12,
                                fontWeight: 600,
                                fontFamily: 'monospace',
                                background: 'rgba(59, 130, 246, 0.1)',
                                color: 'var(--accent)',
                              }}
                            >
                              {row.eventType}
                            </span>
                          </td>
                          <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{row.total}</td>
                          <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', color: row.pending > 0 ? '#f59e0b' : undefined }}>
                            {row.pending}
                          </td>
                          <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', color: row.failed > 0 ? '#ef4444' : undefined }}>
                            {row.failed}
                          </td>
                          <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{row.processed}</td>
                          <td>
                            {row.failed > 0 ? (
                               // eslint-disable-next-line i18next/no-literal-string
                               <span style={{ color: '#ef4444', fontWeight: 700, fontSize: 11 }}>Γ£ò {t('status.errors', { count: row.failed })}</span>
                            ) : row.pending === 0 ? (
                              // eslint-disable-next-line i18next/no-literal-string
                              <span style={{ color: '#4ade80', fontWeight: 700, fontSize: 11 }}>Γ£ô {t('status.allSynced')}</span>
                            ) : (
                              // eslint-disable-next-line i18next/no-literal-string
                              <span style={{ color: '#f59e0b', fontWeight: 700, fontSize: 11 }}>ΓÅ│ {t('status.pending', { count: row.pending })}</span>
                            )}
                          </td>
                          <td style={{ textAlign: 'right' }}>
                            <div className="flex gap-1 justify-end">
                              <button
                                className="btn btn-secondary btn-sm"
                                style={{ fontSize: 10 }}
                                onClick={() => handleViewEvents(row.eventType)}
                              >
                                {drawerType === row.eventType ? t('actions.hide') : t('actions.view')}
                              </button>
                              {row.pending > 0 && (
                                <button
                                  className="btn btn-sm"
                                  style={{
                                    fontSize: 10,
                                    background: 'rgba(239, 68, 68, 0.1)',
                                    color: '#f87171',
                                    border: '1px solid rgba(239, 68, 68, 0.3)',
                                  }}
                                  disabled={clearing === row.eventType}
                                  onClick={() => handleClearEvents(row.eventType)}
                                >
                                  {clearing === row.eventType ? 'ΓÇª' : `Γ£ò ${t('actions.clear')}`}
                                </button>
                              )}
                            </div>
                          </td>
                        </tr>

                        {/* Inline event drawer */}
                        {drawerType === row.eventType && (
                          <tr>
                            <td colSpan={6} style={{ padding: 0 }}>
                              <div
                                style={{
                                  background: 'var(--bg-primary)',
                                  border: '1px solid var(--border)',
                                  borderRadius: 6,
                                  margin: '4px 8px 8px',
                                  maxHeight: 400,
                                  overflowY: 'auto',
                                }}
                              >
                                {drawerLoading ? (
                                  <div style={{ padding: 16, textAlign: 'center', color: 'var(--text-muted)', fontSize: 12 }}>
                                    {t('drawer.loading')}
                                  </div>
                                ) : drawerEvents.length === 0 ? (
                                  <div style={{ padding: 16, textAlign: 'center', color: 'var(--text-muted)', fontSize: 12 }}>
                                    {t('drawer.noEvents')}
                                  </div>
                                ) : (
                                  <table className="table-lines" style={{ margin: 0 }}>
                                    <thead>
                                      <tr>
                                        <th style={{ width: 170, fontSize: 10 }}>{t('columns.timestamp')}</th>
                                        <th style={{ fontSize: 10 }}>{t('columns.aggregate')}</th>
                                        <th style={{ width: 80, fontSize: 10 }}>{t('columns.status')}</th>
                                        <th style={{ width: 60, fontSize: 10 }}>{t('columns.payload')}</th>
                                      </tr>
                                    </thead>
                                    <tbody>
                                      {drawerEvents.map((evt) => (
                                        <Fragment key={evt.outboxId}>
                                          <tr>
                                            <td style={{ fontSize: 10, fontVariantNumeric: 'tabular-nums', color: 'var(--text-muted)' }}>
                                              {new Date(evt.createdOn).toLocaleString()}
                                            </td>
                                            <td style={{ fontSize: 10, fontFamily: 'monospace', color: 'var(--text-secondary)' }}>
                                              {evt.aggregateType}:{evt.aggregateId.substring(0, 12)}
                                            </td>
                                            <td style={{ fontSize: 10 }}>
                                              {evt.lastError ? (
                                                  // eslint-disable-next-line i18next/no-literal-string
                                                  <span style={{ color: '#ef4444', fontWeight: 700 }} title={evt.lastError}>Γ£ò</span>
                                                ) : evt.processedAt ? (
                                                  // eslint-disable-next-line i18next/no-literal-string
                                                  <span style={{ color: '#4ade80', fontWeight: 700 }}>Γ£ô</span>
                                                ) : (
                                                  // eslint-disable-next-line i18next/no-literal-string
                                                  <span style={{ color: '#f59e0b', fontWeight: 700 }}>ΓÅ│</span>
                                                )}
                                            </td>
                                            <td>
                                              <button
                                                className="btn btn-secondary btn-sm"
                                                style={{ fontSize: 9, padding: '1px 4px' }}
                                                onClick={() =>
                                                  setDrawerExpandedId(
                                                    drawerExpandedId === evt.outboxId ? null : evt.outboxId,
                                                  )
                                                }
                                              >
                                                {drawerExpandedId === evt.outboxId ? 'Γû╝' : 'Γû╢'}
                                              </button>
                                            </td>
                                          </tr>
                                          {drawerExpandedId === evt.outboxId && (
                                            <tr>
                                              <td colSpan={4} style={{ padding: '8px 12px' }}>
                                                <pre
                                                  style={{
                                                    background: 'var(--bg-secondary)',
                                                    border: '1px solid var(--border)',
                                                    borderRadius: 4,
                                                    padding: 8,
                                                    fontSize: 10,
                                                    fontFamily: 'monospace',
                                                    overflowX: 'auto',
                                                    maxHeight: 200,
                                                    color: 'var(--text-secondary)',
                                                    margin: 0,
                                                  }}
                                                >
                                                  {evt.lastError && (
                                                    <span style={{ display: 'block', color: '#ef4444', marginBottom: '8px', fontWeight: 'bold' }}>
                                                      {t('drawer.errorLabel')} {evt.lastError}
                                                    </span>
                                                  )}
                                                  {JSON.stringify(evt.payload, null, 2)}
                                                </pre>
                                              </td>
                                            </tr>
                                          )}
                                        </Fragment>
                                      ))}
                                    </tbody>
                                  </table>
                                )}
                              </div>
                            </td>
                          </tr>
                        )}
                      </Fragment>
                    ))}
                  </tbody>
                </table>
              </div>
            )}

            {/* Recent events log */}
            <div className="card">
              <h3
                className="text-sm font-semibold mb-4"
                style={{ color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em' }}
              >
                {t('recentEvents', { count: data.recentEvents.length })}
              </h3>
              <div style={{ maxHeight: 600, overflowY: 'auto' }}>
                <table className="table-lines">
                  <thead>
                    <tr>
                      <th style={{ width: 170 }}>{t('columns.timestamp')}</th>
                      <th style={{ width: 150 }}>{t('columns.eventType')}</th>
                      <th>{t('columns.aggregate')}</th>
                      <th style={{ width: 170 }}>{t('columns.processedAt')}</th>
                      <th style={{ width: 80, textAlign: 'center' }}>{t('columns.status')}</th>
                      <th style={{ width: 70 }}>{t('columns.payload')}</th>
                    </tr>
                  </thead>
                  <tbody>
                    {data.recentEvents.map((evt) => (
                      <Fragment key={evt.outboxId}>
                        <tr>
                          <td style={{ fontSize: 11, fontVariantNumeric: 'tabular-nums', color: 'var(--text-muted)' }}>
                            {new Date(evt.createdOn).toLocaleString()}
                          </td>
                          <td>
                            <span
                              style={{
                                padding: '2px 6px',
                                borderRadius: 4,
                                fontSize: 11,
                                fontWeight: 600,
                                fontFamily: 'monospace',
                                background: 'rgba(59, 130, 246, 0.1)',
                                color: 'var(--accent)',
                              }}
                            >
                              {evt.eventType}
                            </span>
                          </td>
                          <td style={{ fontSize: 11, fontFamily: 'monospace', color: 'var(--text-secondary)' }}>
                            {evt.aggregateType}:{evt.aggregateId.substring(0, 8)}
                          </td>
                          <td style={{ fontSize: 11, fontVariantNumeric: 'tabular-nums', color: 'var(--text-muted)' }}>
                            {evt.processedAt ? new Date(evt.processedAt).toLocaleString() : 'ΓÇö'}
                          </td>
                          <td style={{ textAlign: 'center' }}>
                            {evt.lastError ? (
                              // eslint-disable-next-line i18next/no-literal-string
                              <span style={{ color: '#ef4444', fontWeight: 700, fontSize: 11 }} title={evt.lastError}>Γ£ò</span>
                            ) : evt.processedAt ? (
                              // eslint-disable-next-line i18next/no-literal-string
                              <span style={{ color: '#4ade80', fontWeight: 700, fontSize: 11 }}>Γ£ô</span>
                            ) : (
                              // eslint-disable-next-line i18next/no-literal-string
                              <span style={{ color: '#f59e0b', fontWeight: 700, fontSize: 11 }}>ΓÅ│</span>
                            )}
                          </td>
                          <td>
                            <button
                              className="btn btn-secondary btn-sm"
                              style={{ fontSize: 10 }}
                              onClick={() =>
                                setExpandedId(expandedId === evt.outboxId ? null : evt.outboxId)
                              }
                            >
                              {expandedId === evt.outboxId ? 'Γû╝' : 'Γû╢'}
                            </button>
                          </td>
                        </tr>
                        {expandedId === evt.outboxId && (
                          <tr key={`${evt.outboxId}-payload`}>
                            <td colSpan={6} style={{ padding: '12px 16px' }}>
                              <pre
                                style={{
                                  background: 'var(--bg-primary)',
                                  border: '1px solid var(--border)',
                                  borderRadius: 6,
                                  padding: 12,
                                  fontSize: 11,
                                  fontFamily: 'monospace',
                                  overflowX: 'auto',
                                  maxHeight: 300,
                                  color: 'var(--text-secondary)',
                                }}
                              >
                                {JSON.stringify(evt.payload, null, 2)}
                              </pre>
                            </td>
                          </tr>
                        )}
                      </Fragment>
                    ))}
                    {data.recentEvents.length === 0 && (
                      <tr>
                        <td colSpan={6} style={{ textAlign: 'center', color: 'var(--text-muted)', padding: '20px 0' }}>
                          {t('noEvents')}
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </>
        )}
      </div>
    </>
  );
}

'use client';

import { useState, useCallback, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { apiFetch, apiFetchBlob, apiMutate, reportError } from '@/lib/api';
import { toast } from 'react-hot-toast';
import { useTranslations } from 'next-intl';

export function TemplateForm({ initialData, isNew }: { initialData?: any, isNew?: boolean }) {
  const t = useTranslations('admin.reporting.form');
  const [formData, setFormData] = useState({
    name: initialData?.name || '',
    slug: initialData?.slug || '',
    description: initialData?.description || '',
    template: initialData?.template || t('defaults.template'),
    outputNamePattern: initialData?.outputNamePattern || t('defaults.outputPattern'),
    contexts: (initialData?.contexts as string[]) || [],
  });
  
  const [previewVars, setPreviewVars] = useState({
    hookSlug: (initialData?.contexts as string[])?.[0] || '',
    entityId: '',
  });
  
  const [availableHooks, setAvailableHooks] = useState<any[]>([]);
  const [pdfBlobUrl, setPdfBlobUrl] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [previewing, setPreviewing] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [contextsOpen, setContextsOpen] = useState(false);
  
  const router = useRouter();

  useEffect(() => {
    apiFetch<{ data: any[] }>('/api/reports/hooks').then(res => setAvailableHooks(res.data)).catch(() => {});
  }, []);

  const handleSave = async () => {
    setSaving(true);
    try {
      if (isNew) {
        await apiMutate('/api/reports', 'POST', formData);
        toast.success(t('toasts.created'));
        router.push('/admin/reporting');
      } else {
        await apiMutate(`/api/reports/${initialData.id}`, 'PATCH', formData);
        toast.success(t('toasts.saved'));
        router.refresh();
      }
    } catch (e: any) {
      toast.error(e.message || t('toasts.saveFailed'));
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!window.confirm(t('toasts.deleteConfirm'))) return;
    
    setDeleting(true);
    try {
      await apiMutate(`/api/reports/${initialData.id}`, 'DELETE');
      toast.success(t('toasts.deleted'));
      router.push('/admin/reporting');
    } catch (e: any) {
      toast.error(e.message || t('toasts.deleteFailed'));
      setDeleting(false);
    }
  };

  const handlePreview = async () => {
    setPreviewing(true);
    try {
      const blob = await apiFetchBlob('/api/reports/preview', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          template: formData.template,
          hookSlug: previewVars.hookSlug,
          entityId: previewVars.entityId
        })
      });
      const url = URL.createObjectURL(blob);
      setPdfBlobUrl(url);
    } catch (e: any) {
      toast.error(e.message || t('toasts.previewFailed'));
    } finally {
      setPreviewing(false);
    }
  };

  const handleRandomizeId = async () => {
    if (!previewVars.hookSlug) return;
    try {
      const res = await apiFetch<{ data: { id: string | null } }>(`/api/reports/hooks/${previewVars.hookSlug}/random-id`);
      if (res.data.id) {
        setPreviewVars(p => ({ ...p, entityId: res.data.id! }));
      }
    } catch (e) {
      reportError(e, 'TemplateForm');
    }
  };

  const handleHookChange = (newHookSlug: string) => {
    setPreviewVars(p => ({ ...p, hookSlug: newHookSlug, entityId: '' }));
    if (newHookSlug) {
      // Automatically fetch a random ID when changing hooks
      apiFetch<{ data: { id: string | null } }>(`/api/reports/hooks/${newHookSlug}/random-id`)
        .then(res => {
          if (res.data.id) setPreviewVars(p => ({ ...p, hookSlug: newHookSlug, entityId: res.data.id! }));
        })
        .catch(() => {});
    }
  };

  return (
    <div className="flex flex-col gap-6 pb-12 h-full overflow-y-auto pr-2">
      {/* Top side: Form & Editor */}
      <div className="flex flex-col gap-4 w-full shrink-0">
        <div className="card p-6 flex flex-col gap-4 bg-white rounded-xl shadow-sm border border-[rgba(196,198,205,0.4)]">
          <div className="flex items-center gap-3">
            <button 
              onClick={() => router.push('/admin/reporting')} 
              className="p-1 rounded-full hover:bg-gray-100 text-gray-400 hover:text-gray-800 transition-colors flex items-center justify-center shrink-0"
              title={t('buttons.returnToList')}
            >
              {/* eslint-disable-next-line i18next/no-literal-string */}
              <span className="material-symbols-outlined text-[20px]">arrow_back</span>
            </button>
            <h2 className="text-[1.3rem] font-bold tracking-tight text-[#041627]" style={{ fontFamily: 'Manrope, sans-serif' }}>
              {isNew ? t('newTemplate') : formData.name}
            </h2>
          </div>
          
          <div className="flex gap-4">
            <div className="flex-1">
              <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">{t('labels.displayName')}</label>
              <input className="input w-full" value={formData.name} onChange={e => setFormData(d => ({ ...d, name: e.target.value }))} />
            </div>
            <div className="flex-1">
              <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">{t('labels.uniqueSlug')}</label>
              <input className="input w-full" value={formData.slug} onChange={e => setFormData(d => ({ ...d, slug: e.target.value }))} placeholder={t('placeholders.slug')} />
            </div>
          </div>
          <div className="flex gap-4">
            <div className="flex-1">
              <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">{t('labels.outputPattern')}</label>
              <input className="input w-full" value={formData.outputNamePattern} onChange={e => setFormData(d => ({ ...d, outputNamePattern: e.target.value }))} />
            </div>
            <div className="flex-[2]">
              <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">{t('labels.description')}</label>
              <input className="input w-full" value={formData.description} onChange={e => setFormData(d => ({ ...d, description: e.target.value }))} />
            </div>
          </div>
          
          <div className="flex gap-4 mt-4">
            <div className="flex-1">
              <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-3">{t('labels.supportedContexts')}</label>
              <div className="relative w-full">
                <div 
                  className="input flex items-center justify-between cursor-pointer font-normal border-gray-300 bg-white shadow-sm"
                  onClick={() => setContextsOpen(!contextsOpen)}
                >
                  <span className="truncate pr-4 text-sm text-gray-700 font-semibold">
                    {formData.contexts.length > 0 ? formData.contexts.join(', ') : <span className="text-gray-400 font-normal">{t('placeholders.selectContexts')}</span>}
                  </span>
                  {/* eslint-disable-next-line no-restricted-syntax */}
                  <span className="material-symbols-outlined text-gray-400 text-[18px]">{contextsOpen ? 'expand_less' : 'expand_more'}</span>
                </div>
                
                {contextsOpen && (
                  <>
                    <div className="fixed inset-0 z-40" onClick={() => setContextsOpen(false)}></div>
                    <div className="absolute top-[calc(100%+4px)] left-0 w-full min-w-[200px] max-h-60 overflow-y-auto bg-white border border-[rgba(196,198,205,0.4)] rounded-lg shadow-xl z-50 py-1">
                      {availableHooks.length === 0 ? (
                        <div className="text-xs text-gray-400 italic p-3">{t('loadingContexts')}</div>
                      ) : (
                        availableHooks.map(h => (
                          <label key={h.contextSlug} className="flex items-center gap-3 px-3 py-2 cursor-pointer hover:bg-[#f8f9fa] transition-colors border-b border-gray-100 last:border-0">
                            <input 
                              type="checkbox" 
                              className="checkbox checkbox-sm checkbox-primary border-gray-300 rounded"
                              checked={formData.contexts.includes(h.contextSlug)}
                              onChange={(e) => {
                                const checked = e.target.checked;
                                setFormData(d => ({
                                  ...d,
                                  contexts: checked 
                                    ? [...d.contexts, h.contextSlug] 
                                    : d.contexts.filter(c => c !== h.contextSlug)
                                }));
                              }}
                            />
                            <span className="text-[13px] font-semibold text-gray-700">{h.contextSlug}</span>
                          </label>
                        ))
                      )}
                    </div>
                  </>
                )}
              </div>
              <p className="text-[10px] text-gray-400 mt-2 italic">
                {t('descriptions.contextHelp')}
              </p>
            </div>
          </div>

          <div className="flex flex-col flex-1 mt-4 min-h-[500px]">
            <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">{t('labels.typstSource')}</label>
            <textarea 
              className="flex-1 w-full border border-[rgba(196,198,205,0.4)] rounded-lg font-mono text-sm leading-relaxed p-4 bg-[#f8f9fa] whitespace-pre focus:outline-none focus:ring-2 focus:ring-[#006b5c]/30 focus:border-[#006b5c]"
              value={formData.template}
              onChange={e => setFormData(d => ({ ...d, template: e.target.value }))}
              spellCheck={false}
              style={{ minHeight: '500px', resize: 'vertical' }}
            />
          </div>

          <div className="flex items-center gap-3 mt-4">
            <button className="btn btn-primary px-8 py-3 text-sm font-bold rounded-lg transition-all bg-[#006b5c] text-white hover:brightness-110" onClick={handleSave} disabled={saving || deleting}>
              {saving ? t('buttons.saving') : t('buttons.save')}
            </button>
            {!isNew && (
              <button 
                className="btn btn-secondary px-8 py-3 text-sm font-bold rounded-lg border border-red-200 text-red-600 hover:bg-red-50 transition-all" 
                onClick={handleDelete} 
                disabled={saving || deleting}
              >
                {deleting ? t('buttons.deleting') : t('buttons.delete')}
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Bottom side: Live Preview */}
      <div className="flex flex-col w-full min-h-[800px] shrink-0">
        <div className="card p-6 flex flex-col gap-4 h-full bg-white rounded-xl shadow-sm border border-[rgba(196,198,205,0.4)]">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-bold text-[#041627]" style={{ fontFamily: 'Manrope, sans-serif' }}>{t('livePreview.title')}</h3>
            <span className="text-xs text-gray-400 font-semibold bg-gray-100 px-2 py-1 rounded">{t('livePreview.badge')}</span>
          </div>
          <div className="flex gap-3 items-end bg-[#f8f9fa] p-4 rounded-lg border border-[rgba(196,198,205,0.4)]">
            <div className="flex-1">
              <label className="block text-[11px] font-bold text-gray-500 uppercase tracking-wider mb-1.5">{t('labels.contextResolver')}</label>
              <select className="select w-full bg-white" value={previewVars.hookSlug} onChange={e => handleHookChange(e.target.value)}>
                <option value="">{t('none')}</option>
                {availableHooks.map(h => (
                  <option key={h.contextSlug} value={h.contextSlug}>{h.contextSlug}</option>
                ))}
              </select>
            </div>
            <div className="flex-1 relative">
              <label className="block text-[11px] font-bold text-gray-500 uppercase tracking-wider mb-1.5">{t('labels.targetRecordId')}</label>
              <div className="flex gap-2">
                 <input className="input w-full bg-white font-mono text-sm" value={previewVars.entityId} onChange={e => setPreviewVars(p => ({ ...p, entityId: e.target.value }))} placeholder={t('placeholders.uuid')} />
                 <button className="btn btn-secondary px-3 bg-white" title={t('buttons.getRandomId')} onClick={handleRandomizeId} disabled={!previewVars.hookSlug}>
                   {/* eslint-disable-next-line i18next/no-literal-string */}
                   ≡ƒÄ▓
                 </button>
              </div>
            </div>
            <button className="btn btn-secondary w-36 px-4 py-2 text-sm font-bold rounded-lg transition-all bg-white border border-[#041627] text-[#041627] hover:bg-gray-50" disabled={previewing || !previewVars.entityId} onClick={handlePreview}>
               {previewing ? t('buttons.compiling') : t('buttons.generatePdf')}
            </button>
          </div>
          
          <div className="flex-1 border border-[rgba(196,198,205,0.4)] rounded-lg bg-gray-200/50 overflow-hidden relative shadow-inner">
            {pdfBlobUrl ? (
              <iframe src={`${pdfBlobUrl}#toolbar=0`} className="w-[100%] h-[100%] border-0 object-contain" style={{ backgroundColor: '#525659' }} />
            ) : (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-400 gap-3">
                <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><line x1="16" y1="13" x2="8" y2="13"></line><line x1="16" y1="17" x2="8" y2="17"></line><polyline points="10 9 9 9 8 9"></polyline></svg>
                <span className="font-semibold text-sm">{t('livePreview.waiting')}</span>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

