'use client';
import { useState, useEffect } from 'react';
import SlideOver from '@/components/shared/SlideOver';
import { useTranslations } from 'next-intl';
import { apiFetch, apiMutate } from '@/lib/api';
import { toast } from 'react-hot-toast';

interface ChartFile {
  filename: string;
  name: string;
  countryCode?: string;
}

interface Props {
  isOpen: boolean;
  onClose: () => void;
  onImportComplete: () => void;
}

export default function ImportCoaModal({ isOpen, onClose, onImportComplete }: Props) {
  const tCommon = useTranslations('common');
  const [charts, setCharts] = useState<ChartFile[]>([]);
  const [selectedFile, setSelectedFile] = useState<string>('');
  const [isLoading, setIsLoading] = useState(false);
  const [isImporting, setIsImporting] = useState(false);

  useEffect(() => {
    if (isOpen) {
      loadCharts();
    }
  }, [isOpen]);

  const loadCharts = async () => {
    try {
      setIsLoading(true);
      const data = await apiFetch<ChartFile[]>('/api/gl/charts');
      setCharts(data);
      if (data.length > 0) {
        setSelectedFile(data[0].filename);
      }
    } catch (err: any) {
      toast.error('Failed to load available charts: ' + err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleImport = async () => {
    if (!selectedFile) return;
    try {
      setIsImporting(true);
      const res = await apiMutate<{ created: number }>('/api/gl/seed', 'POST', { filename: selectedFile });
      toast.success(`Successfully imported ${res.created} accounts.`);
      onImportComplete();
      onClose();
    } catch (err: any) {
      toast.error('Failed to import chart of accounts: ' + err.message);
    } finally {
      setIsImporting(false);
    }
  };

  return (
    <SlideOver isOpen={isOpen} onClose={onClose} title="Import Chart of Accounts" width="max-w-md">
      <div className="flex flex-col gap-4 p-4">
        {isLoading ? (
          <div className="text-sm text-muted animate-pulse">Loading available charts...</div>
        ) : charts.length === 0 ? (
          <div className="text-sm text-muted">No charts available.</div>
        ) : (
          <div className="flex flex-col gap-2">
            <label className="text-sm font-medium">Select Preset</label>
            <select
              className="input w-full"
              value={selectedFile}
              onChange={(e) => setSelectedFile(e.target.value)}
              disabled={isImporting}
            >
              {charts.map((chart) => (
                <option key={chart.filename} value={chart.filename}>
                  {chart.name} {chart.countryCode ? `(${chart.countryCode})` : ''}
                </option>
              ))}
            </select>
          </div>
        )}

        <div className="flex justify-end gap-2 mt-4">
          <button className="btn btn-secondary" onClick={onClose} disabled={isImporting}>
            {tCommon('cancel')}
          </button>
          <button
            className="btn btn-primary"
            onClick={handleImport}
            disabled={!selectedFile || isImporting || isLoading}
          >
            {isImporting ? 'Importing...' : 'Import CoA'}
          </button>
        </div>
      </div>
    </SlideOver>
  );
}

'use client';
import { useState, useEffect } from 'react';
import SlideOver from '@/components/shared/SlideOver';
import { useTranslations } from 'next-intl';
import { apiFetch, apiMutate } from '@/lib/api';
import { toast } from 'react-hot-toast';

interface SettingsFile {
  filename: string;
  name: string;
  countryCode?: string;
}

interface Props {
  isOpen: boolean;
  onClose: () => void;
  onImportComplete: () => void;
}

export default function ImportTaxModal({ isOpen, onClose, onImportComplete }: Props) {
  const tCommon = useTranslations('common');
  const [files, setFiles] = useState<SettingsFile[]>([]);
  const [selectedFile, setSelectedFile] = useState<string>('');
  const [isLoading, setIsLoading] = useState(false);
  const [isImporting, setIsImporting] = useState(false);

  useEffect(() => {
    if (isOpen) {
      loadFiles();
    }
  }, [isOpen]);

  const loadFiles = async () => {
    try {
      setIsLoading(true);
      const data = await apiFetch<SettingsFile[]>('/api/gl/tax-settings-files');
      setFiles(data);
      if (data.length > 0) {
        setSelectedFile(data[0].filename);
      }
    } catch (err: any) {
      toast.error('Failed to load available tax settings: ' + err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleImport = async () => {
    if (!selectedFile) return;
    try {
      setIsImporting(true);
      const res = await apiMutate<{ created: number }>('/api/gl/seed-tax', 'POST', { filename: selectedFile });
      toast.success(`Successfully imported ${res.created} tax categories.`);
      onImportComplete();
      onClose();
    } catch (err: any) {
      toast.error('Failed to import tax settings: ' + err.message);
    } finally {
      setIsImporting(false);
    }
  };

  return (
    <SlideOver isOpen={isOpen} onClose={onClose} title="Import Tax Settings" width="max-w-md">
      <div className="flex flex-col gap-4 p-4">
        {isLoading ? (
          <div className="text-sm text-muted animate-pulse">Loading available tax settings...</div>
        ) : files.length === 0 ? (
          <div className="text-sm text-muted">No tax settings files available.</div>
        ) : (
          <div className="flex flex-col gap-2">
            <label className="text-sm font-medium">Select Preset</label>
            <select
              className="input w-full"
              value={selectedFile}
              onChange={(e) => setSelectedFile(e.target.value)}
              disabled={isImporting}
            >
              {files.map((file) => (
                <option key={file.filename} value={file.filename}>
                  {file.name} {file.countryCode ? `(${file.countryCode})` : ''}
                </option>
              ))}
            </select>
          </div>
        )}

        <div className="flex justify-end gap-2 mt-4">
          <button className="btn btn-secondary" onClick={onClose} disabled={isImporting}>
            {tCommon('cancel')}
          </button>
          <button
            className="btn btn-primary"
            onClick={handleImport}
            disabled={!selectedFile || isImporting || isLoading}
          >
            {isImporting ? 'Importing...' : 'Import Tax Settings'}
          </button>
        </div>
      </div>
    </SlideOver>
  );
}

'use client';

