'use client';

import { use } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { calculateAvailableQuantity, PURCHASE_ORDER_STATE } from '@modbm/shared';
import ProductSearchInput from '@/components/shared/ProductSearchInput';
import ActivityTimeline from '@/components/shared/ActivityTimeline';
import { formatAmount } from '@/lib/currency';
import { calculateUomPriceAdjustment } from '@modbm/shared';
import type { ProductUom } from '@modbm/shared';
import { useTranslations } from 'next-intl';
import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import EntityHeader from '@/components/shared/EntityHeader';
import DetailsLayout from '@/components/shared/DetailsLayout';
import PageNav from '@/components/shared/PageNav';
import LocationSelect from '@/components/shared/LocationSelect';

import type { TaxCategory } from './types';
import { getTaxLabel } from './types';
import InvoicesSection from './InvoicesSection';
import AllocationsSection from './AllocationsSection';
import ReceptionsSection from './ReceptionsSection';
import ReturnsSection from './ReturnsSection';
import { usePurchaseOrder } from './usePurchaseOrder';

import StateBadge from '@/components/StateBadge';
import { ValidState } from '@/types/states';

function TaxLabel({ category }: { category: TaxCategory }) {
  if (!category) return null;
  return <>{getTaxLabel(category)}</>;
}

export default function OrderDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  const router = useRouter();
  const tCommon = useTranslations('common');
  const tPurchase = useTranslations('purchaseOrders');
  const tToast = useTranslations('toast');

  const o = usePurchaseOrder(id);


  const { order, loading, error, saving, copying, latestAutoTransition,
    isHeaderEditable, isLinesEditable, visibleTransitions, subtotal, totalTax,
    editName, setEditName, editReferenceNumber, setEditReferenceNumber,
    editNotes, setEditNotes, editLocationId, setEditLocationId, headerDirty,
    taxCategories, activeTab, setActiveTab, inventoryData, inventoryLoading,
    invoices, setInvoicing,
    clearError, setError, saveHeader, changeState, copyOrder,
    updateLine, updateLineFields, removeLine, addLineFromProduct, addBlankLine,
    loadOrder, loadInvoices, loadAllocations, allocations, allocationsLoading,
  } = o;

  useDocumentTitle(order ? (order.name ? `${order.orderNumber} - ${order.name}` : order.orderNumber) : null);

  if (loading) {
    return (
      <>
        <div className="flex items-center justify-center flex-1">
          <p style={{ color: 'var(--text-muted)' }}>{tCommon('loading')}</p>
        </div>
      </>
    );
  }

  if (!order) {
    return (
      <>
        <div className="flex flex-col items-center justify-center flex-1">
          <p className="text-lg mb-2" style={{ color: 'var(--danger)' }}>
            {error || tPurchase('orderNotFound')}
          </p>
          <button className="btn btn-secondary" onClick={() => router.push('/purchase-orders')}>
            {tPurchase('backToOrders')}
          </button>
        </div>
      </>
    );
  }

  const sections = {
    details: { id: 'details-section', label: 'Details', show: true },
    allocations: { id: 'allocations-section', label: 'Allocations', show: true },
    receptions: { id: 'receptions-section', label: 'Receptions', show: true },
    invoices: { id: 'Invoices-section', label: 'Invoices', show: true },
    activity: { id: 'activity-section', label: 'Activity', show: true },
  };
  const visibleSections = Object.values(sections).filter(s => s.show);


  return (
    <>
      <DetailsLayout
        header={
          <EntityHeader
            title={order.orderNumber}
            subtitle={order.name || tPurchase('untitledOrder')}
            onBack={() => {
              if (document.referrer.includes(window.location.host)) {
                router.back();
              } else {
                router.push('/purchase-orders');
              }
            }}
            isSaving={saving}
            badges={<StateBadge state={order.stateCode as ValidState} />}
            actions={
              <>
                <PageNav sections={visibleSections} />
                {headerDirty && isHeaderEditable && (
                  <button className="btn btn-primary btn-sm" onClick={saveHeader} disabled={saving}>
                    {tPurchase('buttons.save')}
                  </button>
                )}
                {visibleTransitions.map((t) => (
                  <button
                    key={t.state}
                    className={`btn btn-sm ${t.isDanger ? 'btn-danger' : t.isBack ? 'btn-secondary' : 'btn-primary'}`}
                    onClick={() => changeState(t.state)}
                  >
                    {t.icon === 'close' ? (
                      <span className="material-symbols-outlined mr-1" style={{ fontSize: 16 }}>close</span>
                    ) : (
                      t.icon
                    )}
                    {t.label}
                  </button>
                ))}
              </>
            }
          />
        }
      >
      <div className="flex flex-col gap-3">

      {error && (
        <div
          className="px-4 py-3 rounded-lg text-sm"
          style={{
            background: 'rgba(239, 68, 68, 0.1)',
            border: '1px solid rgba(239, 68, 68, 0.3)',
            color: '#f87171',
          }}
        >
          {error}
          <button className="ml-3 text-xs underline" onClick={clearError}>{tCommon('dismiss')}</button>
        </div>
      )}

          {/* Order info card */}
          <div id="details-section" className="card">
            <div className="flex justify-between items-center mb-4">
              <h3 className="section-heading">
                {/* eslint-disable-next-line i18next/no-literal-string */}
                <span className="material-symbols-outlined">receipt_long</span>
                {tPurchase('orderDetails')}
              </h3>
              <button
                className="btn btn-secondary btn-sm"
                onClick={copyOrder}
                disabled={copying}
              >
                {copying ? tCommon('copying') : tPurchase('buttons.copyOrder')}
              </button>
            </div>
            <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tPurchase('labels.supplier')}
                    {order.currencyCode && (
                      <span
                        style={{
                          marginLeft: 8,
                          padding: '1px 6px',
                          borderRadius: 4,
                          background: 'rgba(59,130,246,0.15)',
                          color: 'var(--accent)',
                          fontWeight: 600,
                          fontSize: 10,
                          letterSpacing: '0.04em',
                        }}
                      >
                        {order.currencyCode}
                      </span>
                    )}
                  </label>
                  <div className="text-sm" style={{ fontWeight: 500, paddingTop: 6 }}>
                    {order.vendorId ? (
                      <Link href={`/suppliers/${order.vendorId}`} className="text-[var(--accent)] hover:underline">
                        {order.vendorName || order.vendorId}
                      </Link>
                    ) : (
                      order.vendorName || 'ΓÇö'
                    )}
                  </div>
                </div>
                <div>
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tPurchase('labels.referenceNumber')}
                  </label>
                  <input
                    className="input"
                    value={editReferenceNumber}
                    onChange={(e) => setEditReferenceNumber(e.target.value)}
                    onBlur={saveHeader}
                    disabled={!isHeaderEditable}
                    placeholder={tPurchase('placeholders.referenceNumber')}
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tPurchase('labels.orderName')}
                  </label>
                  <input
                    className="input"
                    value={editName}
                    onChange={(e) => setEditName(e.target.value)}
                    onBlur={saveHeader}
                    disabled={!isHeaderEditable}
                    placeholder={tPurchase('placeholders.orderName')}
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tPurchase('labels.created')}
                  </label>
                  <p className="text-sm" style={{ fontWeight: 500, paddingTop: 6 }}>
                    {new Date(order.createdOn).toLocaleString()} {tCommon('by')} {order.createdBy || 'ΓÇö'}
                  </p>
                </div>
                <div>
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tPurchase('labels.location')}
                  </label>
                  {isHeaderEditable && order.stateCode === PURCHASE_ORDER_STATE.DRAFT ? (
                    <LocationSelect
                      value={editLocationId || ''}
                      onChange={(loc) => setEditLocationId(loc)}
                      className="text-sm"
                    />
                  ) : (
                    <p className="text-sm" style={{ fontWeight: 500, paddingTop: 6 }}>
                      {order.locationName || order.deliveryLocationId || 'ΓÇö'}
                    </p>
                  )}
                </div>
                <div className="col-span-1">
                   {/* notes pushed to full width if needed, or matched next column */}
                </div>
                <div className="col-span-2">
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tCommon('notesCardHeading')}
                  </label>
                  <input
                    className="input w-full"
                    value={editNotes}
                    onChange={(e) => setEditNotes(e.target.value)}
                    onBlur={saveHeader}
                    disabled={!isHeaderEditable}
                    placeholder={tCommon('notesCardPlaceholder')}
                  />
                </div>
              </div>
          </div>

        {/* Line items / Availability tabs */}
        <div id="lines-section" className="card">
          <div className="flex items-center justify-between mb-4">
            <div className="flex gap-0">
              <button
                className="text-xs font-medium px-3 py-1.5 rounded-l-lg"
                style={{
                  color: activeTab === 'lines' ? 'var(--accent)' : 'var(--text-muted)',
                  background: activeTab === 'lines' ? 'rgba(59,130,246,0.1)' : 'transparent',
                  border: '1px solid',
                  borderColor: activeTab === 'lines' ? 'rgba(59,130,246,0.3)' : 'var(--border)',
                  cursor: 'pointer',
                }}
                onClick={() => setActiveTab('lines')}
              >
                {tPurchase('lineItems')}
              </button>
              <button
                className={`text-xs font-medium px-3 py-1.5 ${order.stateCode !== PURCHASE_ORDER_STATE.DRAFT ? '' : 'rounded-r-lg'}`}
                style={{
                  color: activeTab === 'availability' ? 'var(--accent)' : 'var(--text-muted)',
                  background: activeTab === 'availability' ? 'rgba(59,130,246,0.1)' : 'transparent',
                  border: '1px solid',
                  borderColor: activeTab === 'availability' ? 'rgba(59,130,246,0.3)' : 'var(--border)',
                  borderLeft: activeTab === 'availability' ? '1px solid rgba(59,130,246,0.3)' : 'none',
                  cursor: 'pointer',
                }}
                onClick={() => setActiveTab('availability')}
              >
                {tPurchase('availability')}
              </button>
              {order.stateCode !== PURCHASE_ORDER_STATE.DRAFT && (
                <button
                  className="text-xs font-medium px-3 py-1.5 rounded-r-lg"
                  style={{
                    color: activeTab === 'status' ? 'var(--accent)' : 'var(--text-muted)',
                    background: activeTab === 'status' ? 'rgba(59,130,246,0.1)' : 'transparent',
                    border: '1px solid',
                    borderColor: activeTab === 'status' ? 'rgba(59,130,246,0.3)' : 'var(--border)',
                    borderLeft: activeTab === 'status' ? '1px solid rgba(59,130,246,0.3)' : 'none',
                    cursor: 'pointer',
                  }}
                  onClick={() => setActiveTab('status')}
                >
                  Status
                </button>
              )}
            </div>
            {isLinesEditable && activeTab === 'lines' && (
              <>
                <ProductSearchInput
                  onSelect={addLineFromProduct}
                  placeholder="Add productΓÇª (search)"
                  style={{ width: 240 }}
                />
                <button
                  className="btn btn-secondary btn-sm"
                  onClick={addBlankLine}
                  disabled={saving}
                >
                  + {tPurchase('buttons.customLine')}
                </button>
              </>
            )}
          </div>

          {activeTab === 'lines' ? (
            <table className="table-lines">
              <thead>
                <tr>
                  <th style={{ width: 40 }}>{tPurchase('columns.lineNumber')}</th>
                  <th>{tPurchase('columns.product')}</th>
                  <th>{tPurchase('columns.description')}</th>
                  <th style={{ width: 90, textAlign: 'right' }}>{tPurchase('columns.qty')}</th>
                  <th style={{ width: 80, textAlign: 'right' }}>{tPurchase('columns.uom')}</th>
                  <th style={{ width: 110, textAlign: 'right' }}>{tPurchase('columns.unitPrice')}</th>
                  <th style={{ width: 80, textAlign: 'right' }}>{tPurchase('columns.discountPct' as any)}</th>
                  <th style={{ width: 110, textAlign: 'right' }}>{tPurchase('columns.tax' as any)}</th>
                  <th style={{ width: 110, textAlign: 'right' }}>{tPurchase('columns.amount')}</th>
                  {isLinesEditable && <th style={{ width: 50 }}></th>}
                </tr>
              </thead>
              <tbody>
                {order.lines.map((line) => (
                  <tr key={line.purchaseOrderLineId}>
                    <td style={{ color: 'var(--text-muted)' }}>{line.lineNumber}</td>
                    <td style={{ fontWeight: 600, fontSize: 12 }}>
                      {line.productId && line.productId !== '00000000-0000-0000-0000-000000000000' ? (
                        <Link href={`/products/${line.productId}`} style={{ color: 'var(--accent)', textDecoration: 'none' }}>
                          {line.productNumber || line.productId?.substring(0, 8)}
                        </Link>
                      ) : (
                        line.productNumber || line.productId?.substring(0, 8) || 'ΓÇö'
                      )}
                    </td>
                    <td>
                      {(!line.productId || line.productId === '00000000-0000-0000-0000-000000000000') && isLinesEditable ? (
                        <input
                          className="input"
                          style={{ width: '100%', fontSize: 13 }}
                          defaultValue={line.productDescription || ''}
                          key={`desc-${line.purchaseOrderLineId}-${line.productDescription}`}
                          onBlur={(e) => {
                            if (e.target.value !== (line.productDescription || '')) {
                              updateLine(line.purchaseOrderLineId, 'productDescription', e.target.value);
                            }
                          }}
                          placeholder="Custom description..."
                        />
                      ) : (
                        line.productDescription || 'ΓÇö'
                      )}
                    </td>
                    {isLinesEditable ? (
                      <>
                        <td style={{ textAlign: 'right' }}>
                          <input
                            className="input"
                            type="number"
                            min="0"
                            step="1"
                            style={{ width: '100%', textAlign: 'right' }}
                            defaultValue={line.quantity}
                            key={`qty-${line.purchaseOrderLineId}-${line.quantity}`}
                            onBlur={(e) => {
                              if (e.target.value !== line.quantity) {
                                updateLine(line.purchaseOrderLineId, 'quantity', e.target.value);
                              }
                            }}
                          />
                        </td>
                        <td style={{ textAlign: 'right' }}>
                          {(() => {
                            const uoms: ProductUom[] = line.productUoms || [];
                            const defaultUom = line.baseUom || 'EA';
                            const selectOptions = uoms.length > 0 ? uoms : [{ uomCode: defaultUom, ratio: 1 }];
                            return (
                              <select
                                className="input"
                                style={{ width: '100%', fontSize: 13, textAlign: 'right' }}
                                value={line.unitOfMeasure || defaultUom}
                                onChange={(e) => {
                                  const newVal = e.target.value;
                                  const oldVal = line.unitOfMeasure || defaultUom;
                                  if (newVal !== oldVal) {
                                    const oldO = selectOptions.find(o => o.uomCode === oldVal);
                                    const oldRatio = typeof oldO?.ratio === 'string' ? parseFloat(oldO.ratio) : (oldO?.ratio || 1);
    
                                    const newO = selectOptions.find(o => o.uomCode === newVal);
                                    const newRatio = typeof newO?.ratio === 'string' ? parseFloat(newO.ratio) : (newO?.ratio || 1);
    
                                    const newPrice = calculateUomPriceAdjustment(line.pricePerUnit || 0, oldRatio, newRatio);
                                    updateLineFields(line.purchaseOrderLineId, {
                                      unitOfMeasure: newVal,
                                      pricePerUnit: isNaN(newPrice) ? '0.00' : newPrice.toFixed(2)
                                    });
                                  }
                                }}
                              >
                                {selectOptions.map(o => (
                                  <option key={o.uomCode} value={o.uomCode}>{o.uomCode}</option>
                                ))}
                              </select>
                            );
                          })()}
                        </td>
                        <td style={{ textAlign: 'right' }}>
                          <input
                            className="input"
                            type="number"
                            min="0"
                            step="0.01"
                            style={{ width: '100%', textAlign: 'right' }}
                            defaultValue={parseFloat(line.pricePerUnit || '0').toFixed(2)}
                            key={`price-${line.purchaseOrderLineId}-${line.pricePerUnit}`}
                            onBlur={(e) => {
                              const val = parseFloat(e.target.value);
                              const formatted = isNaN(val) ? '0.00' : val.toFixed(2);
                              e.target.value = formatted;
                              if (formatted !== parseFloat(line.pricePerUnit || '0').toFixed(2)) {
                                updateLine(line.purchaseOrderLineId, 'pricePerUnit', formatted);
                              }
                            }}
                          />
                        </td>
                        <td style={{ textAlign: 'right' }}>
                          <input
                            className="input"
                            type="number"
                            min="0"
                            max="100"
                            step="0.1"
                            style={{ width: '100%', textAlign: 'right' }}
                            defaultValue={line.discountPercentage}
                            key={`disc-${line.purchaseOrderLineId}-${line.discountPercentage}`}
                            onBlur={(e) => {
                              if (e.target.value !== line.discountPercentage) {
                                updateLine(line.purchaseOrderLineId, 'discountPercentage', e.target.value);
                              }
                            }}
                          />
                        </td>
                      </>
                    ) : (
                      <>
                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                          {line.quantity}
                        </td>
                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                          {/* eslint-disable-next-line no-restricted-syntax */}
                          {line.unitOfMeasure || line.baseUom || 'EA'}
                        </td>
                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                          {formatAmount(parseFloat(line.pricePerUnit || '0'), order.currencyCode || 'EUR')}
                        </td>
                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                          {parseFloat(line.discountPercentage || '0').toFixed(1)}%
                        </td>
                      </>
                    )}
                    {isLinesEditable ? (
                      <td style={{ textAlign: 'right' }}>
                        <select
                          className="input"
                          style={{ width: '100%', fontSize: 12, textAlign: 'right' }}
                          value={line.taxCategoryId || ''}
                          onChange={(e) => updateLine(line.purchaseOrderLineId, 'taxCategoryId', e.target.value)}
                        >
                          {taxCategories.map((c) => (
                            <option key={c.taxCategoryId} value={c.taxCategoryId}>
                              <TaxLabel category={c} />
                            </option>
                          ))}
                        </select>
                      </td>
                    ) : (
                      <td style={{ textAlign: 'right', fontSize: 12 }}>
                        {(() => {
                          const c = taxCategories.find((c) => c.taxCategoryId === line.taxCategoryId);
                          if (c) return <TaxLabel category={c} />;
                          // Legacy derivation
                          const amt = parseFloat(line.amount || '0');
                          const tax = parseFloat(line.tax || '0');
                          if (amt > 0 && tax > 0) {
                            const pct = (tax / amt) * 100;
                            return `${pct % 1 === 0 ? pct.toFixed(0) : pct.toFixed(1)}%`;
                          }
                          if (amt > 0 && tax === 0) return tCommon('taxLabels.exempt');
                          return 'ΓÇö';
                        })()}
                      </td>
                    )}
                    <td
                      style={{
                        textAlign: 'right',
                        fontWeight: 600,
                        fontVariantNumeric: 'tabular-nums',
                      }}
                    >
                      {formatAmount(parseFloat(line.amount || '0'), order.currencyCode || 'EUR')}
                    </td>
                    {isLinesEditable && (
                      <td>
                        <button
                          className="btn btn-danger btn-sm"
                          onClick={() => removeLine(line.purchaseOrderLineId)}
                          title="Remove line"
                        >
                          <span dangerouslySetInnerHTML={{ __html: '&#10005;' }} />
                        </button>
                      </td>
                    )}
                  </tr>
                ))}
                {order.lines.length === 0 && (
                  <tr>
                    <td
                      colSpan={isLinesEditable ? 9 : 8}
                      style={{ textAlign: 'center', color: 'var(--text-muted)', padding: '20px 0' }}
                    >
                      {tPurchase('noLineItems')}
                    </td>
                  </tr>
                )}
                {order.lines.length > 0 && (() => {
                  const taxPct = subtotal > 0 ? (totalTax / subtotal) * 100 : 0;
                  return (
                    <>
                      <tr style={{ borderTop: '2px solid var(--border)' }}>
                        <td colSpan={8} style={{ textAlign: 'right', fontWeight: 600, color: 'var(--text-muted)' }}>
                          {tCommon('subtotal')}
                        </td>
                        <td style={{ textAlign: 'right', fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>
                          {formatAmount(subtotal, order.currencyCode || 'EUR')}
                        </td>
                        {isLinesEditable && <td></td>}
                      </tr>
                      <tr>
                        <td colSpan={8} style={{ textAlign: 'right', fontWeight: 600, color: 'var(--text-muted)' }}>
                          {tCommon('tax')}{taxPct > 0 ? ` (${taxPct % 1 === 0 ? taxPct.toFixed(0) : taxPct.toFixed(1)}%)` : ''}
                        </td>
                        <td style={{ textAlign: 'right', fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>
                          {formatAmount(totalTax, order.currencyCode || 'EUR')}
                        </td>
                        {isLinesEditable && <td></td>}
                      </tr>
                      <tr style={{ backgroundColor: 'rgba(59,130,246,0.02)' }}>
                        <td colSpan={8} style={{ textAlign: 'right', fontWeight: 700, fontSize: 13, color: 'var(--text-primary)' }}>
                          {tCommon('total')}
                        </td>
                        <td style={{ textAlign: 'right', fontWeight: 800, fontSize: 14, color: 'var(--accent)', fontVariantNumeric: 'tabular-nums' }}>
                          {formatAmount(subtotal + totalTax, order.currencyCode || 'EUR')}
                        </td>
                        {isLinesEditable && <td></td>}
                      </tr>
                    </>
                  );
                })()}
              </tbody>
            </table>
          ) : activeTab === 'availability' ? (
            /* Availability tab */
            inventoryLoading ? (
              <p className="text-sm" style={{ color: 'var(--text-muted)', padding: '20px 0', textAlign: 'center' }}>{tPurchase('loadingInventory')}</p>
            ) : (
              <table className="table-lines">
                <thead>
                  <tr>
                    <th style={{ width: 40 }}>{tPurchase('columns.lineNumber')}</th>
                    <th>{tPurchase('columns.product')}</th>
                    <th>{tPurchase('columns.description')}</th>
                    <th style={{ width: 90, textAlign: 'right' }}>{tPurchase('columns.thisOrder')}</th>
                    <th style={{ width: 100, textAlign: 'right' }}>{tPurchase('columns.location')}</th>
                    <th style={{ width: 90, textAlign: 'right' }}>{tPurchase('columns.onHand')}</th>
                    <th style={{ width: 90, textAlign: 'right' }}>{tPurchase('columns.committed')}</th>
                    <th style={{ width: 90, textAlign: 'right' }}>{tPurchase('columns.ordered')}</th>
                    <th style={{ width: 90, textAlign: 'right' }}>{tPurchase('columns.reserved')}</th>
                    <th style={{ width: 90, textAlign: 'right' }}>{tPurchase('columns.available')}</th>
                    <th style={{ width: 70, textAlign: 'center' }}>{tPurchase('columns.status')}</th>
                  </tr>
                </thead>
                <tbody>
                  {order.lines.map((line) => {
                    const lineInventory = inventoryData.filter(
                      (inv) => inv.productId === line.productId,
                    );
                    const totalAvail = lineInventory.reduce(
                      (sum, inv) => sum + calculateAvailableQuantity(inv.quantityOnHand, inv.quantityCommitted, inv.quantityReserved), 0,
                    );
                    const orderedQty = parseFloat(line.quantity || '0');
                    const canFulfil = totalAvail >= orderedQty;

                    if (lineInventory.length === 0) {
                      return (
                        <tr key={line.purchaseOrderLineId}>
                          <td style={{ color: 'var(--text-muted)' }}>{line.lineNumber}</td>
                          <td style={{ fontWeight: 600, fontSize: 12 }}>
                            {line.productId && line.productId !== '00000000-0000-0000-0000-000000000000' ? (
                              <Link href={`/products/${line.productId}`} style={{ color: 'var(--accent)', textDecoration: 'none' }}>
                                {line.productNumber || line.productId?.substring(0, 8)}
                              </Link>
                            ) : (
                              line.productNumber || line.productId?.substring(0, 8) || 'ΓÇö'
                            )}
                          </td>
                          <td>{line.productDescription || 'ΓÇö'}</td>
                          <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{line.quantity}</td>
                          <td colSpan={6} style={{ textAlign: 'center', color: 'var(--text-muted)', fontSize: 12 }}>
                            {tPurchase('noInventoryData')}
                          </td>
                          <td style={{ textAlign: 'center' }}>
                            <span style={{ color: '#f59e0b', fontWeight: 700, fontSize: 11 }}>ΓÜá</span>
                          </td>
                        </tr>
                      );
                    }

                    return lineInventory.map((inv, idx) => {
                      const avail = calculateAvailableQuantity(inv.quantityOnHand, inv.quantityCommitted, inv.quantityReserved);
                      return (
                        <tr key={`${line.purchaseOrderLineId}-${inv.inventoryLevelId}`}>
                          {idx === 0 && (
                            <>
                              <td style={{ color: 'var(--text-muted)' }} rowSpan={lineInventory.length}>{line.lineNumber}</td>
                              <td style={{ fontWeight: 600, fontSize: 12 }} rowSpan={lineInventory.length}>
                                {line.productId && line.productId !== '00000000-0000-0000-0000-000000000000' ? (
                                  <Link href={`/products/${line.productId}`} style={{ color: 'var(--accent)', textDecoration: 'none' }}>
                                    {line.productNumber || line.productId?.substring(0, 8)}
                                  </Link>
                                ) : (
                                  line.productNumber || line.productId?.substring(0, 8) || 'ΓÇö'
                                )}
                              </td>
                              <td rowSpan={lineInventory.length}>{line.productDescription || 'ΓÇö'}</td>
                              <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }} rowSpan={lineInventory.length}>
                                {line.quantity}
                              </td>
                            </>
                          )}
                          <td style={{ textAlign: 'right', fontSize: 12 }}>{inv.locationName || inv.locationNo}</td>
                          <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                            {parseFloat(inv.quantityOnHand || '0')}
                          </td>
                          <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                            {parseFloat(inv.quantityCommitted || '0')}
                          </td>
                          <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                            {parseFloat(inv.quantityOnOrder || '0')}
                          </td>
                          <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                            {parseFloat(inv.quantityReserved || '0')}
                          </td>
                          <td style={{
                            textAlign: 'right',
                            fontVariantNumeric: 'tabular-nums',
                            fontWeight: 600,
                            color: avail > 0 ? '#4ade80' : '#ef4444',
                          }}>
                            {avail}
                          </td>
                          {idx === 0 && (
                            <td style={{ textAlign: 'center' }} rowSpan={lineInventory.length}>
                              <span style={{
                                color: canFulfil ? '#4ade80' : '#ef4444',
                                fontWeight: 700,
                                fontSize: 11,
                              }}>
                                {canFulfil ? 'Γ£ô' : 'Γ£ù'}
                              </span>
                            </td>
                          )}
                        </tr>
                      );
                    });
                  })}
                  {order.lines.length === 0 && (
                    <tr>
                      <td colSpan={10} style={{ textAlign: 'center', color: 'var(--text-muted)', padding: '20px 0' }}>
                        {tPurchase('noLineItemsShort')}
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            )
          ) : activeTab === 'status' ? (
            /* Status / Bill Summary tab */
            <div className="overflow-x-auto">
                <table className="table-lines">
                    <thead>
                        <tr>
                            <th style={{ width: 40 }}>{tPurchase('columns.lineNumber')}</th>
                            <th>{tPurchase('columns.product')}</th>
                            <th>{tPurchase('columns.description')}</th>
                            <th style={{ textAlign: 'right' }}>{tPurchase('columns.ordered')}</th>
                            <th style={{ textAlign: 'right' }}>Allocated</th>
                            <th style={{ textAlign: 'right' }}>{tPurchase('columns.received')}</th>
                            <th style={{ textAlign: 'right' }}>{tPurchase('columns.billed')}</th>
                            <th style={{ textAlign: 'right' }}>{tPurchase('columns.remaining')}</th>
                        </tr>
                    </thead>
                    <tbody>
                        {(order.lines || []).map(line => {
                            const ordered = parseFloat(line.quantity || '0');
                            const received = parseFloat(line.quantityReceived || '0');
                            const allocated = allocations.reduce((sum, alloc) => {
                                return sum + (alloc.purchaseOrderLineId === line.purchaseOrderLineId ? parseFloat(alloc.quantity) : 0);
                            }, 0);
                            const billed = invoices.reduce((sum, inv) => {
                                const invLine = inv.lines?.find((il: any) => il.purchaseOrderLineId === line.purchaseOrderLineId);
                                return sum + (invLine ? parseFloat(invLine.quantityInvoiced) : 0);
                            }, 0);
                            const remaining = Math.max(0, ordered - billed);
                            return (
                                <tr key={line.purchaseOrderLineId}>
                                    <td style={{ color: 'var(--text-muted)' }}>{line.lineNumber}</td>
                                    <td style={{ fontWeight: 600, fontSize: 12 }}>
                                        {line.productNumber || line.productId?.substring(0, 8) || 'ΓÇö'}
                                    </td>
                                    <td>{line.productDescription || 'ΓÇö'}</td>
                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{ordered}</td>
                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', color: allocated > 0 ? 'var(--badge-shipped)' : undefined, fontWeight: allocated > 0 ? 600 : 400 }}>{allocated}</td>
                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', color: received >= ordered && ordered > 0 ? 'var(--badge-shipped)' : undefined, fontWeight: received >= ordered && ordered > 0 ? 600 : 400 }}>{received}</td>
                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', color: billed >= received && received > 0 ? 'var(--badge-shipped)' : undefined, fontWeight: billed >= received && received > 0 ? 600 : 400 }}>{billed}</td>
                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', color: remaining === 0 ? 'var(--text-muted)' : undefined }}>{remaining}</td>
                                </tr>
                            );
                        })}
                        {order.lines.length === 0 && (
                          <tr>
                            <td colSpan={8} style={{ textAlign: 'center', color: 'var(--text-muted)', padding: '20px 0' }}>
                              {tPurchase('noLineItemsShort')}
                            </td>
                          </tr>
                        )}
                    </tbody>
                </table>
            </div>
          ) : null}
        </div>

        <AllocationsSection 
          orderId={id} 
          allocations={allocations} 
          loading={allocationsLoading} 
          onAllocationsChanged={loadAllocations} 
        />

        <ReceptionsSection orderId={id} />

        <ReturnsSection
          orderId={id}
          orderState={order.stateCode}
          orderLines={order.lines}
          events={order.events}
          currencyCode={order.currencyCode}
        />

        <InvoicesSection
          orderId={id}
          order={order}
          Invoices={invoices}
          taxCategories={taxCategories}
          setError={setError}
          loadInvoices={loadInvoices}
          loadOrder={loadOrder as any}
        />

        {/* Audit timeline */}
        <div id="activity-section" className="card">
          <ActivityTimeline events={order.events || []} />
        </div>
      </div>
      </DetailsLayout>

      {/* Global Toast Notification for Auto-Transitions */}
      <div
        className={`fixed bottom-6 right-6 rounded-lg p-4 max-w-[400px] z-[60] flex flex-col gap-1 pointer-events-none shadow-lg border border-[var(--border)] transition-all duration-300 ease-out ${latestAutoTransition ? 'translate-y-0 opacity-100' : 'translate-y-full opacity-0'
          }`}
        style={{ background: 'var(--bg-card)' }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <span style={{ fontSize: 16 }}>ΓÜí</span>
          <strong style={{ fontSize: 13, color: 'var(--text-primary)' }}>
            {tToast('orderStateUpdated')}
          </strong>
        </div>
        <p style={{ fontSize: 12, color: 'var(--text-secondary)', margin: 0, lineHeight: 1.4 }}>
          {latestAutoTransition && (
            tToast('orderMovedToReason', {
              state: tCommon(`states.${latestAutoTransition.to}` as any),
              reason: latestAutoTransition.reason.toLowerCase()
            })
          )}
        </p>
      </div>
    </>
  );
}

'use client';

import { useMemo, useState, useCallback } from 'react';
import DataGrid from '@/components/DataGrid';
import DraftPOsModal from './DraftPOsModal';
import LinkToPOSlideOver from './LinkToPOSlideOver';
import ReallocateModal from './ReallocateModal';
import InternalTransferModal from './InternalTransferModal';
import StockElsewhereCell from './StockElsewhereCell';
import type { ColDef, ICellRendererParams } from 'ag-grid-community';
import { useTranslations } from 'next-intl';
import { apiFetch, reportError } from '@/lib/api';
import toast from 'react-hot-toast';
import Link from 'next/link';
import { PO_STATE } from '@modbm/core';

export interface AvailableElsewhereEntry {
  locationId: string;
  locationName: string;
  availableQty: number;
}

export interface DemandRow {
  id: string;
  salesOrderId: string;
  orderNumber: string;
  productId: string;
  productName: string;
  productDescription?: string;
  quantity: number;
  createdOn: string;
  vendorId?: string;
  vendorName?: string;
  costPrice?: number;
  currencyCode?: string;
  locationId: string;
  locationName: string;
  /**
   * Inventory available at other locations for this demand's product,
   * excluding the demand's own destination location. Locations with zero
   * available qty are omitted server-side. Sorted ascending by API; the
   * cell renderer sorts by qty descending for display.
   */
  availableElsewhere: AvailableElsewhereEntry[];
  purchaseOrderId?: string;
  purchaseOrderNumber?: string;
  purchaseOrderState?: string;
}

export default function DemandsContent() {
  const tCommon = useTranslations('common');
  const tPurchase = useTranslations('purchaseOrders');
  const [loading, setLoading] = useState(false);
  const [refreshKey, setRefreshKey] = useState(0);
  const [selectedRows, setSelectedRows] = useState<DemandRow[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isLinkSlideOverOpen, setIsLinkSlideOverOpen] = useState(false);
  const [isReallocateModalOpen, setIsReallocateModalOpen] = useState(false);
  const [isInternalTransferModalOpen, setIsInternalTransferModalOpen] = useState(false);

  const columns = useMemo<ColDef<DemandRow>[]>(() => [
    {
      field: 'orderNumber',
      headerName: 'Sales Order',
      width: 160,
      pinned: 'left',
      checkboxSelection: true,
      headerCheckboxSelection: true,
    },
    { field: 'productName', headerName: 'Product', flex: 1, minWidth: 150 },
    { field: 'productDescription', headerName: 'Description', flex: 2, minWidth: 200 },
    {
      field: 'purchaseOrderState',
      headerName: 'Status',
      width: 160,
      cellRenderer: (params: ICellRendererParams<DemandRow>) => {
        if (!params.data?.purchaseOrderId) {
          return <span className="badge badge-warning">{tPurchase('demandsContent.pendingSupply')}</span>;
        }
        
        const badgeClass = params.data.purchaseOrderState === PO_STATE.DRAFT ? 'badge-draft' : 'badge-info';
        const label = params.data.purchaseOrderState === PO_STATE.DRAFT ? tPurchase('demandsContent.draft') : tPurchase('demandsContent.ordered');
        const poNumber = params.data.purchaseOrderNumber || '';
        const displayPo = poNumber.length > 8 ? poNumber.substring(0, 8) + '...' : poNumber;
        
        return (
          <Link href={`/purchase-orders/${params.data.purchaseOrderId}`} className="hover:opacity-80 transition-opacity inline-flex items-center">
            <span className={`badge ${badgeClass} cursor-pointer`} title={poNumber}>{label} {displayPo}</span>
          </Link>
        );
      }
    },
    {
      field: 'locationName',
      headerName: 'Location',
      flex: 1,
    },
    { field: 'quantity', headerName: 'Required Qty', width: 140, cellDataType: 'number' },
    {
      headerName: 'Stock Elsewhere',
      width: 200,
      // Disable sort/filter on this synthetic column (derived array ΓÇö no comparable scalar)
      sortable: false,
      filter: false,
      cellRenderer: (params: ICellRendererParams<DemandRow>) => (
        <StockElsewhereCell
          availableElsewhere={params.data?.availableElsewhere ?? []}
          requiredQty={Number(params.data?.quantity ?? 0)}
        />
      ),
    },
    {
      field: 'vendorName',
      headerName: 'Preferred Supplier',
      width: 180,
      valueFormatter: (params: { value: unknown }) => params.value ? String(params.value) : 'ΓÇö'
    },
    {
      field: 'createdOn',
      headerName: 'Date Requested',
      width: 140,
      valueFormatter: (params: { value: unknown }) => {
        if (!params.value) return 'ΓÇö';
        return new Date(params.value as string).toLocaleDateString();
      },
    },
  ], []);

  const handleDraftPOs = () => {
    if (selectedRows.length === 0) return;
    setIsModalOpen(true);
  };

  const handleModalSuccess = () => {
    setIsModalOpen(false);
    setIsLinkSlideOverOpen(false);
    setIsReallocateModalOpen(false);
    setIsInternalTransferModalOpen(false);
    setSelectedRows([]);
    setRefreshKey((k) => k + 1);
  };

  return (
      <>
          <DataGrid<DemandRow>
            refreshTrigger={refreshKey}
            endpoint={`/api/allocations/open`}
            columns={columns}
            gridKey="open-demands"
            searchPlaceholder="Search demands..."
            exportFileName="open-demands"
            fetchAll
            rowIdField="id"
            rowSelection="multiple"
            isRowSelectable={(rowNode) => !rowNode.data?.purchaseOrderId}
            onSelectionChanged={setSelectedRows}
            pageTitle={tPurchase('demandTitle')}
            headerActions={
              <div className="flex flex-wrap items-center justify-start lg:justify-end gap-3 w-full lg:w-auto">
                  {/* Group 1: PO Allocation */}
                  <div className="flex items-center gap-3">
                    <button
                      onClick={() => setIsLinkSlideOverOpen(true)}
                      disabled={selectedRows.length === 0}
                      className="px-4 py-2 text-sm font-bold rounded-lg transition-all bg-[#006b5c] text-white hover:brightness-110 disabled:opacity-50 disabled:cursor-not-allowed whitespace-nowrap"
                    >
                      {tPurchase('demandsContent.allocateToPo')} {selectedRows.length > 0 ? `(${selectedRows.length})` : ''}
                    </button>
                    <button
                      onClick={handleDraftPOs}
                      disabled={selectedRows.length === 0}
                      className="px-4 py-2 text-sm font-bold rounded-lg transition-all bg-[#006b5c] text-white hover:brightness-110 disabled:opacity-50 disabled:cursor-not-allowed whitespace-nowrap"
                    >
                      {tPurchase('demandsContent.draftPos')} {selectedRows.length > 0 ? `(${selectedRows.length})` : ''}
                    </button>
                  </div>

                  <div className="hidden lg:block h-5 w-px bg-[rgba(196,198,205,0.4)] shrink-0"></div>

                  {/* Group 2: Location Management */}
                  <div className="flex items-center gap-3">
                    <button
                      onClick={() => setIsReallocateModalOpen(true)}
                      disabled={selectedRows.length === 0}
                      className="px-4 py-2 text-sm font-bold rounded-lg transition-all bg-[#1A467F] text-white hover:brightness-110 disabled:opacity-50 disabled:cursor-not-allowed whitespace-nowrap"
                    >
                      {tPurchase('demandsContent.changeLocation')} {selectedRows.length > 0 ? `(${selectedRows.length})` : ''}
                    </button>
                    <button
                      onClick={() => setIsInternalTransferModalOpen(true)}
                      disabled={selectedRows.length === 0}
                      className="px-4 py-2 text-sm font-bold rounded-lg transition-all bg-[#1A467F] text-white hover:brightness-110 disabled:opacity-50 disabled:cursor-not-allowed whitespace-nowrap"
                    >
                      {tPurchase('demandsContent.internalTransfer')} {selectedRows.length > 0 ? `(${selectedRows.length})` : ''}
                    </button>
                  </div>
              </div>
            }
          />
      </>
      <DraftPOsModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        selectedDemands={selectedRows}
        onSuccess={handleModalSuccess}
      />
      <LinkToPOSlideOver
        isOpen={isLinkSlideOverOpen}
        onClose={() => setIsLinkSlideOverOpen(false)}
        demands={selectedRows}
        onRefresh={handleModalSuccess}
      />
      <ReallocateModal
        isOpen={isReallocateModalOpen}
        onClose={() => setIsReallocateModalOpen(false)}
        selectedDemands={selectedRows}
        onSuccess={handleModalSuccess}
      />
      <InternalTransferModal
        isOpen={isInternalTransferModalOpen}
        onClose={() => setIsInternalTransferModalOpen(false)}
        selectedDemands={selectedRows}
        onSuccess={handleModalSuccess}
      />
    </div>
  );
}

'use client';

import { useState, Suspense } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import { apiMutate } from '@/lib/api';
import { toast } from 'react-hot-toast';
import ProductSearchInput from '@/components/shared/ProductSearchInput';
import type { Product } from '@/components/shared/ProductSearchInput';
import EntityHeader from '@/components/shared/EntityHeader';
import DetailsLayout from '@/components/shared/DetailsLayout';

import React from 'react';
import LocationSelect from '@/components/shared/LocationSelect';
import SupplierSelect from '@/components/shared/SupplierSelect';
import { useTranslations } from 'next-intl';

interface DraftLine {
  id: string;
  productId: string;
  productNumber?: string;
  productName: string;
  quantityReceived: number;
}

interface CompletedLine {
  goodsReceivedLineId: string;
  productId: string;
  productNumber: string;
  productName: string;
  quantityReceived: string;
  matchStatus: string;
  orderNumber?: string;
}

function ReceivingFlow() {
  const t = useTranslations('goodsReceived');
  const tCommon = useTranslations('common');
  useDocumentTitle(t('flow.title'));
  const router = useRouter();

  // Header state
  const [vendorId, setVendorId] = useState<string | null>(null);
  const [locationId, setLocationId] = useState<string | null>(null);
  const [packingSlipNumber, setPackingSlipNumber] = useState<string>('');
  const [notes, setNotes] = useState<string>('');

  // Draft state
  const [draftLines, setDraftLines] = useState<DraftLine[]>([]);
  const [qtyToReceive, setQtyToReceive] = useState<string>('');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);

  // Flow state
  const [saving, setSaving] = useState(false);
  const [completed, setCompleted] = useState(false);
  const [completedLines, setCompletedLines] = useState<CompletedLine[]>([]);

  const handleProductSelect = (product: Product) => {
    setSelectedProduct(product);
    setQtyToReceive('1');
  };

  const addToDraft = () => {
    if (!selectedProduct) return;
    const qty = Number(qtyToReceive);
    if (qty <= 0) {
      toast.error(t('toast.qtyReq'));
      return;
    }

    // Check if product already in draft ΓÇö if so, add to existing quantity
    const existing = draftLines.find((l) => l.productId === selectedProduct.productId);
    if (existing) {
      setDraftLines(
        draftLines.map((l) =>
          l.productId === selectedProduct.productId
            ? { ...l, quantityReceived: l.quantityReceived + qty }
            : l,
        ),
      );
    } else {
      setDraftLines([
        ...draftLines,
        {
          id: Math.random().toString(36).substring(7),
          productId: selectedProduct.productId,
          productNumber: selectedProduct.productNumber,
          productName: selectedProduct.name,
          quantityReceived: qty,
        },
      ]);
    }

    setSelectedProduct(null);
    setQtyToReceive('');
  };

  const removeDraftLine = (id: string) => {
    setDraftLines(draftLines.filter((l) => l.id !== id));
  };

  const commitReception = async () => {
    if (draftLines.length === 0) return;
    if (!vendorId) {
      toast.error(t('toast.selectSupplier'));
      return;
    }
    if (!locationId) {
      toast.error(t('toast.selectLocation'));
      return;
    }
    setSaving(true);

    try {
      const result = await apiMutate<any>('/api/goods-received', 'POST', {
        vendorId,
        locationId,
        packingSlipNumber: packingSlipNumber || undefined,
        notes: notes || undefined,
        lines: draftLines.map((l) => ({
          productId: l.productId,
          quantityReceived: String(l.quantityReceived),
        })),
      });

      setCompletedLines(result.lines || []);
      toast.success(t('toast.confirmed'));
      setCompleted(true);
    } catch (err: any) {
      toast.error(err.message || t('toast.failed'));
    } finally {
      setSaving(false);
    }
  };

  // ΓöÇΓöÇ Match status badge ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const MatchStatusBadge = ({ status }: { status: string }) => {
    const styles: Record<string, { bg: string; color: string; label: string }> = {
      matched: { bg: 'rgba(16,185,129,0.12)', color: '#059669', label: t('matchStatus.matched') },
      unmatched: { bg: 'rgba(239,68,68,0.12)', color: '#dc2626', label: t('matchStatus.unmatched') },
      ambiguous: { bg: 'rgba(245,158,11,0.12)', color: '#d97706', label: t('matchStatus.ambiguous') },
    };
    const s = styles[status] || styles.unmatched;
    return (
      <span
        style={{
          display: 'inline-block',
          padding: '2px 8px',
          borderRadius: 6,
          fontSize: 11,
          fontWeight: 600,
          background: s.bg,
          color: s.color,
          letterSpacing: '0.02em',
        }}
      >
        {s.label}
      </span>
    );
  };

  // ΓöÇΓöÇ Completed screen ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  if (completed) {
    return (
      <DetailsLayout
        header={
          <EntityHeader
            title={t('completed.title')}
            subtitle={t('completed.subtitle')}
            actions={
              <div className="flex gap-2">
                <button className="btn btn-secondary" onClick={() => router.push('/receiving')}>
                  {t('completed.backToList')}
                </button>
                <button
                  className="btn btn-primary"
                  onClick={() => {
                    setCompleted(false);
                    setDraftLines([]);
                    setSelectedProduct(null);
                    setCompletedLines([]);
                    setVendorId(null);
                    setPackingSlipNumber('');
                    setNotes('');
                  }}
                >
                  {t('completed.newReception')}
                </button>
              </div>
            }
            showPrint={false}
          />
        }
      >
        <div className="flex flex-col gap-6">
          <div className="card flex flex-col gap-4">
            {(notes || packingSlipNumber) && (
              <div className="mb-4 flex gap-8 text-sm">
                {packingSlipNumber && (
                  <div>
                    <strong style={{ color: 'var(--text-muted)', display: 'block', marginBottom: 2 }}>
                      {t('labels.packingSlip')}:
                    </strong>
                    {packingSlipNumber}
                  </div>
                )}
                {notes && (
                  <div>
                    <strong style={{ color: 'var(--text-muted)', display: 'block', marginBottom: 2 }}>
                      {tCommon('columns.notes')}:
                    </strong>
                    {notes}
                  </div>
                )}
              </div>
            )}

            <div className="overflow-x-auto w-full">
              <table className="table-lines">
                <thead>
                  <tr>
                    <th>{tCommon('columns.product')}</th>
                    <th>{tCommon('columns.description')}</th>
                    <th style={{ width: 100, textAlign: 'right' }}>{tCommon('columns.received')}</th>
                    <th style={{ width: 120 }}>{t('columns.matchStatus')}</th>
                    <th style={{ width: 160 }}>{tCommon('columns.purchaseOrder')}</th>
                  </tr>
                </thead>
                <tbody>
                  {completedLines.map((line) => (
                    <tr key={line.goodsReceivedLineId}>
                      <td style={{ fontWeight: 600, fontSize: 12 }}>{line.productNumber || 'ΓÇö'}</td>
                      <td style={{ fontSize: 13 }}>{line.productName || 'ΓÇö'}</td>
                      <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontSize: 13 }}>
                        {line.quantityReceived}
                      </td>
                      <td>
                        <MatchStatusBadge status={line.matchStatus} />
                      </td>
                      <td>
                        {line.orderNumber ? (
                          <span style={{ fontWeight: 500, fontSize: 13, color: 'var(--accent)' }}>
                            {line.orderNumber}
                          </span>
                        ) : (
                          <span style={{ color: 'var(--text-muted)', fontSize: 12 }}>ΓÇö</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </DetailsLayout>
    );
  }

  // ΓöÇΓöÇ Main flow ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  return (
    <DetailsLayout
      header={
        <EntityHeader
          title={t('flow.title')}
          subtitle={t('flow.subtitle')}
          isSaving={saving}
          actions={
            <button
              className="btn btn-primary"
              onClick={commitReception}
              disabled={draftLines.length === 0 || saving || !vendorId || !locationId}
            >
              {t('flow.confirmReception')}
            </button>
          }
          showPrint={false}
        />
      }
    >
      <div className="flex flex-col gap-6">
        {/* Package Header */}
        <div className="card flex flex-col gap-4" style={{ height: 'fit-content' }}>
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
            <div>
              <label className="block mb-1 text-xs font-semibold" style={{ color: 'var(--text-muted)' }}>
                {t('labels.supplier')} *
              </label>
              <SupplierSelect
                value={vendorId}
                onChange={(s) => setVendorId(s?.vendorId || null)}
                placeholder={t('placeholders.selectSupplier')}
                required
              />
            </div>
            <div>
              <label className="block mb-1 text-xs font-semibold" style={{ color: 'var(--text-muted)' }}>
                {t('labels.location')} *
              </label>
              <LocationSelect
                value={locationId}
                onChange={setLocationId}
                placeholder={t('placeholders.selectLocation')}
                required
              />
            </div>
            <div>
              <label className="block mb-1 text-xs font-semibold" style={{ color: 'var(--text-muted)' }}>
                {t('labels.packingSlip')}
              </label>
              <input
                className="input"
                placeholder={t('placeholders.packingSlip')}
                value={packingSlipNumber}
                onChange={(e) => setPackingSlipNumber(e.target.value)}
              />
            </div>
            <div>
              <label className="block mb-1 text-xs font-semibold" style={{ color: 'var(--text-muted)' }}>
                {tCommon('columns.notes')}
              </label>
              <input
                className="input"
                placeholder={t('placeholders.notes')}
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
              />
            </div>
          </div>

          {/* Product scanner */}
          <h3 className="section-heading mb-0 mt-2">{t('flow.scanProduct')}</h3>

          <div className="flex items-end gap-3">
            {!selectedProduct ? (
              <div className="flex-1">
                <ProductSearchInput
                  onSelect={handleProductSelect}
                  placeholder={t('placeholders.searchProduct')}
                />
              </div>
            ) : (
              <div className="flex-1 flex flex-col">
                <label className="block mb-1 text-xs font-medium" style={{ color: 'var(--text-muted)' }}>
                  {t('flow.selectedProduct', { fallback: 'Selected Product' })}
                </label>
                <div
                  className="text-sm px-3 flex items-center w-full border rounded outline-none"
                  style={{ 
                    background: 'var(--bg-card)', 
                    color: 'var(--text-primary)', 
                    borderColor: 'var(--border)',
                    height: '38px',
                    whiteSpace: 'nowrap',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis'
                  }}
                  title={`${selectedProduct.productNumber} ΓÇö ${selectedProduct.name}`}
                >
                  <span style={{ fontWeight: 600, marginRight: 8, color: 'var(--accent)' }}>{selectedProduct.productNumber}</span>
                  <span style={{ color: 'var(--text-muted)', overflow: 'hidden', textOverflow: 'ellipsis' }}>{selectedProduct.name}</span>
                </div>
              </div>
            )}

            {selectedProduct && (
              <>
                <div style={{ width: 100 }}>
                  <label className="block mb-1 text-xs font-medium" style={{ color: 'var(--text-muted)' }}>
                    {tCommon('columns.qty')}
                  </label>
                  <input
                    type="number"
                    min="0"
                    step="any"
                    className="input w-full"
                    value={qtyToReceive}
                    onChange={(e) => setQtyToReceive(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') addToDraft();
                    }}
                  />
                </div>
                <button className="btn btn-primary" onClick={addToDraft}>
                  {tCommon('add')}
                </button>
                <button
                  className="btn btn-secondary"
                  onClick={() => {
                    setSelectedProduct(null);
                    setQtyToReceive('');
                  }}
                >
                  {tCommon('cancel')}
                </button>
              </>
            )}
          </div>


        </div>

        {/* Draft Cart */}
        <div className="card flex flex-col gap-4" style={{ height: 'fit-content' }}>
          <h3 className="section-heading">{t('flow.itemsReceived')}</h3>

          {draftLines.length === 0 ? (
            <p style={{ color: 'var(--text-muted)', fontSize: 14 }}>{t('flow.noItems')}</p>
          ) : (
            <div className="overflow-x-auto w-full">
              <table className="table-lines">
                <thead>
                  <tr>
                    <th>{tCommon('columns.product')}</th>
                    <th>{tCommon('columns.description')}</th>
                    <th style={{ width: 100, textAlign: 'right' }}>{tCommon('columns.qty')}</th>
                    <th style={{ width: 80 }}></th>
                  </tr>
                </thead>
                <tbody>
                  {draftLines.map((line) => (
                    <tr key={line.id}>
                      <td style={{ fontWeight: 600, fontSize: 12 }}>{line.productNumber || 'ΓÇö'}</td>
                      <td style={{ fontSize: 13 }}>{line.productName || 'ΓÇö'}</td>
                      <td
                        style={{
                          textAlign: 'right',
                          fontVariantNumeric: 'tabular-nums',
                          fontSize: 13,
                        }}
                      >
                        {line.quantityReceived}
                      </td>
                      <td style={{ textAlign: 'right' }}>
                        <button
                          className="btn btn-secondary btn-sm"
                          style={{ color: 'var(--danger)', borderColor: 'var(--danger)' }}
                          onClick={() => removeDraftLine(line.id)}
                        >
                          Γ£ò
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>

      <style jsx>{`
        .table-lines {
          width: 100%;
          border-collapse: collapse;
          margin-bottom: 0;
        }
        .table-lines th {
          text-align: left;
          padding: 10px 12px;
          font-size: 11px;
          font-weight: 700;
          text-transform: uppercase;
          letter-spacing: 0.05em;
          color: var(--text-muted);
          border-bottom: 2px solid var(--border);
        }
        .table-lines td {
          padding: 12px;
          font-size: 13px;
          border-bottom: 1px solid var(--border);
          vertical-align: middle;
        }
      `}</style>
    </DetailsLayout>
  );
}

export default function ReceivingPage() {
  const tCommon = useTranslations('common');
  return (
    <Suspense fallback={<p style={{ padding: 20 }}>{tCommon('loading')}</p>}>
      <ReceivingFlow />
    </Suspense>
  );
}

'use client';

import React, { useState, useCallback, useMemo } from 'react';
import { useTranslations } from 'next-intl';
import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import DataGrid from '@/components/DataGrid';
import Link from 'next/link';
import ReceiveReturnSlideOver from './ReceiveReturnSlideOver';
import { RETURN_STATE } from '@modbm/shared';

export default function ReceivingReturnsPage() {
    const tCommon = useTranslations('common');
    useDocumentTitle('Customer Returns Queue');
    const [refreshKey, setRefreshKey] = useState(0);

    const [slideOverOpen, setSlideOverOpen] = useState(false);
    const [selectedReturn, setSelectedReturn] = useState<any>(null);

    const handleReceive = useCallback((returnRecord: any) => {
        setSelectedReturn(returnRecord);
        setSlideOverOpen(true);
    }, []);

    const handleSlideOverClose = useCallback(() => {
        setSlideOverOpen(false);
        setSelectedReturn(null);
    }, []);

    const triggerRefresh = useCallback(() => setRefreshKey(k => k + 1), []);

    // Fetch confirmed and partially received returns globally
    const gridEndpoint = `/api/sales-returns?stateCode=${RETURN_STATE.CONFIRMED},${RETURN_STATE.PARTIALLY_RECEIVED}`;

    const gridColumns: any[] = useMemo(() => [
        { field: 'returnNumber', headerName: 'Return No', width: 140 },
        { field: 'orderNumber', headerName: 'Order No', width: 140 },
        { field: 'createdOn', headerName: tCommon('columns.date'), width: 120, valueFormatter: (p: any) => p.value ? new Date(p.value).toLocaleDateString() : '' },
        { 
            field: 'lines', 
            headerName: 'Lines', 
            width: 100,
            cellRenderer: (p: any) => {
                if (!p.value) return null;
                return (
                    <span className="badge badge-sm badge-info">
                        {p.value.length} items
                    </span>
                );
            }
        },
        { field: 'notes', headerName: tCommon('columns.notes'), flex: 1, minWidth: 200 }
    ], [tCommon]);

    return (
        <>
            <DataGrid 
                refreshTrigger={refreshKey}
                endpoint={gridEndpoint} 
                columns={gridColumns} 
                gridKey="returns-receiving-list"
                fetchAll
                rowIdField="returnId"
                onRowClicked={handleReceive}
                pageTitle="Customer Returns"
            />

            <ReceiveReturnSlideOver 
                isOpen={slideOverOpen} 
                onClose={handleSlideOverClose} 
                returnRecord={selectedReturn} 
                onRefresh={triggerRefresh} 
            />
        </>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import StateBadge from '@/components/StateBadge';
import { ValidState } from '@/types/states';
import { apiFetch } from '@/lib/api';
import Link from 'next/link';

/**
 * FulfillmentSection ΓÇö Combined read-only picking + shipping status
 * for the Sales Order detail page. Single table showing the full
 * fulfillment pipeline per line: Ordered ΓåÆ Picked ΓåÆ Shipped ΓåÆ Available.
 */

interface ShippingLine {
    salesOrderLineId: string;
    lineNumber: number;
    productId: string;
    productNumber: string;
    productDescription: string;
    isPhysical: boolean;
    quantity: string;
    quantityPicked: string;
    quantityShipped: string;
    availableToShip: string;
}

interface ShipmentSummary {
    shipmentId: string;
    shipmentNumber: string;
    stateCode: string;
    notes: string | null;
    trackingNumber: string | null;
    createdOn: string;
    lineCount: number;
}

interface ShippingContext {
    lines: ShippingLine[];
    shipments: ShipmentSummary[];
}

interface PickingSummaryLine {
    salesOrderLineId: string;
    lineNumber: number;
    productId: string;
    productNumber: string;
    productDescription: string;
    quantity: string;
    quantityPicked: string;
    remaining: string;
    isFullyPicked: boolean;
    isPhysical: boolean;
    onHand: string;
}

interface PickingSummary {
    totalLines: number;
    fullyPickedLines: number;
    isFullyPicked: boolean;
    lines: PickingSummaryLine[];
}

interface Props {
    orderId: string;
    pickingSummary: PickingSummary | null;
}

export default function FulfillmentSection({ orderId, pickingSummary }: Props) {
    const t = useTranslations('fulfillment');
    const tShipping = useTranslations('shipping');
    const tCommon = useTranslations('common');

    const [shippingCtx, setShippingCtx] = useState<ShippingContext | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        setLoading(true);
        apiFetch<ShippingContext>(`/api/sales-orders/${orderId}/shipping-context`)
            .then(setShippingCtx)
            .catch(() => setShippingCtx(null))
            .finally(() => setLoading(false));
    }, [orderId]);

    // Merge data: picking summary provides on-hand and remaining; shipping context provides shipped/available-to-ship.
    // Use shipping context lines as the primary source (it has shipped + available).
    // Enrich with on-hand from picking summary.
    const pickingMap = new Map(
        (pickingSummary?.lines ?? []).map(l => [l.salesOrderLineId, l])
    );

    const physicalLines = (shippingCtx?.lines ?? []).filter(l => l.isPhysical);

    return (
        <div id="fulfillment-section" className="card">
            <div className="flex items-center justify-between mb-4">
                <h3 className="section-heading">
                    <span className="material-symbols-outlined">local_shipping</span>
                    {t('title')}
                </h3>
            </div>

            {loading ? (
                <div className="text-center py-6 text-sm" style={{ color: 'var(--text-muted)' }}>
                    {tCommon('loading')}
                </div>
            ) : !shippingCtx ? (
                <div className="text-center py-6 text-sm" style={{ color: 'var(--text-muted)' }}>
                    {t('noData')}
                </div>
            ) : (
                <>
                    <table className="table-lines">
                        <thead>
                            <tr>
                                <th>{t('columns.product')}</th>
                                <th style={{ textAlign: 'right' }}>{t('columns.ordered')}</th>
                                <th style={{ textAlign: 'right' }}>{t('columns.picked')}</th>
                                <th style={{ textAlign: 'right' }}>{t('columns.onHand')}</th>
                                <th style={{ textAlign: 'right' }}>{t('columns.shipped')}</th>
                                <th style={{ textAlign: 'right' }}>{t('columns.readyToShip')}</th>
                            </tr>
                        </thead>
                        <tbody>
                            {physicalLines.map(line => {
                                const ordered = parseFloat(line.quantity);
                                const picked = parseFloat(line.quantityPicked);
                                const shipped = parseFloat(line.quantityShipped);
                                const available = parseFloat(line.availableToShip);
                                const pickLine = pickingMap.get(line.salesOrderLineId);
                                const onHand = pickLine ? parseFloat(pickLine.onHand) : null;
                                const isPicked = picked >= ordered;
                                const isShipped = shipped >= ordered;

                                return (
                                    <tr key={line.salesOrderLineId} className={isShipped ? 'opacity-50' : ''}>
                                        <td>
                                            <div className="font-bold text-sm">
                                                {line.productId ? (
                                                    <Link href={`/products/${line.productId}`} style={{ color: 'var(--accent)', textDecoration: 'none' }}>
                                                        {line.productNumber}
                                                    </Link>
                                                ) : line.productNumber}
                                            </div>
                                            <div className="text-xs text-[var(--text-muted)] truncate max-w-[250px]">{line.productDescription}</div>
                                        </td>
                                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                            {ordered.toLocaleString()}
                                        </td>
                                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                            <span className={isPicked ? 'text-[var(--success)]' : picked > 0 ? 'text-[var(--warning)]' : ''}>
                                                {picked.toLocaleString()}
                                            </span>
                                        </td>
                                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', color: 'var(--text-muted)' }}>
                                            {onHand !== null ? onHand.toLocaleString() : 'ΓÇö'}
                                        </td>
                                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                            <span className={isShipped ? 'text-[var(--success)]' : shipped > 0 ? 'text-[var(--warning)]' : ''}>
                                                {shipped.toLocaleString()}
                                            </span>
                                        </td>
                                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                            <span className={available > 0 ? 'font-semibold text-[var(--accent)]' : 'text-[var(--text-muted)]'}>
                                                {available.toLocaleString()}
                                            </span>
                                        </td>
                                    </tr>
                                );
                            })}
                            {physicalLines.length === 0 && (
                                <tr>
                                    <td colSpan={6} className="py-6 text-center text-sm text-[var(--text-muted)]">
                                        {t('noPhysicalLines')}
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>

                </>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { apiFetch } from '@/lib/api';


interface Macro {
  macroId: string;
  name: string;
  macroType: string;
  content: string;
}

interface QuoteGenerationDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onGenerate: (text: string) => Promise<void>;
}

export default function QuoteGenerationDialog({ isOpen, onClose, onGenerate }: QuoteGenerationDialogProps) {
  const t = useTranslations('salesOrders');
  const tCommon = useTranslations('common');
  const tSettings = useTranslations('admin.settings');

  const [macros, setMacros] = useState<Macro[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [selectedMacroId, setSelectedMacroId] = useState<string>('');
  const [customText, setCustomText] = useState('');
  const [generating, setGenerating] = useState(false);

  useEffect(() => {
    if (isOpen) {
      loadMacros();
      setSelectedMacroId('');
      setCustomText('');
      setError(null);
    }
  }, [isOpen]);

  const loadMacros = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await apiFetch<Macro[]>('/api/macros');
      const textMacros = data.filter(m => m.macroType === 'text_template');
      setMacros(textMacros);
    } catch (err: any) {
      setError(err.message || 'Failed to load macros');
    } finally {
      setLoading(false);
    }
  };

  const handleMacroChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const id = e.target.value;
    setSelectedMacroId(id);
    const macro = macros.find(m => m.macroId === id);
    if (macro) {
      setCustomText(macro.content);
    }
  };

  const handleGenerate = async () => {
    setGenerating(true);
    setError(null);
    try {
      await onGenerate(customText);
      onClose();
    } catch (err: any) {
      setError(err.message || 'Failed to generate quote');
    } finally {
      setGenerating(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-md flex flex-col overflow-hidden">
        <div className="px-6 py-4 border-b border-gray-200 flex justify-between items-center bg-gray-50">
          <h2 className="text-xl font-bold text-gray-900">{t('generateQuoteTitle')}</h2>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600">
            <span className="material-symbols-outlined">close</span>
          </button>
        </div>

        <div className="p-6 flex flex-col gap-4">
          {error && (
            <div className="p-3 rounded bg-red-50 text-red-700 text-sm border border-red-200">
              {error}
            </div>
          )}

          <div>
            <label className="block text-sm font-medium mb-1 text-gray-700">
              {t('labels.quoteMacro')}
            </label>
            {loading ? (
              <div className="text-sm text-gray-500">{tCommon('loading')}</div>
            ) : (
              <select
                className="input w-full"
                value={selectedMacroId}
                onChange={handleMacroChange}
              >
                <option value="">{t('placeholders.selectMacro')}</option>
                {macros.map(m => (
                  <option key={m.macroId} value={m.macroId}>
                    {m.name}
                  </option>
                ))}
              </select>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium mb-1 text-gray-700">
              {t('labels.quoteText')}
            </label>
            <textarea
              className="input w-full font-sans text-sm"
              rows={6}
              value={customText}
              onChange={(e) => setCustomText(e.target.value)}
              placeholder={t('placeholders.quoteText') || 'Enter text to display on the quote PDF...'}
            />
          </div>

          <div className="flex justify-end gap-2 mt-4 pt-4 border-t border-gray-100">
            <button
              className="btn btn-secondary"
              onClick={onClose}
              disabled={generating}
            >
              {tCommon('cancel')}
            </button>
            <button
              className="btn btn-primary flex items-center gap-2"
              onClick={handleGenerate}
              disabled={generating}
            >
              {generating && <span className="material-symbols-outlined animate-spin text-sm">progress_activity</span>}
              {t('buttons.generate')}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useTranslations } from 'next-intl';
import { apiMutate } from '@/lib/api';
import { formatAmount } from '@/lib/currency';
import { computeLinePrice, computeReturnCreditSummary } from '@modbm/shared';
import { formatLocationDisplay } from '@/lib/formatters';

import type { OrderDetail, OrderReturn, TaxCategory } from './types';
import {
    RETURN_STATE,
    RETURN_TRANSITIONS,
    RETURN_LIFECYCLE,
    SALES_ORDER_STATE,
    isBackTransition as sharedIsBackTransition,
} from '@modbm/shared';
import StateBadge, { StateName } from '@/components/StateBadge';
import { ValidState } from '@/types/states';
import { useSettings } from '@/components/SettingsProvider';

function PurchaseReturnStateBadge({ state }: { state: ValidState }) {
    const t = useTranslations('common.states');
    return <span className={`badge badge-${state}`}>{t(state)}</span>;
}

interface NewReturnLine {
    salesOrderLineId: string;
    quantityReturned: string;
    reason: string;
    returnFee: string;
    feeMode: 'absolute' | 'percentage';
    originalAmount: number;
}

interface ReturnsSectionProps {
    orderId: string;
    order: OrderDetail;
    returns: OrderReturn[];
    returnsLoading: boolean;
    showCreateReturn: boolean;
    setShowCreateReturn: (v: boolean) => void;
    setError: (msg: string) => void;
    loadReturns: () => Promise<void>;
    loadOrder: (autoTransitions?: any[], showSpinner?: boolean) => Promise<void>;
    pickingSummary?: any;
    taxCategories: TaxCategory[];
    locations: { locationId: string; name: string; code?: string }[];
}

export default function ReturnsSection({
    orderId, order, returns, returnsLoading,
    showCreateReturn, setShowCreateReturn,
    setError, loadReturns, loadOrder, pickingSummary, taxCategories, locations,
}: ReturnsSectionProps) {
  const { baseCurrency } = useSettings();
    const t = useTranslations();
    const tCommon = useTranslations('common');
    const tSales = useTranslations('salesOrders');
    const tConfirm = useTranslations('confirm');

    // Local state
    const [saving, setSaving] = useState(false);
    const [returnLocations, setReturnLocations] = useState<Record<string, string>>({});
    const [newReturnNotes, setNewReturnNotes] = useState('');
    const [newReturnLines, setNewReturnLines] = useState<NewReturnLine[]>(() =>
        order.lines.map((l) => ({
            salesOrderLineId: l.salesOrderLineId,
            quantityReturned: '',
            reason: '',
            returnFee: '0',
            feeMode: 'absolute' as const,
            originalAmount: parseFloat(l.amount || '0'),
        })),
    );

    const handleCancel = () => {
        setShowCreateReturn(false);
        setNewReturnLines(
            order.lines.map((l) => ({
                salesOrderLineId: l.salesOrderLineId,
                quantityReturned: '',
                reason: '',
                returnFee: '0',
                feeMode: 'absolute' as const,
                originalAmount: parseFloat(l.amount || '0'),
            })),
        );
        setNewReturnNotes('');
    };

    const handleSave = async () => {
        setSaving(true);
        setError('');
        try {
            const lines = newReturnLines
                .filter((l) => l.quantityReturned && parseFloat(l.quantityReturned) > 0)
                .map((l) => ({
                    salesOrderLineId: l.salesOrderLineId,
                    quantityReturned: l.quantityReturned,
                    reason: l.reason || undefined,
                    returnFee: l.returnFee || '0',
                }));
            await apiMutate(`/api/sales-orders/${orderId}/returns`, 'POST', {
                notes: newReturnNotes || undefined,
                lines,
            });
            handleCancel();
            await loadReturns();
            await loadOrder(undefined, false);
        } catch (err) {
            setError(err instanceof Error ? err.message : tCommon('errors.failedToCreateReturn'));
        } finally {
            setSaving(false);
        }
    };

    return (
        <div className="card">
            <div className="flex items-center justify-between mb-2">
                <h3 className="section-heading">
                    {/* eslint-disable-next-line i18next/no-literal-string */}
                    <span className="material-symbols-outlined">assignment_return</span>
                    {tSales('returnsHeading')}
                </h3>
                {!showCreateReturn && [
                    SALES_ORDER_STATE.PICKING,
                    SALES_ORDER_STATE.SHIPPED, 
                    SALES_ORDER_STATE.INVOICED, 
                    SALES_ORDER_STATE.LEGACY
                ].includes(order.stateCode as any) && (
                    <button
                        className="btn btn-secondary btn-sm"
                        onClick={() => setShowCreateReturn(true)}
                    >
                        {tSales('buttons.createReturn')}
                    </button>
                )}
            </div>

            {/* Create return form */}
            {showCreateReturn && (
                <div style={{ marginBottom: 16, padding: 16, borderRadius: 8, background: 'rgba(59, 130, 246, 0.05)', border: '1px solid rgba(59, 130, 246, 0.2)' }}>
                    <div className="flex items-center justify-between mb-3">
                        <strong style={{ fontSize: 13, display: 'flex', alignItems: 'center', gap: 6 }}>
                            {/* eslint-disable-next-line i18next/no-literal-string */}
                            <span className="material-symbols-outlined text-[16px]">assignment_return</span>
                            {tSales('newReturn')}
                        </strong>
                        <button
                            style={{ background: 'none', border: 'none', color: 'var(--text-muted)', cursor: 'pointer', fontSize: 16 }}
                            onClick={handleCancel}
                        >
                            {/* eslint-disable-next-line i18next/no-literal-string */}
                            <span aria-hidden>Γ£ò</span>
                        </button>
                    </div>

                    <div style={{ marginBottom: 12 }}>
                        <input
                            className="input w-full"
                            value={newReturnNotes}
                            onChange={(e) => setNewReturnNotes(e.target.value)}
                            placeholder={tSales('placeholders.returnNotes')}
                        />
                    </div>

                    <table className="table-lines" style={{ marginBottom: 12 }}>
                        <thead>
                            <tr>
                                <th style={{ width: 40 }}>{tSales('columns.lineNumber')}</th>
                                <th>{tSales('columns.product')}</th>
                                <th>{tSales('columns.description')}</th>
                                <th style={{ width: 90, textAlign: 'right' }}>{tSales('columns.shipped')}</th>
                                <th style={{ width: 100, textAlign: 'right' }}>{tSales('columns.returnQty')}</th>
                                <th style={{ width: 180 }}>{tSales('columns.reason')}</th>
                                <th style={{ width: 140, textAlign: 'right' }}>{tSales('columns.fee')}</th>
                            </tr>
                        </thead>
                        <tbody>
                            {order.lines.map((line, idx) => {
                                const rl = newReturnLines[idx];
                                if (!rl) return null;
                                const pLine = pickingSummary?.lines?.find((pl: any) => pl.salesOrderLineId === line.salesOrderLineId);
                                const shippedQty = pLine && pLine.quantityShipped != null ? parseFloat(pLine.quantityShipped) : 0;
                                return (
                                    <tr key={line.salesOrderLineId}>
                                        <td style={{ color: 'var(--text-muted)' }}>{line.lineNumber}</td>
                                        <td style={{ fontWeight: 600, fontSize: 12 }}>
                                            {line.productNumber || line.productId?.substring(0, 8) || 'ΓÇö'}
                                        </td>
                                        <td>{line.productDescription || 'ΓÇö'}</td>
                                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                            {shippedQty}
                                        </td>
                                        <td style={{ textAlign: 'right' }}>
                                            <input
                                                className="input"
                                                type="number"
                                                min="0"
                                                max={shippedQty || line.quantity}
                                                step="1"
                                                style={{
                                                    width: 70, padding: '2px 6px', borderRadius: 4,
                                                    border: '1px solid var(--border)', background: 'var(--surface)',
                                                    color: 'var(--text)', fontSize: 13, textAlign: 'right',
                                                }}
                                                value={rl.quantityReturned}
                                                onChange={(e) => {
                                                    const updated = [...newReturnLines];
                                                    updated[idx] = { ...rl, quantityReturned: e.target.value };
                                                    setNewReturnLines(updated);
                                                }}
                                                placeholder={tSales('placeholders.zero')}
                                            />
                                        </td>
                                        <td>
                                            <input
                                                className="input"
                                                style={{ width: '100%' }}
                                                value={rl.reason}
                                                onChange={(e) => {
                                                    const updated = [...newReturnLines];
                                                    updated[idx] = { ...rl, reason: e.target.value };
                                                    setNewReturnLines(updated);
                                                }}
                                                placeholder={tSales('placeholders.reason')}
                                            />
                                        </td>
                                        <td style={{ textAlign: 'right' }}>
                                            <div className="flex items-center gap-1">
                                                <select
                                                    className="input"
                                                    style={{ width: 50, fontSize: 11, padding: '4px 6px' }}
                                                    value={rl.feeMode}
                                                    onChange={(e) => {
                                                        const updated = [...newReturnLines];
                                                        const mode = e.target.value as 'absolute' | 'percentage';
                                                        if (mode === 'percentage' && rl.feeMode === 'absolute') {
                                                            const pct = rl.originalAmount > 0
                                                                ? ((parseFloat(rl.returnFee || '0') / rl.originalAmount) * 100).toFixed(1)
                                                                : '0';
                                                            updated[idx] = { ...rl, feeMode: mode, returnFee: pct };
                                                        } else if (mode === 'absolute' && rl.feeMode === 'percentage') {
                                                            const abs = (rl.originalAmount * parseFloat(rl.returnFee || '0') / 100).toFixed(2);
                                                            updated[idx] = { ...rl, feeMode: mode, returnFee: abs };
                                                        }
                                                        setNewReturnLines(updated);
                                                    }}
                                                >
                                                    <option value="absolute">$</option>
                                                    <option value="percentage">%</option>
                                                </select>
                                                <input
                                                    className="input"
                                                    type="number"
                                                    min="0"
                                                    step="0.01"
                                                    style={{ width: 80, textAlign: 'right' }}
                                                    value={rl.returnFee}
                                                    onChange={(e) => {
                                                        const updated = [...newReturnLines];
                                                        updated[idx] = { ...rl, returnFee: e.target.value };
                                                        setNewReturnLines(updated);
                                                    }}
                                                    onBlur={() => {
                                                        if (rl.feeMode === 'percentage') {
                                                            const updated = [...newReturnLines];
                                                            const abs = (rl.originalAmount * parseFloat(rl.returnFee || '0') / 100).toFixed(2);
                                                            updated[idx] = { ...rl, feeMode: 'absolute', returnFee: abs };
                                                            setNewReturnLines(updated);
                                                        }
                                                    }}
                                                />
                                            </div>
                                        </td>
                                    </tr>
                                );
                            })}
                            {/* Create form totals */}
                            {(() => {
                                const activeFLines = newReturnLines.filter(l => l.quantityReturned && parseFloat(l.quantityReturned) > 0);
                                if (activeFLines.length === 0) return null;
                                const cc = order.currencyCode || 'AUD';
                                const summary = computeReturnCreditSummary(
                                    activeFLines.map((rl) => {
                                        const origLine = order.lines.find(l => l.salesOrderLineId === rl.salesOrderLineId);
                                        const taxCat = taxCategories.find(c => c.taxCategoryId === origLine?.taxCategoryId);
                                        return {
                                            quantity: parseFloat(rl.quantityReturned || '0'),
                                            pricePerUnit: parseFloat(origLine?.pricePerUnit || '0'),
                                            discountPercentage: parseFloat(origLine?.discountPercentage || '0'),
                                            taxRate: parseFloat(taxCat?.rate || '0'),
                                            returnFee: parseFloat(rl.returnFee || '0'),
                                        };
                                    }),
                                );
                                const { subtotal, totalTax, totalFees, netCredit } = summary;
                                return (
                                    <>
                                        <tr style={{ borderTop: '2px solid var(--border)' }}>
                                            <td colSpan={5} style={{ textAlign: 'right', fontWeight: 600, fontSize: 12, color: 'var(--text-muted)' }}>
                                                {tSales('returns.totalCredit')}
                                            </td>
                                            <td></td>
                                            <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontWeight: 600 }}>
                                                {formatAmount(subtotal, cc)}
                                            </td>
                                        </tr>
                                        <tr>
                                            <td colSpan={5} style={{ textAlign: 'right', fontWeight: 600, fontSize: 12, color: 'var(--text-muted)' }}>
                                                {tSales('columns.tax')}
                                            </td>
                                            <td></td>
                                            <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontWeight: 600 }}>
                                                {formatAmount(totalTax, cc)}
                                            </td>
                                        </tr>
                                        <tr>
                                            <td colSpan={5} style={{ textAlign: 'right', fontWeight: 600, fontSize: 12, color: 'var(--text-muted)' }}>
                                                {tSales('returns.totalFees')}
                                            </td>
                                            <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontWeight: 600 }}>
                                                {totalFees > 0 ? `ΓêÆ${formatAmount(totalFees, cc)}` : formatAmount(0, cc)}
                                            </td>
                                            <td></td>
                                        </tr>
                                        <tr>
                                            <td colSpan={5} style={{ textAlign: 'right', fontWeight: 700, fontSize: 13 }}>
                                                {tSales('returns.netCredit')}
                                            </td>
                                            <td></td>
                                            <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontWeight: 700, fontSize: 13 }}>
                                                {formatAmount(netCredit, cc)}
                                            </td>
                                        </tr>
                                    </>
                                );
                            })()}
                        </tbody>
                    </table>

                    <div className="flex items-center gap-2">
                        <button
                            className="btn btn-primary btn-sm"
                            disabled={saving || newReturnLines.every((l) => !l.quantityReturned || parseFloat(l.quantityReturned) <= 0)}
                            onClick={handleSave}
                        >
                            {tSales('buttons.saveReturn')}
                        </button>
                        <button className="btn btn-secondary btn-sm" onClick={handleCancel}>
                            {tCommon('cancel')}
                        </button>
                    </div>
                </div>
            )}

            {/* Existing returns list */}
            {returnsLoading ? (
                <p className="text-sm" style={{ color: 'var(--text-muted)' }}>{tSales('loadingReturns')}</p>
            ) : returns.length === 0 && !showCreateReturn ? (
                <div className="text-center py-6 text-sm" style={{ color: 'var(--text-muted)' }}>
                    {tSales('noReturns')}
                </div>
            ) : (
                <div className="space-y-3">
                    {returns.map((ret) => {
                        let allowedRetTransitions = RETURN_TRANSITIONS[ret.stateCode] || [];
                        if (ret.stateCode === RETURN_STATE.CONFIRMED || ret.stateCode === RETURN_STATE.PARTIALLY_RECEIVED) {
                            allowedRetTransitions = allowedRetTransitions.filter((s: string) => s !== RETURN_STATE.RECEIVED && s !== RETURN_STATE.PARTIALLY_RECEIVED);
                        }
                        const isRetEditable = ret.stateCode === RETURN_STATE.DRAFT;
                        return (
                            <div
                                key={ret.returnId}
                                style={{
                                    padding: 14,
                                    borderRadius: 8,
                                    border: '1px solid var(--border)',
                                    background: 'var(--bg-card, #fff)',
                                }}
                            >
                                <div className="flex items-center justify-between mb-3">
                                    <div className="flex items-center gap-3">
                                        <span style={{ fontWeight: 700, fontSize: 13 }}>{ret.returnNumber}</span>
                                        <PurchaseReturnStateBadge state={ret.stateCode as ValidState} />
                                        <span className="text-xs" style={{ color: 'var(--text-muted)' }}>
                                            {new Date(ret.createdOn).toLocaleString()}
                                            {ret.createdBy && ` ${tCommon('by')} ${ret.createdBy}`}
                                        </span>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <div className="flex gap-2">
                                        {allowedRetTransitions.map((s: string) => (
                                            <button
                                                key={s}
                                                className={`btn btn-sm ${s === 'cancelled' ? 'btn-danger' : 'btn-primary'}`}
                                                onClick={async () => {
                                                    if (s === RETURN_STATE.PROCESSED) {
                                                        if (!confirm(tConfirm('processReturn'))) return;
                                                    }
                                                    try {
                                                        await apiMutate(`/api/sales-orders/${orderId}/returns/${ret.returnId}/state`, 'PATCH', {
                                                            stateCode: s
                                                        });
                                                        await loadReturns();
                                                        await loadOrder(undefined, false);
                                                    } catch (err) {
                                                        setError(err instanceof Error ? err.message : tCommon('errors.failedToChangeReturnState'));
                                                    }
                                                }}
                                            >
                                                ΓåÆ <StateName state={s as ValidState} />
                                            </button>
                                        ))}
                                        <button
                                            className="btn btn-secondary btn-sm"
                                            onClick={async () => {
                                                try {
                                                    const { apiFetchBlob } = await import('@/lib/api');
                                                    const blob = await apiFetchBlob(`/api/reports/hooks/return-slip/run?id=${ret.returnId}&context=sales-return`, { method: 'POST' });
                                                    const url = URL.createObjectURL(blob);
                                                    window.open(url, '_blank');
                                                } catch (err) {
                                                    setError(err instanceof Error ? err.message : tCommon('errors.failedToGenerateReport'));
                                                }
                                            }}
                                        >
                                            {tSales('buttons.returnSlip')}
                                        </button>
                                        {ret.stateCode === RETURN_STATE.PROCESSED && (
                                            <button
                                                className="btn btn-secondary btn-sm"
                                                onClick={async () => {
                                                    try {
                                                        const { apiFetchBlob } = await import('@/lib/api');
                                                        const blob = await apiFetchBlob(`/api/reports/hooks/sales-return-credit/run?id=${ret.returnId}&context=sales-return`, { method: 'POST' });
                                                        const url = URL.createObjectURL(blob);
                                                        window.open(url, '_blank');
                                                    } catch (err) {
                                                        // Fallback to existing error setter
                                                        setError(err instanceof Error ? err.message : tCommon('errors.failedToGenerateReport'));
                                                    }
                                                }}
                                            >
                                                {tSales('buttons.salesCredit')}
                                            </button>
                                        )}
                                        </div>
                                    </div>
                                </div>

                                {ret.notes && (
                                    <p className="text-xs mb-2" style={{ color: 'var(--text-secondary)' }}>
                                        {ret.notes}
                                    </p>
                                )}

                                {ret.creditNoteNumber && (
                                    <div className="flex items-center gap-2 mb-2 text-xs" style={{ color: 'var(--text-secondary)' }}>
                                        <span className="material-symbols-outlined" style={{ fontSize: 14 }}>receipt_long</span>
                                        <span style={{ fontWeight: 600 }}>{tSales('returns.creditNote')}:</span>
                                        <span>{ret.creditNoteNumber}</span>
                                    </div>
                                )}

                                <table className="table-lines">
                                    <thead>
                                        <tr>
                                            <th style={{ width: 150 }}>{tSales('columns.product')}</th>
                                            <th>{tSales('columns.description')}</th>
                                            <th style={{ width: 90, textAlign: 'right' }}>{tSales('columns.returnQty')}</th>
                                            <th style={{ textAlign: 'right' }}>{tSales('columns.unitPrice')}</th>
                                            <th style={{ textAlign: 'right' }}>{tSales('columns.discountPct')}</th>
                                            <th style={{ textAlign: 'right' }}>{tSales('columns.tax')}</th>
                                            <th style={{ width: 180 }}>{tSales('columns.reason')}</th>
                                            <th style={{ width: 100, textAlign: 'right' }}>{tSales('columns.fee')}</th>
                                            <th style={{ width: 100, textAlign: 'right' }}>{tSales('columns.amount')}</th>
                                            {isRetEditable && <th style={{ width: 50 }}></th>}
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {ret.lines.map((rl) => {
                                            const origLine = order.lines.find((l) => l.salesOrderLineId === rl.salesOrderLineId);
                                            const disc = parseFloat(origLine?.discountPercentage || '0');
                                            const taxCat = taxCategories.find(c => c.taxCategoryId === origLine?.taxCategoryId);
                                            const taxRate = parseFloat(taxCat?.rate || '0');
                                            const cc = order.currencyCode || baseCurrency;
                                            const pricing = computeLinePrice({
                                                quantity: parseFloat(rl.quantityReturned || '0'),
                                                pricePerUnit: parseFloat(origLine?.pricePerUnit || '0'),
                                                discountPercentage: disc,
                                                taxRate: taxRate,
                                            });
                                            return (
                                                <tr key={rl.returnLineId}>
                                                    <td>
                                                        <span style={{ fontWeight: 600, fontSize: 12 }}>
                                                            {origLine?.productNumber || origLine?.productId?.substring(0, 8) || 'ΓÇö'}
                                                        </span>
                                                    </td>
                                                    <td>
                                                        <span style={{ fontSize: 12, color: 'var(--text-secondary)' }}>
                                                            {origLine?.productDescription || 'ΓÇö'}
                                                        </span>
                                                    </td>
                                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                                        {isRetEditable ? (
                                                            <input
                                                                className="input"
                                                                type="number"
                                                                min="1"
                                                                step="1"
                                                                style={{ width: '100%', textAlign: 'right' }}
                                                                defaultValue={rl.quantityReturned}
                                                                key={`retqty-${rl.returnLineId}-${rl.quantityReturned}`}
                                                                onBlur={async (e) => {
                                                                    if (e.target.value !== rl.quantityReturned) {
                                                                        try {
                                                                            await apiMutate(
                                                                                `/api/sales-orders/${orderId}/returns/${ret.returnId}/lines/${rl.returnLineId}`,
                                                                                'PATCH',
                                                                                { quantityReturned: e.target.value },
                                                                            );
                                                                            await loadReturns();
                                                                        } catch (err) {
                                                                            setError(err instanceof Error ? err.message : tCommon('errors.failedToUpdateReturnLine'));
                                                                        }
                                                                    }
                                                                }}
                                                            />
                                                        ) : (
                                                            rl.quantityReturned
                                                        )}
                                                    </td>
                                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                                        {formatAmount(parseFloat(origLine?.pricePerUnit || '0'), cc)}
                                                    </td>
                                                    <td style={{ textAlign: 'right', color: disc > 0 ? 'inherit' : 'var(--text-muted)' }}>
                                                        {disc.toFixed(1)}%
                                                    </td>
                                                    <td style={{ textAlign: 'right', color: taxRate > 0 ? 'inherit' : 'var(--text-muted)' }}>
                                                        {taxRate.toFixed(1)}%
                                                    </td>
                                                    <td>
                                                        {isRetEditable ? (
                                                            <input
                                                                className="input"
                                                                style={{ width: '100%' }}
                                                                defaultValue={rl.reason || ''}
                                                                key={`retrsn-${rl.returnLineId}-${rl.reason}`}
                                                                onBlur={async (e) => {
                                                                    if (e.target.value !== (rl.reason || '')) {
                                                                        try {
                                                                            await apiMutate(
                                                                                `/api/sales-orders/${orderId}/returns/${ret.returnId}/lines/${rl.returnLineId}`,
                                                                                'PATCH',
                                                                                { reason: e.target.value },
                                                                            );
                                                                            await loadReturns();
                                                                        } catch (err) {
                                                                            setError(err instanceof Error ? err.message : tCommon('errors.failedToUpdateReturnLine'));
                                                                        }
                                                                    }
                                                                }}
                                                                placeholder={tSales('placeholders.reason')}
                                                            />
                                                        ) : (
                                                            <span style={{ fontSize: 12 }}>{rl.reason || 'ΓÇö'}</span>
                                                        )}
                                                    </td>
                                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                                        {isRetEditable ? (
                                                            <input
                                                                className="input"
                                                                type="number"
                                                                min="0"
                                                                step="0.01"
                                                                style={{ width: '100%', textAlign: 'right' }}
                                                                defaultValue={parseFloat(rl.returnFee || '0').toFixed(2)}
                                                                key={`retfee-${rl.returnLineId}-${rl.returnFee}`}
                                                                onBlur={async (e) => {
                                                                    const val = parseFloat(e.target.value);
                                                                    const formatted = isNaN(val) ? '0.00' : val.toFixed(2);
                                                                    if (formatted !== parseFloat(rl.returnFee || '0').toFixed(2)) {
                                                                        try {
                                                                            await apiMutate(
                                                                                `/api/sales-orders/${orderId}/returns/${ret.returnId}/lines/${rl.returnLineId}`,
                                                                                'PATCH',
                                                                                { returnFee: formatted },
                                                                            );
                                                                            await loadReturns();
                                                                        } catch (err) {
                                                                            setError(err instanceof Error ? err.message : tCommon('errors.failedToUpdateReturnLine'));
                                                                        }
                                                                    }
                                                                }}
                                                            />
                                                        ) : (
                                                            formatAmount(parseFloat(rl.returnFee || '0'), order.currencyCode || baseCurrency)
                                                        )}
                                                    </td>
                                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                                        {formatAmount(pricing.amount, order.currencyCode || baseCurrency)}
                                                    </td>
                                                    {isRetEditable && (
                                                        <td>
                                                            <button
                                                                className="btn btn-danger btn-sm"
                                                                onClick={async () => {
                                                                    if (!confirm(tConfirm('removeReturnLine'))) return;
                                                                    try {
                                                                        await apiMutate(
                                                                            `/api/sales-orders/${orderId}/returns/${ret.returnId}/lines/${rl.returnLineId}`,
                                                                            'DELETE',
                                                                        );
                                                                        await loadReturns();
                                                                    } catch (err) {
                                                                        setError(err instanceof Error ? err.message : t('common.errors.failedToRemoveReturnLine'));
                                                                    }
                                                                }}
                                                                title={t('salesOrders.buttons.removeReturnLine')}
                                                            >
                                                                <span dangerouslySetInnerHTML={{ __html: '&#10005;' }} />
                                                            </button>
                                                        </td>
                                                    )}
                                                </tr>
                                            );
                                        })}
                                        {ret.lines.length === 0 && (
                                            <tr>
                                                <td
                                                    colSpan={isRetEditable ? 9 : 8}
                                                    style={{ textAlign: 'center', color: 'var(--text-muted)', padding: '12px 0' }}
                                                >
                                                    {t('salesOrders.noReturnLines')}
                                                </td>
                                            </tr>
                                        )}
                                        {ret.lines.length > 0 && (() => {
                                            const summary = computeReturnCreditSummary(
                                                ret.lines.map((rl) => {
                                                    const origLine = order.lines.find((l) => l.salesOrderLineId === rl.salesOrderLineId);
                                                    const taxCat = taxCategories.find(c => c.taxCategoryId === origLine?.taxCategoryId);
                                                    return {
                                                        quantity: parseFloat(rl.quantityReturned || '0'),
                                                        pricePerUnit: parseFloat(origLine?.pricePerUnit || '0'),
                                                        discountPercentage: parseFloat(origLine?.discountPercentage || '0'),
                                                        taxRate: parseFloat(taxCat?.rate || '0'),
                                                        returnFee: parseFloat(rl.returnFee || '0'),
                                                    };
                                                }),
                                            );
                                            const { subtotal, totalTax, totalFees, netCredit } = summary;
                                            const cc = order.currencyCode || baseCurrency;
                                            return (
                                                <>
                                                    <tr style={{ borderTop: '2px solid var(--border)' }}>
                                                        <td colSpan={7} style={{ textAlign: 'right', fontWeight: 600, fontSize: 12, color: 'var(--text-muted)' }}>
                                                            {t('salesOrders.returns.totalCredit')}
                                                        </td>
                                                        <td></td>
                                                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontWeight: 600 }}>
                                                            {formatAmount(subtotal, cc)}
                                                        </td>
                                                        {isRetEditable && <td></td>}
                                                    </tr>
                                                    <tr>
                                                        <td colSpan={7} style={{ textAlign: 'right', fontWeight: 600, fontSize: 12, color: 'var(--text-muted)' }}>
                                                            {tSales('columns.tax')}
                                                        </td>
                                                        <td></td>
                                                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontWeight: 600 }}>
                                                            {formatAmount(totalTax, cc)}
                                                        </td>
                                                        {isRetEditable && <td></td>}
                                                    </tr>
                                                    <tr>
                                                        <td colSpan={7} style={{ textAlign: 'right', fontWeight: 600, fontSize: 12, color: 'var(--text-muted)' }}>
                                                            {t('salesOrders.returns.totalFees')}
                                                        </td>
                                                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontWeight: 600 }}>
                                                            {totalFees > 0 ? `ΓêÆ${formatAmount(totalFees, cc)}` : formatAmount(0, cc)}
                                                        </td>
                                                        <td></td>
                                                        {isRetEditable && <td></td>}
                                                    </tr>
                                                    <tr>
                                                        <td colSpan={7} style={{ textAlign: 'right', fontWeight: 700, fontSize: 13 }}>
                                                            {t('salesOrders.returns.netCredit')}
                                                        </td>
                                                        <td></td>
                                                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontWeight: 700, fontSize: 13 }}>
                                                            {formatAmount(netCredit, cc)}
                                                        </td>
                                                        {isRetEditable && <td></td>}
                                                    </tr>
                                                </>
                                            );
                                        })()}
                                    </tbody>
                                </table>
                            </div>
                        );
                    })}
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect, use, useMemo } from 'react';
import { useRouter } from 'next/navigation';
import { toast } from 'react-hot-toast';
import { useTranslations } from 'next-intl';
import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import {
  apiFetch,
  apiMutate,
  reportError,
} from '@/lib/api';
import ActivityTimeline from '@/components/shared/ActivityTimeline';
import StateBadge, { StateName } from '@/components/StateBadge';
import { ValidState } from '@/types/states';
import EntityHeader from '@/components/shared/EntityHeader';
import DetailsLayout from '@/components/shared/DetailsLayout';
import { CURRENCIES } from '@/lib/currency';
import PageNav from '@/components/shared/PageNav';
import DataGrid from '@/components/DataGrid';
import GroupSelect from '@/components/shared/GroupSelect';
import { resolveSupplierRiskProfile } from '@/lib/supplier-risk';
import SupplierStatusBadges from '@/components/suppliers/SupplierStatusBadges';
import SupplierExpiries from '@/components/suppliers/SupplierExpiries';
import { useSettings } from '@/components/SettingsProvider';
import { SUPPLIER_STATE } from '@modbm/shared';

interface Supplier {
  vendorId: string;
  vendorNumber: string;
  name: string;
  emailAddress1: string | null;
  telephone1: string | null;
  address1Line1: string | null;
  address1Line2: string | null;
  address1City: string | null;
  address1StateOrProvince: string | null;
  address1PostalCode: string | null;
  address1Country: string | null;
  // Overrides
  tradingTermsId?: string | null;
  earlyPaymentDiscount?: string | null;
  creditLimit?: string | null;
  isPurchasingBlocked?: boolean;
  purchasingBlockReason?: string | null;
  isPaymentBlocked?: boolean;
  paymentBlockReason?: string | null;
  
  // Group properties (resolved in backend from join)
  supplierGroupName?: string | null;
  supplierGroupCode?: string | null;
  groupIsPurchasingBlocked?: boolean;
  groupPurchasingBlockReason?: string | null;
  groupIsPaymentBlocked?: boolean;
  groupPaymentBlockReason?: string | null;

  currencyCode: string;
  supplierGroupId: string | null;
  stateCode: string;
  notes: string | null;
  blockNotes?: string | null;

  bankAccountName?: string | null;
  bankBsb?: string | null;
  bankAccountNumber?: string | null;

  createdBy?: string | null;
  createdOn?: string | null;
  modifiedOn?: string | null;
  events?: any[];
}

export default function SupplierDetailPage({ params: paramsPromise }: { params: Promise<{ id: string }> }) {
  const { baseCurrency } = useSettings();
  const t = useTranslations('suppliers');
  const tCommon = useTranslations('common');
  const tSales = useTranslations('salesOrders');
  const tToast = useTranslations('toast');
  const tConfirm = useTranslations('confirm');
  const tSidebar = useTranslations('sidebar');
  const params = use(paramsPromise);
  const router = useRouter();
  const [activeTab, setActiveTab] = useState<'details' | 'products' | 'compliance'>('details');
  const [supplier, setSupplier] = useState<Supplier | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  useDocumentTitle(supplier ? (supplier.name ? `${supplier.vendorNumber} - ${supplier.name}` : supplier.vendorNumber) : null);

  // Editable field state
  const [editName, setEditName] = useState('');
  const [editEmail, setEditEmail] = useState('');
  const [editPhone, setEditPhone] = useState('');
  const [editStreet, setEditStreet] = useState('');
  const [editCity, setEditCity] = useState('');
  const [editCountry, setEditCountry] = useState('');
  const [editTradingTermsId, setEditTradingTermsId] = useState<string | null>(null);
  const [editEarlyPaymentDiscount, setEditEarlyPaymentDiscount] = useState<string | null>(null);
  const [editNotes, setEditNotes] = useState('');
  const [editCurrency, setEditCurrency] = useState(baseCurrency);
  const [editSupplierGroupId, setEditSupplierGroupId] = useState<string | null>(null);
  
  const [editIsPurchasingBlocked, setEditIsPurchasingBlocked] = useState(false);
  const [editPurchasingBlockReason, setEditPurchasingBlockReason] = useState('');
  const [editIsPaymentBlocked, setEditIsPaymentBlocked] = useState(false);
  const [editPaymentBlockReason, setEditPaymentBlockReason] = useState('');
  const [editBlockNotes, setEditBlockNotes] = useState('');

  const [editBankAccountName, setEditBankAccountName] = useState('');
  const [editBankBsb, setEditBankBsb] = useState('');
  const [editBankAccountNumber, setEditBankAccountNumber] = useState('');

  const [availableTradingTerms, setAvailableTradingTerms] = useState<any[]>([]);

  const loadSupplier = async (showSpinner = true) => {
    if (showSpinner) setLoading(true);
    try {
      const [data, termsData] = await Promise.all([
        apiFetch<Supplier>(`/api/suppliers/${params.id}`),
        apiFetch<any[]>('/api/settings/trading-terms').catch(() => []),
      ]);
      setSupplier(data);
      setAvailableTradingTerms(termsData);
      
      setEditName(data.name || '');
      setEditEmail(data.emailAddress1 || '');
      setEditPhone(data.telephone1 || '');
      setEditStreet(data.address1Line1 || '');
      setEditCity(data.address1City || '');
      setEditCountry(data.address1Country || '');
      setEditTradingTermsId(data.tradingTermsId || null);
      setEditEarlyPaymentDiscount(data.earlyPaymentDiscount || '');
      setEditNotes(data.notes || '');
      
      setEditIsPurchasingBlocked(data.isPurchasingBlocked || false);
      setEditPurchasingBlockReason(data.purchasingBlockReason || '');
      setEditIsPaymentBlocked(data.isPaymentBlocked || false);
      setEditPaymentBlockReason(data.paymentBlockReason || '');
      setEditBlockNotes(data.blockNotes || '');
      
      setEditBankAccountName(data.bankAccountName || '');
      setEditBankBsb(data.bankBsb || '');
      setEditBankAccountNumber(data.bankAccountNumber || '');
      
      setEditCurrency(data.currencyCode || baseCurrency);
      setEditSupplierGroupId(data.supplierGroupId || null);
    } catch (err) {
      setError(err instanceof Error ? err.message : tCommon('errors.failedToLoadOrder'));
    } finally {
      if (showSpinner) setLoading(false);
    }
  };

  useEffect(() => {
    loadSupplier();
  }, [params.id]);

  /** Save a single field on blur if it changed */
  const saveField = async (field: string, value: any, original: any) => {
    if (value === original) return;
    if (value === '' && original === null) return;
    setSaving(true);
    setError('');
    try {
      const payloadValue = value === '' ? null : value;
      await apiMutate(`/api/suppliers/${params.id}`, 'PATCH', { [field]: payloadValue });
      await loadSupplier(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : tCommon('errors.failedToUpdateOrder'));
    } finally {
      setSaving(false);
    }
  };

  /** Toggle state code (active/inactive) */
  const toggleState = async () => {
    if (!supplier || saving) return;
    const newState = supplier.stateCode === SUPPLIER_STATE.ACTIVE ? SUPPLIER_STATE.INACTIVE : SUPPLIER_STATE.ACTIVE;
    setSaving(true);
    setError('');
    try {
      await apiMutate(`/api/suppliers/${params.id}`, 'PATCH', { stateCode: newState });
      await loadSupplier(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : tCommon('errors.failedToChangeState'));
    } finally {
      setSaving(false);
    }
  };

  const archiveSupplier = async () => {
    if (!confirm(tConfirm('archiveOrder'))) return;
    setSaving(true);
    try {
      await apiMutate(`/api/suppliers/${params.id}/archive`, 'POST');
      toast.success(tToast('orderArchived'), { icon: '≡ƒôª' });
      await loadSupplier(false);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setSaving(false);
    }
  };

  const unarchiveSupplier = async () => {
    setSaving(true);
    try {
      await apiMutate(`/api/suppliers/${params.id}/unarchive`, 'POST');
      toast.success(tToast('orderUnarchived'), { icon: '≡ƒôª' });
      await loadSupplier(false);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setSaving(false);
    }
  };

  const productColumns: any[] = useMemo(() => [
    { field: 'productNumber', headerName: t('products.columns.productNo'), width: 140 },
    { field: 'productName', headerName: t('products.columns.name'), flex: 1, minWidth: 160 },
    { field: 'supplierPartNumber', headerName: t('products.columns.partNo'), width: 150 },
    { field: 'costPrice', headerName: t('products.columns.costPrice'), type: 'numericColumn', width: 120, valueFormatter: (p: any) => p.value ? `$${parseFloat(p.value).toFixed(2)}` : 'ΓÇö' },
    { field: 'discountPercent', headerName: t('products.columns.discount'), type: 'numericColumn', width: 120, valueFormatter: (p: any) => p.value ? `${parseFloat(p.value)}%` : 'ΓÇö' },
    { field: 'productStateCode', headerName: t('products.columns.status'), width: 110, cellRenderer: (p: { value: string }) => p.value ? <StateBadge state={p.value as ValidState} /> : null },
  ], [t]);

  if (loading) {
    return (
      <>
        <div className="flex items-center justify-center flex-1">
          <p style={{ color: 'var(--text-muted)' }}>{tCommon('loading')}</p>
        </div>
      </>
    );
  }

  if (!supplier) {
    return (
      <>
        <div className="flex flex-col items-center justify-center flex-1">
          <p className="text-lg mb-2" style={{ color: 'var(--danger)' }}>
            {error || tCommon('noMatchingResults')}
          </p>
          <button className="btn btn-secondary" onClick={() => router.push('/suppliers')}>
            ΓåÉ {tSidebar('items.suppliers')}
          </button>
        </div>
      </>
    );
  }

  const isEditable = supplier.stateCode !== SUPPLIER_STATE.ARCHIVED;



  const visibleSections = [
    {
      id: 'tab-details',
      label: t('tabs.overview'),
      isSubPage: true,
      isActive: activeTab === 'details',
      onClick: () => setActiveTab('details'),
      subtargets: [
        { id: 'info-section', label: t('tabs.info'), onClick: () => { setActiveTab('details'); setTimeout(() => document.getElementById('info-section')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50); } },
        { id: 'financials-section', label: t('tabs.financials'), onClick: () => { setActiveTab('details'); setTimeout(() => document.getElementById('financials-section')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50); } },
        { id: 'notes-section', label: t('tabs.notes'), onClick: () => { setActiveTab('details'); setTimeout(() => document.getElementById('notes-section')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50); } },
        { id: 'contact-section', label: t('tabs.contact'), onClick: () => { setActiveTab('details'); setTimeout(() => document.getElementById('contact-section')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50); } },
        { id: 'bank-section', label: 'Bank', onClick: () => { setActiveTab('details'); setTimeout(() => document.getElementById('bank-section')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50); } },
        { id: 'activity-section', label: t('tabs.activity'), onClick: () => { setActiveTab('details'); setTimeout(() => document.getElementById('activity-section')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50); } },
      ]
    },
    {
      id: 'tab-products',
      label: t('tabs.products'),
      isSubPage: true,
      isActive: activeTab === 'products',
      onClick: () => setActiveTab('products')
    },
    {
      id: 'tab-compliance',
      label: t('tabs.compliance'),
      isSubPage: true,
      isActive: activeTab === 'compliance',
      onClick: () => setActiveTab('compliance')
    }
  ];

  return (
    <>
      <DetailsLayout
        header={
          <EntityHeader
            title={supplier.name}
            subtitle={supplier.vendorNumber}
            onBack={() => {
              if (document.referrer.includes(window.location.host)) {
                router.back();
              } else {
                router.push('/suppliers');
              }
            }}
            isSaving={saving}
            badges={<SupplierStatusBadges mode="header" profile={resolveSupplierRiskProfile(supplier as any)} stateCode={supplier.stateCode} />}
            actions={
              <>
                <PageNav sections={visibleSections} />
              </>
            }
          />
        }
      >
      {supplier.stateCode === SUPPLIER_STATE.ARCHIVED && (
        <div
          className="px-4 mb-4 py-3 rounded-lg flex items-center gap-3 shadow-sm"
          style={{ background: 'rgba(245, 158, 11, 0.1)', border: '1px solid rgba(245, 158, 11, 0.3)', color: '#b45309' }}
        >
          <span style={{ fontSize: '1.2rem' }}>≡ƒôª</span>
          <div>
            <strong className="font-semibold text-amber-800">{tSales('archivedBannerTitle')}</strong> {tSales('archivedBannerBody')}
          </div>
        </div>
      )}

      {activeTab === 'products' && (
        <div className="flex-1 min-h-0 flex flex-col w-full h-full pb-6">
          <div className="flex-1 min-h-0 flex flex-col z-10 bg-white rounded-xl shadow-sm border border-[rgba(196,198,205,0.4)] overflow-hidden transition-all">
            <DataGrid 
                endpoint={`/api/suppliers/${encodeURIComponent(params.id)}/products`}
                columns={productColumns}
                gridKey="supplier-products"
                fetchAll
                onRowClicked={(row: any) => router.push(`/products/${row.productId}`)}
                renderHeader={({ searchInput, optionsButton, rowCount, loading }) => (
                  <div className="flex items-center justify-between px-6 py-4">
                    <div className="flex items-center gap-4 flex-1">
                      <h2 className="text-[1.3rem] font-bold tracking-tight text-[#041627] shrink-0" style={{ fontFamily: 'Manrope, sans-serif' }}>
                        {t('products.title')}
                      </h2>
                      <div className="h-5 w-px bg-[rgba(196,198,205,0.4)] shrink-0 mx-2"></div>
                      <div className="flex items-center gap-2 px-3 py-1.5 bg-[#f2f4f6] rounded-lg shrink-0">
                        <span className="text-[11px] font-bold text-[#041627] tracking-wider uppercase" style={{ fontFamily: 'Manrope, sans-serif' }}>
                          {tCommon('grid.rowCountLabel')}
                        </span>
                        <span className="text-[11px] font-bold text-[#006b5c]">
                          {loading ? '...' : rowCount.toLocaleString()}
                        </span>
                      </div>
                      <div className="flex-1 ml-4 max-w-md">
                        {searchInput}
                      </div>
                    </div>
                    <div className="flex items-center gap-3 shrink-0 ml-4">
                      {optionsButton}
                    </div>
                  </div>
                )}
            />
          </div>
        </div>
      )}

      {activeTab === 'details' && (
        <div className="flex flex-col gap-3">

      {error && (
        <div
          className="px-4 py-3 rounded-lg text-sm"
          style={{
            background: 'rgba(239, 68, 68, 0.1)',
            border: '1px solid rgba(239, 68, 68, 0.3)',
            color: '#f87171',
          }}
        >
          {error}
          <button className="ml-3 text-xs underline" onClick={() => setError('')}>{tCommon('dismiss')}</button>
        </div>
      )}

        {/* Top row: General Info (left) + Financials (right) */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          {/* General Info Card */}
          <div id="info-section" className="card">
            <h3 className="section-heading">
              {/* eslint-disable-next-line i18next/no-literal-string */}
              <span className="material-symbols-outlined">info</span>
              {t('generalInfo')}
            </h3>
            <div className="grid grid-cols-1 gap-4">
              <div>
                <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                  {tCommon('columns.name')}
                </label>
                <input
                  type="text"
                  className="input"
                  value={editName}
                  onChange={(e) => setEditName(e.target.value)}
                  onBlur={() => saveField('name', editName, supplier.name)}
                  disabled={!isEditable || saving}
                />
              </div>
              <div>
                <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                  {t('columns.vendorNumber')}
                </label>
                <input
                  type="text"
                  className="input"
                  value={supplier.vendorNumber}
                  disabled
                />
              </div>
              <div>
                <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                  {t('supplierGroup')}
                </label>
                <GroupSelect
                  type="supplier"
                  value={editSupplierGroupId}
                  onChange={(val) => {
                    setEditSupplierGroupId(val);
                    saveField('supplierGroupId', val || '', supplier.supplierGroupId);
                  }}
                  disabled={!isEditable || saving}
                  placeholder={t('placeholders.noGroup')}
                />
              </div>
            </div>
          </div>

          {/* Financials Card */}
          <div id="financials-section" className="card">
            <h3 className="section-heading">
              {/* eslint-disable-next-line i18next/no-literal-string */}
              <span className="material-symbols-outlined">payments</span>
              {t('financials')}
            </h3>
            <div className="grid grid-cols-1 gap-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tCommon('columns.currency')}
                  </label>
                  <select
                    className="input"
                    value={editCurrency}
                    onChange={(e) => {
                      setEditCurrency(e.target.value);
                      saveField('currencyCode', e.target.value, supplier.currencyCode);
                    }}
                    disabled={!isEditable || saving}
                  >
                    {CURRENCIES.map(c => (
                      <option key={c.code} value={c.code}>{c.code}</option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {t('paymentTerms')}
                  </label>
                  <select
                    className="input"
                    value={editTradingTermsId || ''}
                    onChange={(e) => {
                      setEditTradingTermsId(e.target.value);
                      saveField('tradingTermsId', e.target.value, supplier.tradingTermsId || null);
                    }}
                    disabled={!isEditable || saving}
                  >
                    <option value="">{tCommon('selectEllipsis')}</option>
                    {availableTradingTerms.map(t => (
                      <option key={t.tradingTermsId} value={t.tradingTermsId}>{t.code} - {t.description}</option>
                    ))}
                  </select>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tCommon('columns.status')}
                  </label>
                  <div
                    className="flex items-center gap-3"
                    style={{ paddingTop: 6, cursor: !isEditable || saving ? 'not-allowed' : 'pointer' }}
                    onClick={toggleState}
                  >
                    <div
                      style={{
                        width: 40,
                        height: 22,
                        borderRadius: 11,
                        background: supplier.stateCode === SUPPLIER_STATE.ACTIVE ? 'var(--accent)' : 'var(--border)',
                        position: 'relative',
                        transition: 'background 0.2s ease',
                        opacity: !isEditable || saving ? 0.5 : 1,
                      }}
                    >
                      <div
                        style={{
                          width: 16,
                          height: 16,
                          borderRadius: '50%',
                          background: '#fff',
                          position: 'absolute',
                          top: 3,
                          left: supplier.stateCode === SUPPLIER_STATE.ACTIVE ? 21 : 3,
                          transition: 'left 0.2s ease',
                        }}
                      />
                    </div>
                    <span className="text-sm" style={{ color: 'var(--text-secondary)' }}>
                      <StateName state={supplier.stateCode as ValidState} />
                    </span>
                  </div>
                </div>
                <div>
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {t('earlyPaymentDiscount')}
                  </label>
                  <div className="relative">
                    <input
                      type="number"
                      className="input w-full pr-8"
                      value={editEarlyPaymentDiscount || ''}
                      onChange={(e) => setEditEarlyPaymentDiscount(e.target.value)}
                      onBlur={() => saveField('earlyPaymentDiscount', editEarlyPaymentDiscount || '', supplier.earlyPaymentDiscount || null)}
                      disabled={!isEditable || saving}
                      step="0.01"
                      min="0"
                      max="100"
                    />
                    <span className="absolute right-3 top-1/2 -translate-y-1/2 font-bold text-slate-400 pointer-events-none">%</span>
                  </div>
                </div>
              </div>

            </div>
          </div>
        </div>

        {/* Notes Card ΓÇö full width */}
        <div id="notes-section" className="card">
          <h3 className="section-heading">
            {/* eslint-disable-next-line i18next/no-literal-string */}
            <span className="material-symbols-outlined">notes</span>
            {tCommon('notesCardHeading')}
          </h3>
          <textarea
            className="input w-full"
            style={{ minHeight: 110, paddingTop: 12, resize: 'vertical' }}
            value={editNotes}
            onChange={(e) => setEditNotes(e.target.value)}
            onBlur={() => saveField('notes', editNotes, supplier.notes)}
            placeholder={tCommon('notesCardPlaceholder')}
            disabled={!isEditable || saving}
          />
        </div>

        {/* Contact & Location Card ΓÇö full width */}
        <div id="contact-section" className="card">
          <h3 className="section-heading">
            {/* eslint-disable-next-line i18next/no-literal-string */}
            <span className="material-symbols-outlined">location_on</span>
            {t('contactLocation')}
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                {t('email')}
              </label>
              <input
                type="email"
                className="input"
                value={editEmail}
                onChange={(e) => setEditEmail(e.target.value)}
                onBlur={() => saveField('emailAddress1', editEmail, supplier.emailAddress1)}
                disabled={!isEditable || saving}
              />
            </div>
            <div>
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                {t('phone')}
              </label>
              <input
                type="text"
                className="input"
                value={editPhone}
                onChange={(e) => setEditPhone(e.target.value)}
                onBlur={() => saveField('telephone1', editPhone, supplier.telephone1)}
                disabled={!isEditable || saving}
              />
            </div>
            <div className="md:col-span-2">
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                {tCommon('columns.address')}
              </label>
              <input
                type="text"
                className="input"
                value={editStreet}
                onChange={(e) => setEditStreet(e.target.value)}
                onBlur={() => saveField('address1Line1', editStreet, supplier.address1Line1)}
                disabled={!isEditable || saving}
              />
            </div>
            <div>
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                {t('city')}
              </label>
              <input
                type="text"
                className="input"
                value={editCity}
                onChange={(e) => setEditCity(e.target.value)}
                onBlur={() => saveField('address1City', editCity, supplier.address1City)}
                disabled={!isEditable || saving}
              />
            </div>
            <div>
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                {t('country')}
              </label>
              <input
                type="text"
                className="input"
                value={editCountry}
                onChange={(e) => setEditCountry(e.target.value)}
                onBlur={() => saveField('address1Country', editCountry, supplier.address1Country)}
                disabled={!isEditable || saving}
              />
            </div>
          </div>
        </div>

        {/* Bank Details Card */}
        <div id="bank-section" className="card">
          <h3 className="section-heading">
            {/* eslint-disable-next-line i18next/no-literal-string */}
            <span className="material-symbols-outlined">account_balance</span>
            Bank Details
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="md:col-span-2">
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                Bank Account Name
              </label>
              <input
                type="text"
                className="input w-full"
                value={editBankAccountName}
                onChange={(e) => setEditBankAccountName(e.target.value)}
                onBlur={() => saveField('bankAccountName', editBankAccountName, supplier.bankAccountName)}
                disabled={!isEditable || saving}
                placeholder="e.g. John Doe Pty Ltd"
              />
            </div>
            <div>
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                BSB
              </label>
              <input
                type="text"
                className="input"
                value={editBankBsb}
                onChange={(e) => setEditBankBsb(e.target.value)}
                onBlur={() => saveField('bankBsb', editBankBsb, supplier.bankBsb)}
                disabled={!isEditable || saving}
                placeholder="e.g. 062-000"
              />
            </div>
            <div>
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                Account Number
              </label>
              <input
                type="text"
                className="input"
                value={editBankAccountNumber}
                onChange={(e) => setEditBankAccountNumber(e.target.value)}
                onBlur={() => saveField('bankAccountNumber', editBankAccountNumber, supplier.bankAccountNumber)}
                disabled={!isEditable || saving}
                placeholder="e.g. 12345678"
              />
            </div>
          </div>
        </div>


        {/* Activity Timeline ΓÇö full width */}
        {/* Activity Timeline ΓÇö full width */}
        <div id="activity-section" className="card">
          <ActivityTimeline events={supplier.events || []} />
        </div>

        <div className="flex justify-end pt-2">
          {supplier.stateCode === SUPPLIER_STATE.ARCHIVED ? (
            <button className="btn btn-secondary" onClick={unarchiveSupplier} disabled={saving}>
              ≡ƒôª {tSales('buttons.unarchive')}
            </button>
          ) : (
            <button
              className="btn btn-secondary"
              style={{ color: '#ef4444', borderColor: '#ef4444' }}
              onClick={archiveSupplier}
              disabled={saving}
            >
              ≡ƒôª {tSales('buttons.archive')}
            </button>
          )}
        </div>
      </div>
      )}

      {activeTab === 'compliance' && (
        <div className="flex flex-col gap-3">
          <div className="card">
            <h3 className="section-heading">
              {/* eslint-disable-next-line i18next/no-literal-string */}
              <span className="material-symbols-outlined">gavel</span>
              {t('compliance.title')}
            </h3>
            <div className="flex gap-2 pt-2 pb-4">
              <SupplierStatusBadges 
                profile={resolveSupplierRiskProfile(supplier as any)} 
                stateCode={supplier.stateCode}
                mode="header"
              />
            </div>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="flex flex-col gap-4">
                <div className="flex flex-col gap-1.5 items-start">
                  <label className="block text-xs font-medium m-0" style={{ color: 'var(--text-muted)' }}>{t('compliance.purchasingBlock')}</label>
                  <label className="switch" title={editIsPurchasingBlocked ? t('tooltips.currentlyBlocked') : t('tooltips.currentlyActive')}>
                    <input 
                      type="checkbox" 
                      checked={!editIsPurchasingBlocked} 
                      disabled={!isEditable || saving}
                      onChange={e => {
                        const newBlocked = !e.target.checked;
                        setEditIsPurchasingBlocked(newBlocked);
                        saveField('isPurchasingBlocked', newBlocked, supplier.isPurchasingBlocked || false);
                      }} 
                    />
                    <span className="switch-slider"></span>
                  </label>
                </div>
                {editIsPurchasingBlocked && (
                  <div>
                    <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>{t('compliance.reason')}</label>
                    <select
                      className="input w-full"
                      value={editPurchasingBlockReason}
                      onChange={e => setEditPurchasingBlockReason(e.target.value)}
                      onBlur={() => saveField('purchasingBlockReason', editPurchasingBlockReason, supplier.purchasingBlockReason || '')}
                      disabled={!isEditable || saving}
                    >
                      <option value="">{tCommon('selectEllipsis')}</option>
                      <option value="compliance_breach">{t('compliance.reasons.compliance_breach')}</option>
                      <option value="quality_issues">{t('compliance.reasons.quality_issues')}</option>
                      <option value="dispute">{t('compliance.reasons.dispute')}</option>
                      <option value="financial_risk">{t('compliance.reasons.financial_risk')}</option>
                      <option value="other">{t('compliance.reasons.other')}</option>
                    </select>
                  </div>
                )}
                {supplier.groupIsPurchasingBlocked && (
                  <div className="text-xs font-semibold text-danger">
                    {t('compliance.groupInherited', { reason: (supplier.groupPurchasingBlockReason || 'Unspecified').replace('_', ' ') })}
                  </div>
                )}
              </div>
              
              <div className="flex flex-col gap-4">
                <div className="flex flex-col gap-1.5 items-start">
                  <label className="block text-xs font-medium m-0" style={{ color: 'var(--text-muted)' }}>{t('compliance.paymentBlock')}</label>
                  <label className="switch" title={editIsPaymentBlocked ? t('tooltips.currentlyBlocked') : t('tooltips.currentlyActive')}>
                    <input 
                      type="checkbox" 
                      checked={!editIsPaymentBlocked} 
                      disabled={!isEditable || saving}
                      onChange={e => {
                        const newBlocked = !e.target.checked;
                        setEditIsPaymentBlocked(newBlocked);
                        saveField('isPaymentBlocked', newBlocked, supplier.isPaymentBlocked || false);
                      }} 
                    />
                    <span className="switch-slider"></span>
                  </label>
                </div>
                {editIsPaymentBlocked && (
                  <div>
                    <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>{t('compliance.reason')}</label>
                    <select
                      className="input w-full"
                      value={editPaymentBlockReason}
                      onChange={e => setEditPaymentBlockReason(e.target.value)}
                      onBlur={() => saveField('paymentBlockReason', editPaymentBlockReason, supplier.paymentBlockReason || '')}
                      disabled={!isEditable || saving}
                    >
                      <option value="">{tCommon('selectEllipsis')}</option>
                      <option value="invoice_dispute">{t('compliance.reasons.invoice_dispute')}</option>
                      <option value="missing_goods">{t('compliance.reasons.missing_goods')}</option>
                      <option value="contractual_breach">{t('compliance.reasons.contractual_breach')}</option>
                      <option value="other">{t('compliance.reasons.other')}</option>
                    </select>
                  </div>
                )}
                {supplier.groupIsPaymentBlocked && (
                  <div className="text-xs font-semibold text-amber-600">
                    {t('compliance.groupInherited', { reason: (supplier.groupPaymentBlockReason || 'Unspecified').replace('_', ' ') })}
                  </div>
                )}
              </div>
            </div>

            <div className="mt-4">
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                {t('compliance.blockNotes')}
              </label>
              <input
                type="text"
                className="input w-full"
                placeholder={t('compliance.notesPlaceholder')}
                value={editBlockNotes}
                onChange={e => setEditBlockNotes(e.target.value)}
                onBlur={() => saveField('blockNotes', editBlockNotes, supplier.blockNotes || null)}
                disabled={!isEditable || saving}
              />
            </div>
          </div>
          
          <SupplierExpiries vendorId={supplier.vendorId} isEditable={isEditable} />
        </div>
      )}
      </DetailsLayout>
    </>
  );
}

'use client';

import { useDocumentTitle } from '@/hooks/useDocumentTitle';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { toast } from 'react-hot-toast';
import { apiMutate } from '@/lib/api';
import EntityHeader from '@/components/shared/EntityHeader';
