'use client';

import { useState, useEffect } from 'react';
import { usePathname } from 'next/navigation';
import Sidebar from '@/components/Sidebar';
import AuthGate from '@/components/AuthGate';

export default function Shell({ children }: { children: React.ReactNode }) {
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const pathname = usePathname();

  // Close sidebar on navigation (path changes)
  useEffect(() => {
    setIsSidebarOpen(false);
  }, [pathname]);

  return (
    <AuthGate>
      <div className="flex h-[100dvh] overflow-hidden relative">
        {/* Mobile Sidebar Overlay */}
        {isSidebarOpen && (
          <div 
            className="fixed inset-0 bg-black/50 z-[9998] lg:hidden"
            onClick={() => setIsSidebarOpen(false)}
          />
        )}

        {/* Sidebar Container */}
        <div 
          className={`fixed inset-y-0 left-0 z-[9999] transform transition-transform duration-300 ease-in-out lg:translate-x-0 lg:static lg:block print:hidden ${
            isSidebarOpen ? 'translate-x-0' : '-translate-x-full'
          }`}
        >
          <Sidebar />
        </div>

        <main className="flex-1 flex flex-col overflow-y-auto w-full lg:w-auto">
          {children}
        </main>

        {/* Floating Toggle Button for Mobile/Tablet */}
        <button 
          className="fixed bottom-6 left-6 z-[9999] lg:hidden w-14 h-14 rounded-full flex items-center justify-center print:hidden shadow-[0_4px_12px_rgba(0,0,0,0.3)] transition-transform hover:scale-105 cursor-pointer"
          style={{ background: 'var(--accent)', color: '#fff' }}
          onClick={() => setIsSidebarOpen(!isSidebarOpen)}
          aria-label="Toggle Navigation"
        >
          <span className="material-symbols-outlined text-[28px]">
            {isSidebarOpen ? 'close' : 'menu'}
          </span>
        </button>
      </div>
    </AuthGate>
  );
}

"use client";

import { useState, useEffect, useMemo, useRef, useCallback } from "react";
import { usePathname, useSearchParams } from 'next/navigation';
import { useTranslations } from 'next-intl';
import { AgGridReact } from "ag-grid-react";
import {
  AllCommunityModule,
  ModuleRegistry,
  type ColDef,
  type ColDefField,
  type GridReadyEvent,
  type FirstDataRenderedEvent,
  type RowClickedEvent,
  type SelectionChangedEvent,
  type StateUpdatedEvent,
  type GridState,
  type ScrollState,
} from "ag-grid-community";

ModuleRegistry.registerModules([AllCommunityModule]);

/* ΓöÇΓöÇ localStorage grid-state helpers (columns, sort, filter ΓÇö NOT scroll) ΓöÇ */

export const STORAGE_PREFIX = "datagrid-state-";

/** Save grid state (excluding scroll) to localStorage */
export function saveGridState(gridKey: string, state: GridState): void {
  try {
    // Strip scroll ΓÇö it lives in sessionStorage separately
    const { scroll: _scroll, ...rest } = state;
    localStorage.setItem(`${STORAGE_PREFIX}${gridKey}`, JSON.stringify(rest));
  } catch {
    /* quota exceeded ΓÇö silently ignore */
  }
}

/** Load saved grid state from localStorage */
export function loadGridState(gridKey: string): GridState | null {
  try {
    const raw = localStorage.getItem(`${STORAGE_PREFIX}${gridKey}`);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as GridState;
    return typeof parsed === 'object' && parsed !== null ? parsed : null;
  } catch {
    return null;
  }
}

/** Clear saved grid state */
export function clearGridState(gridKey: string): void {
  try {
    localStorage.removeItem(`${STORAGE_PREFIX}${gridKey}`);
  } catch {
    /* ignore */
  }
}

/* ΓöÇΓöÇ sessionStorage scroll-state helpers (session-only) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */

export const SCROLL_STORAGE_PREFIX = "datagrid-scroll-";

export function saveScrollState(gridKey: string, scroll: ScrollState): void {
  try {
    sessionStorage.setItem(`${SCROLL_STORAGE_PREFIX}${gridKey}`, JSON.stringify(scroll));
  } catch {
    /* ignore */
  }
}

export function loadScrollState(gridKey: string): ScrollState | null {
  try {
    const raw = sessionStorage.getItem(`${SCROLL_STORAGE_PREFIX}${gridKey}`);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as ScrollState;
    return typeof parsed.top === 'number' ? parsed : null;
  } catch {
    return null;
  }
}

/* ΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */

export interface DataGridProps<T> {
  /** API endpoint to fetch data from (appended with ?page=&limit=&search= params) */
  endpoint?: string;
  /** Local static row data array (mutually exclusive with endpoint) */
  rowData?: T[];
  /** AG Grid column definitions */
  columns: ColDef<T>[];
  /** Stable key for persisting column layout to localStorage (e.g. "ops-products") */
  gridKey?: string;
  /** Placeholder text for the search input */
  searchPlaceholder?: string;
  /** File name prefix for CSV export (default: "export") */
  exportFileName?: string;
  /** Authenticated fetch function ΓÇö must accept a URL and return parsed JSON with a `data` array */
  apiFetch: <R = unknown>(path: string) => Promise<R>;
  /** Error reporter ΓÇö called when data fetching fails */
  onError?: (err: unknown, component: string) => void;
  /** Optional callback when a row is clicked */
  onRowClicked?: (data: T) => void;
  /** When true, fetch the entire dataset in one request (no pagination). AG Grid handles sorting/filtering client-side. */
  fetchAll?: boolean;
  /** Whether to show a toggle to include archived records */
  /** Whether to show a toggle to include archived records */
  showArchivedToggle?: boolean;
  /** Built-in responsive header: The title of the page. If provided, DataGrid automatically wraps itself in the standard page layout. */
  pageTitle?: string | React.ReactNode;
  /** Built-in responsive header: Custom actions (e.g., Create Button) */
  headerActions?: React.ReactNode;
  /** Built-in responsive header: Custom filters (e.g., date dropdown) */
  headerFilters?: React.ReactNode;
  /** If provided, customizes the entire top bar rendering (mutually exclusive with pageTitle) */
  renderHeader?: (props: {
    searchInput: React.ReactNode;
    optionsButton: React.ReactNode;
    rowCount: number;
    loading: boolean;
  }) => React.ReactNode;
  /** Optional theme override for AG grid wrapper. Defaults to ag-theme-alpine-dark */
  gridTheme?: string;
  /** Optional initial search term to seed the quick filter */
  initialSearch?: string;
  /** Property on T to use as a unique row identifier, prevents scrolling jump on data load */
  rowIdField?: keyof T;
  /** Selection mode for rows */
  rowSelection?: "single" | "multiple";
  /** Callback when selection changes */
  onSelectionChanged?: (selectedRows: T[]) => void;
  /** Number to trigger a refresh without unmounting the grid */
  refreshTrigger?: number;
  /** Context object passed directly into AgGridReact context to be available to cell renderers */
  context?: any;
  /** Callback to determine if a row is selectable */
  isRowSelectable?: (node: import('ag-grid-community').IRowNode<T>) => boolean;
  /** Callback when data is successfully loaded */
  onDataLoaded?: (data: T[]) => void;
  /** AG Grid domLayout ΓÇö use 'autoHeight' when the grid is inside a container without a resolved pixel height (e.g. slideovers) */
  domLayout?: 'normal' | 'autoHeight' | 'print';
  /** Optional prefix for URL query parameters to avoid collisions when multiple grids exist on the same page */
  urlPrefix?: string;
}

/** Format numbers: integers stay as integers, decimals get 2 places */
export function numericFormatter(params: { value: unknown }) {
  if (params.value == null) return "";
  const n = Number(params.value);
  if (isNaN(n)) return String(params.value);
  return Number.isInteger(n)
    ? n.toLocaleString()
    : n.toLocaleString(undefined, {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
}

function getCellValue<T>(col: ColDef<T>, row: T) {
  let rawValue = col.field ? (row as any)[col.field] : undefined;
  if (col.valueGetter) {
    if (typeof col.valueGetter === 'function') {
      rawValue = col.valueGetter({ data: row, getValue: () => undefined } as any);
    }
  }

  let formattedValue = rawValue;
  if (col.valueFormatter) {
    if (typeof col.valueFormatter === 'function') {
      formattedValue = col.valueFormatter({ value: rawValue, data: row } as any);
    }
  }

  if (col.cellRenderer) {
    if (typeof col.cellRenderer === 'function') {
      const Renderer = col.cellRenderer as any;
      return <Renderer value={rawValue} data={row} />;
    }
  }

  return formattedValue ?? rawValue;
}

function GenericMobileCard<T>({ row, columns, onRowClicked }: { row: T; columns: ColDef<T>[]; onRowClicked?: (row: T) => void }) {
  const [expanded, setExpanded] = useState(false);
  const visibleCols = columns.filter(c => !c.hide);
  if (visibleCols.length === 0) return null;

  const primaryCol = visibleCols[0];
  const primaryVal = getCellValue(primaryCol, row);

  const secondaryCol = visibleCols.length > 1 ? visibleCols[1] : null;
  const secondaryVal = secondaryCol ? getCellValue(secondaryCol, row) : null;

  const restCols = visibleCols.slice(2);
  const validRestCols = restCols.map(col => ({ col, val: getCellValue(col, row) })).filter(item => item.val != null && item.val !== '');

  const displayLimit = 3;
  const isTruncated = validRestCols.length > displayLimit;
  const displayedCols = expanded ? validRestCols : validRestCols.slice(0, displayLimit);

  return (
    <div 
      className={`p-4 bg-white rounded-xl shadow-[0_2px_8px_rgba(0,0,0,0.04)] border border-slate-200 flex flex-col gap-3 transition-transform ${onRowClicked ? 'cursor-pointer active:scale-[0.98]' : ''}`}
      onClick={() => onRowClicked?.(row)}
    >
      <div className="flex justify-between items-start gap-4">
        <div>
          {secondaryVal && <div className="text-[11px] text-slate-500 font-bold tracking-wider uppercase mb-1">{primaryVal}</div>}
          <div className="text-[15px] font-bold text-[#041627] leading-tight">{secondaryVal || primaryVal}</div>
        </div>
      </div>
      
      {displayedCols.length > 0 && (
        <div className="flex flex-col gap-2 pt-3 border-t border-slate-100">
          {displayedCols.map(({col, val}, idx) => (
            <div key={col.field || col.headerName || idx} className="flex justify-between items-start gap-4 text-[13px]">
              <span className="text-slate-500">{col.headerName}</span>
              <span className="font-medium text-[#041627] text-right">{val}</span>
            </div>
          ))}
          {isTruncated && (
            <div 
              className="text-[13px] font-bold text-[var(--accent)] mt-1 pt-2 border-t border-slate-50 flex items-center justify-center gap-1 cursor-pointer hover:brightness-110"
              onClick={(e) => {
                e.stopPropagation();
                setExpanded(!expanded);
              }}
            >
              {expanded ? 'Show Less' : `+ ${validRestCols.length - displayLimit} More`}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default function DataGrid<T>({
  endpoint,
  rowData,
  columns,
  gridKey = "default-grid",
  searchPlaceholder,
  exportFileName = "export",
  apiFetch,
  onError,
  onRowClicked,
  fetchAll = false,
  showArchivedToggle = false,
  pageTitle,
  headerActions,
  headerFilters,
  renderHeader,
  gridTheme = "ag-theme-alpine-dark",
  initialSearch,
  rowIdField,
  rowSelection = "single",
  onSelectionChanged,
  refreshTrigger = 0,
  context,
  isRowSelectable,
  onDataLoaded,
  domLayout,
  urlPrefix,
}: DataGridProps<T>) {
  const tGrid = useTranslations('common.grid');
  const gridRef = useRef<AgGridReact<T>>(null);
  const pathname = usePathname();
  const searchParams = useSearchParams();

  const qParam = urlPrefix ? `${urlPrefix}_q` : 'q';
  const pageParam = urlPrefix ? `${urlPrefix}_page` : 'page';
  const archivedParam = urlPrefix ? `${urlPrefix}_archived` : 'archived';

  // Merge saved grid state (columns etc. from localStorage) + scroll (from sessionStorage)
  // into a single initialState ΓÇö read once on mount
  const savedInitialState = useMemo<GridState | undefined>(() => {
    if (!gridKey) return undefined;
    const gridState = loadGridState(gridKey);
    const scroll = loadScrollState(gridKey);
    if (!gridState && !scroll) return undefined;
    return {
      ...(gridState ?? {}),
      ...(scroll ? { scroll } : {}),
      partialColumnState: true, // we may not have all column properties
    };
  }, [gridKey]);

  const [data, setData] = useState<T[] | undefined>(undefined);
  const [internalRefresh, setInternalRefresh] = useState(0);

  useEffect(() => {
    if (!gridKey) return;
    const handler = () => setInternalRefresh((prev) => prev + 1);
    window.addEventListener(`grid-refresh-${gridKey}`, handler);
    return () => window.removeEventListener(`grid-refresh-${gridKey}`, handler);
  }, [gridKey]);

  const [displayedRowCount, setDisplayedRowCount] = useState<number>(0);
  const [loading, setLoading] = useState(true);
  const limit = fetchAll ? 99999 : 200;

  // Initialize state from URL params if available, falling back to defaults
  const [search, setSearch] = useState(() => searchParams?.get(qParam) ?? initialSearch ?? "");
  const [includeArchived, setIncludeArchived] = useState(() => searchParams?.get(archivedParam) === 'true');
  const [page, setPage] = useState(() => {
    const p = searchParams?.get(pageParam);
    return p ? parseInt(p, 10) || 1 : 1;
  });

  // We are fully restored from URL synchronously
  const isRestored = true;

  // Sync state FROM URL to local state (e.g., when user hits Back button)
  useEffect(() => {
    setSearch(searchParams?.get(qParam) ?? initialSearch ?? "");
    setIncludeArchived(searchParams?.get(archivedParam) === 'true');
    const p = searchParams?.get(pageParam);
    setPage(p ? parseInt(p, 10) || 1 : 1);
  }, [searchParams, qParam, archivedParam, pageParam, initialSearch]);

  // Sync local state TO URL (e.g., when user types or clicks next page)
  const firstRender = useRef(true);
  useEffect(() => {
    if (firstRender.current) {
      firstRender.current = false;
      return;
    }
    
    if (typeof window === 'undefined') return;
    
    // We only update if the local state actually differs from what's currently in the URL
    // to avoid infinite loops when syncing back from URL
    const currentQ = searchParams?.get(qParam) ?? "";
    const currentArchived = searchParams?.get(archivedParam) === 'true';
    const currentP = searchParams?.get(pageParam) ? parseInt(searchParams.get(pageParam)!, 10) : 1;
    
    if (search === currentQ && includeArchived === currentArchived && page === currentP) {
      return;
    }

    const params = new URLSearchParams(window.location.search);
    
    if (search) params.set(qParam, search);
    else params.delete(qParam);

    if (includeArchived) params.set(archivedParam, 'true');
    else params.delete(archivedParam);

    if (page > 1) params.set(pageParam, String(page));
    else params.delete(pageParam);

    const newUrl = `${window.location.pathname}${params.toString() ? `?${params.toString()}` : ''}${window.location.hash}`;
    window.history.replaceState(window.history.state, '', newUrl);
  }, [search, includeArchived, page, qParam, archivedParam, pageParam, searchParams]);

  /* ΓöÇΓöÇ Column picker dropdown state ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
  const [colPickerOpen, setColPickerOpen] = useState(false);
  const [colRevision, setColRevision] = useState(0);
  const colPickerRef = useRef<HTMLDivElement>(null);

  /* Close picker when clicking outside */
  useEffect(() => {
    if (!colPickerOpen) return;
    const handleClick = (e: MouseEvent) => {
      if (
        colPickerRef.current &&
        !colPickerRef.current.contains(e.target as Node)
      ) {
        setColPickerOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClick);
    return () => document.removeEventListener("mousedown", handleClick);
  }, [colPickerOpen]);

  /** Toggle a single column's visibility via the grid API */
  const toggleColumnVisible = useCallback((colId: string, visible: boolean) => {
    const api = gridRef.current?.api;
    if (!api) return;
    api.setColumnsVisible([colId], visible);
    setColRevision((r) => r + 1); // force re-render so checkbox reflects new state
    // state will be persisted via onStateUpdated
  }, []);

  /* Debounce timer ref for grid state persistence */
  const saveTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  /** Unified state persistence handler ΓÇö debounced.
   *  Fired by AG Grid whenever any state changes (columns, sort, scroll, etc.) */
  const onStateUpdated = useCallback(
    (event: StateUpdatedEvent) => {
      if (!gridKey) return;
      // Skip the initial state hydration event
      if (event.sources.includes('gridInitializing')) return;
      if (saveTimerRef.current) clearTimeout(saveTimerRef.current);
      saveTimerRef.current = setTimeout(() => {
        saveGridState(gridKey, event.state);
      }, 500);
    },
    [gridKey],
  );

  /* Cleanup debounce timer on unmount */
  useEffect(
    () => () => {
      if (saveTimerRef.current) clearTimeout(saveTimerRef.current);
    },
    [],
  );

  useEffect(() => {
    if (!isRestored) return; // wait until we have read sessionStorage

    if (rowData) {
      setData(rowData);
      setDisplayedRowCount(rowData.length);
      setLoading(false);
      return;
    }

    if (!endpoint) return;

    setLoading(true);
    const params = new URLSearchParams();
    params.set("page", String(page));
    params.set("limit", String(limit));
    if (search) params.set("q", search);
    if (includeArchived) params.set("includeArchived", "true");

    const separator = endpoint.includes('?') ? '&' : '?';
    apiFetch<{ data: T[] }>(`${endpoint}${separator}${params}`)
      .then((res) => {
        setData(res.data);
        setDisplayedRowCount(res.data.length);
        onDataLoaded?.(res.data);
      })
      .catch((err) => onError?.(err, "DataGrid"))
      .finally(() => setLoading(false));
  }, [endpoint, rowData, search, includeArchived, page, apiFetch, onError, refreshTrigger, internalRefresh, onDataLoaded, isRestored]);

  /** Enhance columns: add header tooltips, cell tooltips, and numeric parsing */
  const enhancedColumns = useMemo(
    () =>
      columns.map((col, colIndex) => {
        const isNumeric = col.type === "numericColumn";
        const base: ColDef<T> = {
          ...col,
          headerTooltip:
            col.headerTooltip ??
            col.headerName ??
            (col.field as string) ??
            undefined,
          // Cell tooltips for text columns ΓÇö show full value on hover
          ...(!isNumeric && col.field && !col.tooltipField
            ? { tooltipField: col.field as ColDefField<T> }
            : {}),
          // First column is always bold for visual anchoring
          ...(colIndex === 0
            ? {
              cellStyle: {
                fontWeight: 600,
                ...(typeof col.cellStyle === "object" &&
                  col.cellStyle !== null
                  ? col.cellStyle
                  : {}),
              },
            }
            : {}),
        };
        if (!isNumeric || !col.field) return base;
        const field = col.field;
        return {
          ...base,
          // Only add default valueGetter/valueFormatter if the column doesn't already have custom ones
          ...(col.valueGetter
            ? {}
            : {
              valueGetter: (params: { data?: Record<string, unknown> }) => {
                const v = params.data?.[field];
                if (v == null || v === "") return null;
                const n = Number(v);
                return isNaN(n) ? null : n;
              },
            }),
          ...(col.valueFormatter ? {} : { valueFormatter: numericFormatter }),
          filter: "agNumberColumnFilter",
        } as ColDef<T>;
      }),
    [columns],
  );

  const defaultColDef = useMemo<ColDef>(
    () => ({
      sortable: true,
      filter: true,
      resizable: true,
      minWidth: 80,
    }),
    [],
  );

  /** Auto-size columns on grid ready (initialState handles restoration) */
  const onGridReady = useCallback(
    (event: GridReadyEvent) => {
      // Only auto-size if there's no saved state ΓÇö otherwise initialState
      // has already applied the saved column widths/order
      if (!gridKey || !loadGridState(gridKey)) {
        event.api.autoSizeAllColumns();
      }
    },
    [gridKey],
  );

  /** Also auto-size when new data arrives (only if no saved state) */
  const onFirstDataRendered = useCallback(
    (event: FirstDataRenderedEvent) => {
      if (gridKey && loadGridState(gridKey)) return; // saved state takes priority
      event.api.autoSizeAllColumns();
    },
    [gridKey],
  );

  /** CSV export handler */
  const handleExport = useCallback(() => {
    gridRef.current?.api?.exportDataAsCsv({
      fileName: `${exportFileName ?? "export"}_${new Date().toISOString().slice(0, 10)}.csv`,
    });
  }, [exportFileName]);

  /** Reset columns to default layout */
  const handleResetColumns = useCallback(() => {
    if (gridKey) clearGridState(gridKey);
    gridRef.current?.api?.resetColumnState();
    gridRef.current?.api?.autoSizeAllColumns();
  }, [gridKey]);

  /** Row click handler ΓÇö snapshot scroll state before navigating away */
  const handleRowClicked = useCallback(
    (event: RowClickedEvent<T>) => {
      if (gridKey && event.api) {
        const state = event.api.getState();
        if (state.scroll) {
          saveScrollState(gridKey, state.scroll);
        }
      }
      if (onRowClicked && event.data) {
        onRowClicked(event.data);
      }
    },
    [onRowClicked, gridKey],
  );

  const searchInputNode = (
    <div className="relative flex items-center w-full">
      {/* eslint-disable-next-line i18next/no-literal-string */}
      <span className="material-symbols-outlined text-[18px] text-[var(--text-muted)] absolute left-3 pointer-events-none">search</span>
      <input
        className="w-full pl-9 pr-4 py-2 rounded-lg text-sm outline-none transition-all"
        style={{
          background: "#ffffff",
          border: "1px solid var(--border)",
          color: "var(--text-primary)",
        }}
        placeholder={searchPlaceholder ?? "SearchΓÇª"}
        value={search}
        onChange={(e) => {
          setSearch(e.target.value.trimStart());
          setPage(1);
        }}
        onFocus={(e) => e.target.style.borderColor = "var(--accent)"}
        onBlur={(e) => {
          e.target.style.borderColor = "var(--border)";
          setSearch(e.target.value.trim());
        }}
      />
    </div>
  );

  const optionsButtonNode = (
    <div ref={colPickerRef} style={{ position: "relative" }}>
      <button
        onClick={() => setColPickerOpen((v) => !v)}
        className="px-4 py-2 text-sm font-bold rounded-lg transition-colors flex items-center gap-2"
        style={{
          background: colPickerOpen ? "var(--bg-card-hover)" : "transparent",
          color: "var(--text-secondary)",
          border: "1px solid var(--border)",
        }}
        onMouseEnter={(e) => { if (!colPickerOpen) e.currentTarget.style.background = "var(--bg-card-hover)" }}
        onMouseLeave={(e) => { if (!colPickerOpen) e.currentTarget.style.background = "transparent" }}
        title={tGrid('options')}
      >
        {/* eslint-disable-next-line i18next/no-literal-string */}
        <span className="material-symbols-outlined text-[18px]">tune</span>{' '}{tGrid('options')}
      </button>
      {colPickerOpen && (
            <div
              style={{
                position: "absolute",
                top: "100%",
                right: 0,
                marginTop: 4,
                background: "var(--bg-card)",
                border: "1px solid var(--border)",
                borderRadius: 8,
                padding: "6px 0",
                zIndex: 50,
                minWidth: 200,
                maxHeight: 400,
                overflowY: "auto",
                boxShadow: "0 8px 24px rgba(0,0,0,0.4)",
              }}
            >
              {/* 1. Export Section */}
              <div
                style={{
                  padding: "2px 12px 4px",
                  fontSize: 11,
                  color: "var(--text-muted)",
                  fontWeight: 600,
                  textTransform: "uppercase",
                  letterSpacing: "0.05em",
                  marginTop: 4,
                }}
              >
                {tGrid('export')}
              </div>
              <button
                onClick={() => {
                  handleExport();
                  setColPickerOpen(false);
                }}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                  width: "100%",
                  padding: "6px 12px",
                  background: "transparent",
                  border: "none",
                  cursor: "pointer",
                  fontSize: 13,
                  color: "var(--text-primary)",
                  textAlign: "left",
                }}
                onMouseEnter={(e) =>
                  (e.currentTarget.style.background = "var(--bg-card-hover)")
                }
                onMouseLeave={(e) =>
                  (e.currentTarget.style.background = "transparent")
                }
              >
                <span aria-hidden>Γ¼ç</span>{' '}{tGrid('exportCsv')}
              </button>

              {/* 2. Columns Section */}
              {gridKey && (
                <>
                  <div
                    style={{
                      height: 1,
                      background: "var(--border)",
                      margin: "6px 0",
                    }}
                  />
                  <div
                    style={{
                      padding: "2px 12px 4px",
                      fontSize: 11,
                      color: "var(--text-muted)",
                      fontWeight: 600,
                      textTransform: "uppercase",
                      letterSpacing: "0.05em",
                    }}
                  >
                    {tGrid('columns')}
                  </div>
                  {columns.map((col) => {
                    const colId = (col.field ??
                      col.colId ??
                      col.headerName ??
                      "") as string;
                    if (!colId) return null;
                    const gridCol = gridRef.current?.api?.getColumn(colId);
                    const visible = gridCol ? gridCol.isVisible() : true;
                    return (
                      <label
                        key={colId}
                        style={{
                          display: "flex",
                          alignItems: "center",
                          gap: 8,
                          padding: "4px 12px",
                          cursor: "pointer",
                          fontSize: 13,
                          color: visible
                            ? "var(--text-primary)"
                            : "var(--text-muted)",
                        }}
                        onMouseEnter={(e) =>
                        (e.currentTarget.style.background =
                          "var(--bg-card-hover)")
                        }
                        onMouseLeave={(e) =>
                          (e.currentTarget.style.background = "transparent")
                        }
                      >
                        <input
                          type="checkbox"
                          checked={visible}
                          onChange={(e) =>
                            toggleColumnVisible(colId, e.target.checked)
                          }
                          style={{ accentColor: "var(--accent)" }}
                        />
                        {col.headerName ?? colId}
                      </label>
                    );
                  })}
                  <button
                    onClick={() => {
                      handleResetColumns();
                      setColPickerOpen(false);
                    }}
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 8,
                      width: "100%",
                      padding: "6px 12px",
                      background: "transparent",
                      border: "none",
                      cursor: "pointer",
                      fontSize: 13,
                      color: "var(--text-primary)",
                      textAlign: "left",
                    }}
                    onMouseEnter={(e) =>
                      (e.currentTarget.style.background = "var(--bg-card-hover)")
                    }
                    onMouseLeave={(e) =>
                      (e.currentTarget.style.background = "transparent")
                    }
                  >
                    {/* eslint-disable-next-line i18next/no-literal-string */}
                    <span aria-hidden>Γå╗</span>{' '}{tGrid('resetColumns')}
                  </button>
                </>
              )}

              {/* 3. Rows Section */}
              {showArchivedToggle && (
                <>
                  <div
                    style={{
                      height: 1,
                      background: "var(--border)",
                      margin: "6px 0",
                    }}
                  />
                  <div
                    style={{
                      padding: "2px 12px 4px",
                      fontSize: 11,
                      color: "var(--text-muted)",
                      fontWeight: 600,
                      textTransform: "uppercase",
                      letterSpacing: "0.05em",
                    }}
                  >
                    {tGrid('rowCountLabel')}
                  </div>
                  <label
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 8,
                      width: "100%",
                      padding: "6px 12px",
                      cursor: "pointer",
                      fontSize: 13,
                      color: "var(--text-primary)",
                    }}
                    onMouseEnter={(e) =>
                      (e.currentTarget.style.background = "var(--bg-card-hover)")
                    }
                    onMouseLeave={(e) =>
                      (e.currentTarget.style.background = "transparent")
                    }
                  >
                    <input
                      type="checkbox"
                      checked={includeArchived}
                      onChange={(e) => {
                        setIncludeArchived(e.target.checked);
                        setPage(1);
                      }}
                      style={{ accentColor: "var(--accent)" }}
                    />
                    {tGrid('includeArchived')}
                  </label>
                </>
              )}
            </div>
          )}
        </div>
  );


  const gridContent = (
    <div className="flex-1 lg:min-h-0 flex flex-col relative w-full lg:h-full">
      {!fetchAll && (
        <div className="flex gap-1 ml-auto shrink-0 mb-3 absolute top-0 right-0 z-10 p-2 bg-white/80 backdrop-blur-sm rounded-lg shadow-sm border border-slate-100">
          <button
            onClick={() => setPage((p) => Math.max(1, p - 1))}
            disabled={page === 1}
            className="px-3 py-1.5 rounded text-xs cursor-pointer disabled:opacity-30"
            style={{
              background: "var(--bg-card)",
              border: "1px solid var(--border)",
              color: "var(--text-secondary)",
            }}
          >
            <span aria-hidden>ΓåÉ</span>{' '}{tGrid('prev')}
          </button>
          <span
            className="px-3 py-1.5 text-xs"
            style={{ color: "var(--text-muted)" }}
          >
            {tGrid('page', { page: String(page) })}
          </span>
          <button
            onClick={() => setPage((p) => p + 1)}
            disabled={!data || data.length < limit}
            className="px-3 py-1.5 rounded text-xs cursor-pointer disabled:opacity-30"
            style={{
              background: "var(--bg-card)",
              border: "1px solid var(--border)",
              color: "var(--text-secondary)",
            }}
          >
            {tGrid('next')}{' '}<span aria-hidden>ΓåÆ</span>
          </button>
        </div>
      )}
      <div className="hidden lg:block flex-1 min-h-0 w-full h-full relative">
        <div className={`${gridTheme} absolute inset-0`}>
          <AgGridReact<T>
            ref={gridRef}
            rowData={data}
            columnDefs={enhancedColumns}
            defaultColDef={defaultColDef}
            animateRows
            rowSelection={rowSelection}
            isRowSelectable={isRowSelectable}
            context={context}
            {...(rowIdField ? { getRowId: (params) => String(params.data[rowIdField as keyof T]) } : {})}
            suppressScrollOnNewData={true}
            initialState={savedInitialState}
            onGridReady={onGridReady}
            onFirstDataRendered={onFirstDataRendered}
            onStateUpdated={onStateUpdated}
            onModelUpdated={(e) => setDisplayedRowCount(e.api.getDisplayedRowCount())}
            onRowClicked={onRowClicked ? handleRowClicked : undefined}
            onSelectionChanged={onSelectionChanged ? (e: SelectionChangedEvent<T>) => onSelectionChanged!(e.api.getSelectedRows()) : undefined}
            tooltipShowDelay={300}
            {...(domLayout ? { domLayout } : {})}
            {...(fetchAll ? { quickFilterText: search } : {})}
          />
        </div>
      </div>

      {/* Mobile Generic Card View */}
      <div className="lg:hidden flex-1 w-full flex flex-col gap-3 pb-24">
        {data?.map((row, idx) => {
          const key = rowIdField ? String((row as any)[rowIdField as keyof T]) : idx;
          return <GenericMobileCard key={key} row={row} columns={enhancedColumns} onRowClicked={onRowClicked} />;
        })}
      </div>
    </div>
  );

  if (pageTitle) {
    return (
      <div className="lg:h-full flex flex-col relative p-4 lg:p-6">
        <div className="relative lg:h-full flex flex-col">
          <div className="flex-1 lg:min-h-0 flex flex-col z-10 lg:bg-white lg:rounded-xl lg:shadow-[0_2px_8px_rgba(0,0,0,0.04)] lg:border lg:border-[rgba(196,198,205,0.4)] lg:overflow-hidden transition-all">
             <div className="flex flex-col lg:flex-row lg:items-center justify-between lg:px-6 py-4 gap-4">
                <div className="flex items-center justify-between lg:justify-start gap-4 w-full lg:w-auto">
                  <div className="flex items-center gap-4">
                    <h2 className="text-[1.3rem] font-bold tracking-tight text-[#041627] shrink-0" style={{ fontFamily: 'Manrope, sans-serif' }}>
                      {pageTitle}
                    </h2>
                    <div className="hidden lg:block h-5 w-px bg-[rgba(196,198,205,0.4)] shrink-0"></div>
                    <div className="hidden lg:flex items-center gap-2 px-3 py-1.5 bg-[#f2f4f6] rounded-lg shrink-0">
                      <span className="text-[11px] font-bold text-[#041627] tracking-wider uppercase" style={{ fontFamily: 'Manrope, sans-serif' }}>
                        {tGrid('rowCountLabel')}
                      </span>
                      <span className="text-[11px] font-bold text-[#006b5c]">
                        {loading ? '...' : displayedRowCount.toLocaleString()}
                      </span>
                    </div>
                  </div>
                  {headerActions && (
                    <div className="lg:hidden shrink-0">
                      {headerActions}
                    </div>
                  )}
                </div>
                
                <div className="flex items-center gap-3 w-full lg:w-auto relative">
                  <div className="flex-1 lg:max-w-[280px] lg:ml-6 transition-all duration-200 focus-within:absolute focus-within:inset-y-0 focus-within:left-0 focus-within:right-0 focus-within:z-20 lg:focus-within:static bg-[#f8fafc] lg:bg-transparent rounded-lg">
                    {searchInputNode}
                  </div>
                  <div className="shrink-0 flex items-center gap-3">
                    {headerFilters}
                    {optionsButtonNode}
                    {headerActions && (
                      <div className="hidden lg:block shrink-0">
                        {headerActions}
                      </div>
                    )}
                  </div>
                </div>
              </div>
             {gridContent}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col lg:h-full lg:bg-white relative">
      {renderHeader ? (
        renderHeader!({ searchInput: searchInputNode, optionsButton: optionsButtonNode, rowCount: displayedRowCount, loading })
      ) : (
        <div className="flex items-center gap-3">
          {searchInputNode}
          <span className="text-xs" style={{ color: "var(--text-muted)" }}>
            {loading ? tGrid('loadingEllipsis') : tGrid('rows', { count: String(displayedRowCount) })}
          </span>
          {optionsButtonNode}
        </div>
      )}
      {gridContent}
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { apiFetch, apiMutate } from '@/lib/api';
import { toast } from 'react-hot-toast';
import { useTranslations } from 'next-intl';
import SlideOver from './SlideOver';

interface ProductGroup {
  productGroupId: string;
  groupCode: string;
  name: string;
}

interface DiscountRule {
  discountMatrixId: string;
  customerGroupId: string | null;
  customerId: string | null;
  productGroupId: string | null;
  discountPercentage: string;
}

interface DiscountMatrixSlideOverProps {
  open: boolean;
  onClose: () => void;
  ownerLabel: string;
  customerGroupId?: string;
  customerId?: string;
}

export default function DiscountMatrixSlideOver({
  open,
  onClose,
  ownerLabel,
  customerGroupId,
  customerId,
}: DiscountMatrixSlideOverProps) {
  const t = useTranslations('admin.discountMatrix');
  const tCommon = useTranslations('common');

  const [rules, setRules] = useState<DiscountRule[]>([]);
  const [productGroups, setProductGroups] = useState<ProductGroup[]>([]);
  const [loading, setLoading] = useState(false);

  // New rule form
  const [newProductGroupId, setNewProductGroupId] = useState('');
  const [newDiscount, setNewDiscount] = useState('');

  const ownerId = customerGroupId || customerId || '';
  const ownerParam = customerGroupId
    ? `customerGroupId=${customerGroupId}`
    : `customerId=${customerId}`;

  const loadData = useCallback(async () => {
    if (!ownerId) return;
    setLoading(true);
    try {
      const [rulesData, pgData] = await Promise.all([
        apiFetch<DiscountRule[]>(`/api/discount-matrix?${ownerParam}`),
        apiFetch<ProductGroup[]>('/api/product-groups'),
      ]);
      setRules(rulesData || []);
      setProductGroups(pgData || []);
    } catch (err: any) {
      toast.error('Failed to load discount rules: ' + err.message);
    } finally {
      setLoading(false);
    }
  }, [ownerId, ownerParam]);

  useEffect(() => {
    if (open) loadData();
  }, [open, loadData]);

  // The wildcard rule (product_group = null)
  const wildcardRule = rules.find((r) => r.productGroupId === null);
  // Product-group-specific rules
  const specificRules = rules.filter((r) => r.productGroupId !== null);

  // Product groups that don't yet have a rule
  const availableProductGroups = productGroups.filter(
    (pg) => !specificRules.some((r) => r.productGroupId === pg.productGroupId),
  );

  const handleSaveWildcard = async (value: string) => {
    try {
      if (wildcardRule) {
        await apiMutate(
          `/api/discount-matrix/${wildcardRule.discountMatrixId}`,
          'PATCH',
          { discountPercentage: value },
        );
      } else {
        await apiMutate('/api/discount-matrix', 'POST', {
          customerGroupId: customerGroupId || undefined,
          customerId: customerId || undefined,
          discountPercentage: value,
        });
      }
      toast.success(t('toasts.saved'));
      loadData();
    } catch (err: any) {
      toast.error(err.message);
    }
  };

  const handleSaveSpecific = async (ruleId: string, value: string) => {
    try {
      await apiMutate(`/api/discount-matrix/${ruleId}`, 'PATCH', {
        discountPercentage: value,
      });
      toast.success(t('toasts.saved'));
      loadData();
    } catch (err: any) {
      toast.error(err.message);
    }
  };

  const handleAdd = async () => {
    if (!newDiscount) return;
    try {
      await apiMutate('/api/discount-matrix', 'POST', {
        customerGroupId: customerGroupId || undefined,
        customerId: customerId || undefined,
        productGroupId: newProductGroupId || undefined,
        discountPercentage: newDiscount,
      });
      toast.success(t('toasts.saved'));
      setNewProductGroupId('');
      setNewDiscount('');
      loadData();
    } catch (err: any) {
      toast.error(err.message);
    }
  };

  const handleDelete = async (ruleId: string) => {
    try {
      await apiMutate(`/api/discount-matrix/${ruleId}`, 'DELETE');
      toast.success(t('toasts.deleted'));
      loadData();
    } catch (err: any) {
      toast.error(err.message);
    }
  };

  return (
    <SlideOver
      isOpen={open}
      onClose={onClose}
      title={t('title')}
      subtitle={ownerLabel}
    >
      <div className="flex flex-col gap-8">
        {loading ? (
          <p className="text-sm" style={{ color: 'var(--text-muted)' }}>
            {tCommon('loading')}
          </p>
        ) : (
          <>
            {/* Wildcard (Base) Discount */}
            <div>
              <label
                className="text-xs font-semibold mb-2 block"
                style={{
                  color: 'var(--text-muted)',
                  textTransform: 'uppercase',
                  letterSpacing: '0.05em',
                }}
              >
                {t('baseDiscount')}
              </label>
              <div className="flex gap-2 items-center">
                <div className="relative">
                  <input
                    className="input pr-6"
                    style={{ width: 100 }}
                    type="number"
                    step="0.01"
                    defaultValue={wildcardRule?.discountPercentage ?? '0'}
                    onBlur={(e) => handleSaveWildcard(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter')
                        handleSaveWildcard((e.target as HTMLInputElement).value);
                    }}
                  />
                  <span className="absolute right-2 top-1/2 -translate-y-1/2 text-xs font-medium text-gray-500">%</span>
                </div>
              </div>
            </div>

            {/* Product Group Rules */}
            <div>
              <label
                className="text-xs font-semibold mb-2 block"
                style={{
                  color: 'var(--text-muted)',
                  textTransform: 'uppercase',
                  letterSpacing: '0.05em',
                }}
              >
                {t('productGroupRules')}
              </label>

              <table className="table-lines w-full text-sm">
                <thead>
                  <tr>
                    <th className="text-left font-semibold text-xs tracking-wider text-gray-500 uppercase">{t('productGroup')}</th>
                    <th className="text-left font-semibold text-xs tracking-wider text-gray-500 uppercase" style={{ width: 120 }}>{t('discountPercent')}</th>
                    <th style={{ width: 60, textAlign: 'right' }}></th>
                  </tr>
                </thead>
                <tbody>
                  {specificRules.map((r) => {
                    const pg = productGroups.find(
                      (p) => p.productGroupId === r.productGroupId,
                    );
                    return (
                      <tr key={r.discountMatrixId}>
                        <td className="font-mono text-xs">
                          {pg ? `${pg.groupCode} ΓÇö ${pg.name}` : r.productGroupId}
                        </td>
                        <td>
                          <div className="relative">
                            <input
                              className="input pr-6"
                              type="number"
                              step="0.01"
                              defaultValue={r.discountPercentage}
                              style={{ width: 100 }}
                              onBlur={(e) =>
                                handleSaveSpecific(r.discountMatrixId, e.target.value)
                              }
                              onKeyDown={(e) => {
                                if (e.key === 'Enter')
                                  handleSaveSpecific(
                                    r.discountMatrixId,
                                    (e.target as HTMLInputElement).value,
                                  );
                              }}
                            />
                            <span className="absolute right-2 top-1/2 -translate-y-1/2 text-xs font-medium text-gray-500">%</span>
                          </div>
                        </td>
                        <td style={{ textAlign: 'right' }}>
                          <button
                            className="btn btn-ghost btn-xs text-gray-400 hover:text-gray-800"
                            onClick={() => handleDelete(r.discountMatrixId)}
                            title={tCommon('delete')}
                          >
                            <span className="material-symbols-outlined text-base">
                              close
                            </span>
                          </button>
                        </td>
                      </tr>
                    );
                  })}

                  {/* Add new rule row */}
                  {availableProductGroups.length > 0 && (
                    <tr style={{ background: 'var(--bg-secondary)' }}>
                      <td>
                        <select
                          className="input text-xs w-full"
                          value={newProductGroupId}
                          onChange={(e) => setNewProductGroupId(e.target.value)}
                        >
                          <option value="">{t('selectProductGroup')}</option>
                          {availableProductGroups.map((pg) => (
                            <option key={pg.productGroupId} value={pg.productGroupId}>
                              {pg.groupCode} ΓÇö {pg.name}
                            </option>
                          ))}
                        </select>
                      </td>
                      <td>
                        <div className="relative">
                          <input
                            className="input pr-6"
                            type="number"
                            step="0.01"
                            value={newDiscount}
                            onChange={(e) => setNewDiscount(e.target.value)}
                            placeholder="0"
                            style={{ width: 100 }}
                          />
                          <span className="absolute right-2 top-1/2 -translate-y-1/2 text-xs font-medium text-gray-500">%</span>
                        </div>
                      </td>
                      <td style={{ textAlign: 'right' }}>
                        <button
                          className="btn btn-primary btn-xs"
                          onClick={handleAdd}
                          disabled={!newProductGroupId || !newDiscount}
                        >
                          <span className="material-symbols-outlined text-base">add</span>
                        </button>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </>
        )}
      </div>
    </SlideOver>
  );
}

import React from 'react';

export interface FormFieldProps {
  type: 'string' | 'number' | 'integer' | 'boolean' | 'enum';
  title: string;
  value: any;
  onChange: (val: any) => void;
  required?: boolean;
  readOnly?: boolean;
  options?: string[]; // For enum
  description?: string;
}

export const FormField: React.FC<FormFieldProps> = ({
  type,
  title,
  value,
  onChange,
  required,
  readOnly,
  options,
  description,
}) => {
  if (type === 'boolean') {
    return (
      <div className="flex items-center gap-4">
        <label className="text-sm font-medium text-muted w-48 shrink-0">
          {title} {required && <span className="text-[var(--danger)]">*</span>}
        </label>
        <label className="switch" title={title}>
          <input
            type="checkbox"
            checked={Boolean(value)}
            onChange={(e) => onChange(e.target.checked)}
            disabled={readOnly}
          />
          <span className="switch-slider"></span>
        </label>
      </div>
    );
  }

  if (type === 'number' || type === 'integer') {
    return (
      <div className="flex items-center gap-4">
        <label className="text-sm font-medium text-muted w-48 shrink-0">
          {title} {required && <span className="text-[var(--danger)]">*</span>}
        </label>
        <input
          type="number"
          className="input flex-1"
          value={value ?? ''}
          onChange={(e) => onChange(e.target.value === '' ? '' : Number(e.target.value))}
          disabled={readOnly}
          placeholder={description || ''}
        />
      </div>
    );
  }

  if (type === 'enum' || (options && options.length > 0)) {
    return (
      <div className="flex items-center gap-4">
        <label className="text-sm font-medium text-muted w-48 shrink-0">
          {title} {required && <span className="text-[var(--danger)]">*</span>}
        </label>
        <select
          className="input flex-1"
          value={value ?? ''}
          onChange={(e) => onChange(e.target.value)}
          disabled={readOnly}
        >
          <option value="">-- Select --</option>
          {(options || []).map((opt: string) => (
            <option key={opt} value={opt}>
              {opt}
            </option>
          ))}
        </select>
      </div>
    );
  }

  // Default to string
  return (
    <div className="flex items-center gap-4">
      <label className="text-sm font-medium text-muted w-48 shrink-0">
        {title} {required && <span className="text-[var(--danger)]">*</span>}
      </label>
      <input
        type="text"
        className="input flex-1"
        value={value ?? ''}
        onChange={(e) => onChange(e.target.value)}
        disabled={readOnly}
        placeholder={description || ''}
      />
    </div>
  );
};

'use client';

import { useState, useRef, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { apiFetch } from '../../lib/api';

interface POLine {
  purchaseOrderLineId: string;
  orderNumber: string;
  quantity: string;
  quantityReceived: string;
  vendorName?: string;
}

interface POLineSearchInputProps {
  productId?: string;
  vendorId?: string;
  onSelect: (poLineId: string, line?: any) => void;
  placeholder?: string;
  style?: React.CSSProperties;
}

export default function POLineSearchInput({
  productId,
  vendorId,
  onSelect,
  placeholder = 'Search POs...',
  style,
}: POLineSearchInputProps) {
  const [search, setSearch] = useState('');
  const [results, setResults] = useState<POLine[]>([]);
  const [allLines, setAllLines] = useState<POLine[]>([]);
  const [showDropdown, setShowDropdown] = useState(false);
  const [loading, setLoading] = useState(false);
  const [dropdownStyle, setDropdownStyle] = useState<React.CSSProperties>({});
  
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!productId && !vendorId) return;
    setLoading(true);
    let url = `/api/purchase-orders/pending-lines?`;
    const params = new URLSearchParams();
    if (productId) params.append('productId', productId);
    if (vendorId) params.append('vendorId', vendorId);
    url += params.toString();
    
    apiFetch<any>(url)
      .then((data) => {
        const lines = Array.isArray(data) ? data : data.data || [];
        setAllLines(lines);
        setResults(lines);
        if (lines.length > 0) {
          setShowDropdown(true);
        }
      })
      .catch(() => {
        setAllLines([]);
        setResults([]);
      })
      .finally(() => setLoading(false));
  }, [productId, vendorId]);

  const updateDropdownPosition = () => {
    if (inputRef.current) {
      const rect = inputRef.current.getBoundingClientRect();
      setDropdownStyle({
        top: rect.bottom + 4,
        left: rect.left,
        width: Math.max(rect.width, 200),
      });
    }
  };

  useEffect(() => {
    if (showDropdown) {
      updateDropdownPosition();
      window.addEventListener('scroll', updateDropdownPosition, true);
      window.addEventListener('resize', updateDropdownPosition);
      return () => {
        window.removeEventListener('scroll', updateDropdownPosition, true);
        window.removeEventListener('resize', updateDropdownPosition);
      };
    }
  }, [showDropdown]);

  const handleSearch = (term: string) => {
    setSearch(term);
    setShowDropdown(true);
    if (!term) {
      setResults(allLines);
    } else {
      const lower = term.toLowerCase();
      setResults(
        allLines.filter(
          (l) =>
            l.orderNumber?.toLowerCase().includes(lower) ||
            l.vendorName?.toLowerCase().includes(lower)
        )
      );
    }
  };

  const handleSelect = (line: POLine) => {
    setShowDropdown(false);
    setSearch(line.orderNumber);
    onSelect(line.purchaseOrderLineId, line);
  };

  const dropdownContent = showDropdown ? (
    <div
      className="z-50 rounded-lg overflow-hidden max-h-48 scroll-area"
      style={{
        position: 'fixed',
        background: 'var(--bg-card)',
        border: '1px solid var(--border)',
        boxShadow: '0 8px 32px rgba(0,0,0,0.4)',
        ...dropdownStyle
      }}
    >
      {results.map((p) => {
        const qtyPending = parseFloat(p.quantity || '0') - parseFloat(p.quantityReceived || '0');
        return (
          <div
            key={p.purchaseOrderLineId}
            className="px-3 py-2 cursor-pointer text-sm hover:bg-[var(--bg-card-hover)]"
            style={{ borderBottom: '1px solid rgba(30,58,95,0.3)' }}
            onMouseDown={() => handleSelect(p)}
          >
            <div className="flex flex-col gap-1 pt-1 pb-0.5">
              <div style={{ minWidth: 0 }}>
                <span style={{ color: 'var(--accent)', fontWeight: 600 }}>
                  {p.orderNumber}
                </span>
                {p.vendorName && (
                  <span style={{ color: 'var(--text-secondary)', marginLeft: 8, fontSize: 12 }}>
                    {p.vendorName}
                  </span>
                )}
              </div>
              <div style={{ fontSize: 11, color: 'var(--text-muted)' }}>
                Pending Qty: <span style={{ fontWeight: 600, color: 'var(--text-primary)' }}>{qtyPending}</span>
              </div>
            </div>
          </div>
        );
      })}
      {results.length === 0 && !loading && (
        <div className="px-3 py-3 text-sm" style={{ color: 'var(--text-muted)' }}>
          No pending POs found.
        </div>
      )}
    </div>
  ) : null;

  return (
    <div className="relative" style={style}>
      <input
        ref={inputRef}
        className="input"
        autoFocus
        style={{ width: '100%', fontSize: 12, padding: '4px 8px', height: 26 }}
        placeholder={loading ? 'Loading POs...' : placeholder}
        value={search}
        onChange={(e) => handleSearch(e.target.value.trimStart())}
        onFocus={() => setShowDropdown(true)}
        onBlur={(e) => {
          setSearch(e.target.value.trim());
          setTimeout(() => setShowDropdown(false), 200);
        }}
        disabled={loading}
      />
      {typeof document !== 'undefined' && showDropdown && createPortal(dropdownContent, document.body)}
    </div>
  );
}

